INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('andrea-mantegna', 'Andrea Mantegna', '{}', 1431, 1506, '{}', 'pittore di corte', 'A partire dal 1460 lavora per oltre quarant''anni per la famiglia Gonzaga a Mantova, prima per Ludovico III (1444-1478), poi per il figlio Federico (1478-1484) e il nipote Francesco II (1484-1519). I dipinti prodotti in questo lungo periodo risultano complessivamente pochi: l''artista è sovrattutto impegnato in disegni per arazzi, cassoni, oreficerie e miniature, oltre che nella supervisione delle diverse squadre di artisti impiegate nei cantieri edilizi della città.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('squarcione', 'Squarcione', '{}', NULL, NULL, '{}', 'pittore e maestro d''arte', 'Maestro di Andrea Mantegna a Padova, nella cui bottega Mantegna si formò per circa dieci anni prima di sviluppare uno stile personale distaccato.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('gentile-bellini', 'Gentile Bellini', '{}', 1429, 1507, '{}', 'pittore', 'Figlio maggiore di Jacopo, si distingue come abile ritrattista e autore di edifici pubblici e religiosi, fino ad assumere il ruolo di pittore ufficiale della Serenissima. Nel 1479 viene invitato a Costantinopoli per ritrarre il sultano Maometto II. Capolavoro della sua maturità sono tre teleri dipinti dal 1493 per l''Oraorio della Scuola Grande di San Giovanni Evangelista.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('giovanni-bellini', 'Giovanni Bellini', '{}', 1430, 1516, '{}', 'pittore', 'Figlio minore di Jacopo Bellini, inizia il suo apprendistato nella bottega paterna insieme al fratello Gentile. Nel 1453 sposa Nicolosia, sorella di Andrea Mantegna, subendo forti influenze dal cognato. Sviluppa uno stile caratterizzato dall''uso della luce, forme piene e geometriche e interesse per colore a olio. Diventa pittore ufficiale della Serenissima nel 1483. Muore a Venezia nel 1516.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('ludovico-gonzaga', 'Ludovico Gonzaga', '{}', 1412, 1478, '{}', 'committente', 'Marchese di Mantova, che invitò Andrea Mantegna a trasferirsi definitivamente a Mantova nel 1460 assumendolo come pittore di corte.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('donatello', 'Donatello', '{}', 1386, 1466, '{}', 'scultore', 'Grande scultore fiorentino, le cui opere tarde (come la Maddalena penitente) esercitarono una forte influenza sulla cultura figurativa bolognese del secondo Quattrocento, in particolare su Ercole de'' Roberti e Niccolò dell''Arca.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('filippo-lippi', 'Filippo Lippi', '{}', 1406, 1469, '{}', 'pittore', 'Artista toscano presente a Padova, influenza per il giovane Mantegna.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('andrea-del-castagno', 'Andrea del Castagno', '{}', 1421, 1457, '{}', 'pittore', 'Pittore toscano giunto in laguna veneta, il cui stile non modifica significativamente quello dei pittori locali come i Vivarini.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('paolo-uccello', 'Paolo Uccello', '{}', 1397, 1475, '{}', 'pittore', 'Pittore toscano presente in laguna veneta, citato tra gli artisti che non modificano significativamente lo stile locale.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('giovanni-dalemagna', 'Giovanni d''Alemagna', '{}', 1411, 1450, '{}', 'pittore', 'Cognato di Antonio Vivarini, collabora strettamente con lui. Si rivela ben presto aperto alla cultura padovana, dalla quale acquisisce le forme della solidità volumetrica e la linea grafica.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('antonio-vivarini', 'Antonio Vivarini', '{}', 1420, 1484, '{}', 'pittore', 'Fondatore della bottega dei Vivarini a Murano intorno al 1440, realizza sonnose e imponenti politici dominati da fondi dorati e cornici floreali, riccamente intagliate da abili ebanisti.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('niccolo-pizzolo', 'Niccolò Pizzolo', '{}', NULL, 1453, '{}', 'pittore', 'Pittore padovano del secondo gruppo di artisti della cappella Ovetari, collaboratore precedente di Filippo Lippi e Donatello, morto nel 1453.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('piero-della-francesca', 'Piero della Francesca', '{}', 1415, 1492, '{}', 'pittore', 'Pittore toscano citato come riferimento per l''articolazione spaziale e l''illuminazione laterale delle figure nel Polittico Griffoni.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('francesco-squarcione', 'Francesco Squarcione', '{}', 1397, 1474, '{}', 'pittore e maestro d''arte', 'Maestro di Mantegna, noto per lo stile caratterizzato da festoni di frutti e foglie che potevano apparire o al loggiato.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('gregorio-correr', 'Gregorio Correr', '{}', NULL, NULL, '{}', 'committente, abate', 'Abate di San Zeno a Verona, committente della Pala di San Zeno di Mantegna nel 1443.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('ludovico-iii-gonzaga', 'Ludovico III Gonzaga', '{}', 1412, 1478, '{}', 'committente', 'Signore di Mantova dal 1444, committente della Camera degli Spati e protettore di artisti e umanisti. Rappresentato come figura centrale negli affreschi di Mantegna.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('leon-battista-alberti', 'Leon Battista Alberti', '{}', 1404, 1472, '{}', 'architetto, umanista, teorico dell''arte', 'Teorico dell''architettura rinascimentale, autore del ''De re aedificatoria''. Il suo trattato, scritto circa dieci anni prima di quello di Filarete, si basa su principi armonici ed estetici naturali, costituendo un riferimento per la trattatistica architettonica successiva.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('vittore-da-feltre', 'Vittore da Feltre', '{}', 1378, 1446, '{}', 'umanista, pedagogo', 'Fondatore della scuola Ca'' Zoiosa (Gioiosa) a Mantova, precursore dell''educazione umanistica. I suoi principi pedagogici influenzarono la cultura della corte gonzaghesca.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('barbara-di-brandeburgo', 'Barbara di Brandeburgo', '{}', 1422, 1481, '{}', 'marchesa di Mantova', 'Moglie di Ludovico III Gonzaga, figura centrale della corte mantovana, mecenate e protagonista delle scene celebrative dipinte da Mantegna nella Camera degli Sposi.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('francesco-sforza', 'Francesco Sforza', '{}', 1401, 1466, '{}', 'duca di Milano', 'Primo duca di Milano della dinastia Sforzesca, salì al potere nel 1450. Committente delle principali opere architettoniche milanesi del Quattrocento, tra cui il Castello Sforzesco e l''Ospedale Maggiore.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('cristoforo-da-dianque', 'Cristoforo da Dianquè', '{}', NULL, NULL, '{}', 'segretario', 'Segretario di Federico Gonzaga, presente nella scena dell''Incontro tra Federico e il cardinale Francesco Gonzaga.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('federico-gonzaga', 'Federico Gonzaga', '{}', 1441, 1484, '{}', 'cardinale, figlio di Ludovico III', 'Figlio di Ludovico III Gonzaga, creato cardinale nel 1463. Protagonista della scena dell''Incontro con il padre rappresentata sulla parete nord della Camera degli Sposi.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('vittorino-da-feltre', 'Vittorino da Feltre', '{}', 1378, 1446, '{}', 'umanista, pedagogo', 'Famoso educatore umanista, fondatore della ''Casa Giocosa'' a Mantova, simbolo del prestigio intellettuale della corte gonzaghesca.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('francesco-gonzaga', 'Francesco Gonzaga', '{}', 1466, 1519, '{}', 'cardinale', 'Figlio di Ludovico Gonzaga, cardinale della Chiesa cattolica, ritratto nelle scene mitologiche come garante dei legami con il papato.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('federico-iii-dasburgo', 'Federico III d''Asburgo', '{}', 1415, 1493, '{}', 'imperatore del Sacro Romano Impero', 'Imperatore del Sacro Romano Impero, presente nell''iconografia della Camera degli Sposi come riconoscimento dell''autorità imperiale sui Gonzaga.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('cristiano-di-danimarca', 'Cristiano di Danimarca', '{}', NULL, NULL, '{}', 'principe', 'Cognato di Ludovico Gonzaga, presente nella scena dell''Incontro.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('isabella-deste', 'Isabella d''Este', '{}', 1474, 1539, '{}', 'marchesa, committente', 'Figlia di Ercole I duca di Ferrara e moglie del marchese Francesco II Gonzaga. Grande collezionista d''arte e mecenate, creò uno studiolo privato a Mantova tra il 1490-1497 con la collaborazione dei maggiori artisti dell''epoca.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('alfonso-daragona', 'Alfonso d''Aragona', '{}', 1396, 1458, '{}', 'Sovrano e mecenate', 'Re di Napoli dal 1443 al 1458, unificò il regno di Napoli con quello di Sicilia. Grande mecenate, mantenne forte passione per la cultura delle Fiandre, collezionando opere dei più importanti artisti nordici del tempo. Chiamò a corte Pisanello come medaglista tra il 1448 e il 1449.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('pisanello', 'Pisanello', '{}', 1395, 1455, '{}', 'Pittore e medaglista', 'Artista attivo alla corte di Alfonso d''Aragona tra il 1448 e il 1449 in qualità di medaglista. Realizzò numerose medaglie per Alfonso d''Aragona, collaborando con la bottega. La sua attività è testimoniata da numerosi studi per dipinti, sculture e tessuti.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('jan-van-eyck', 'Jan van Eyck', '{}', NULL, NULL, '{}', 'Pittore fiammingo', 'Artista nordico le cui opere erano presenti nelle collezioni di Alfonso d''Aragona e studiate direttamente dagli artisti napoletani.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('jean-fouquet', 'Jean Fouquet', '{}', NULL, NULL, '{}', 'Pittore francese', 'Giunse a Roma nel 1444 e si spinse fino a Napoli tra il 1452 e il 1458, raffigurando la Passione di Cristo su cartoni che furono poi utilizzati da Rogier van der Weyden.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('rogier-van-der-weyden', 'Rogier van der Weyden', '{}', NULL, NULL, '{}', 'Pittore fiammingo', 'Realizzò una serie di arazzi raffiguranti la Passione di Cristo su cartoni di Jean Fouquet.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('guillem-sagrera', 'Guillem Sagrera', '{}', 1380, 1454, '{}', 'Architetto catalano', 'Catalano che diresse i lavori di rinnovamento del Castel Nuovo (Maschio Angioino) iniziati da Alfonso d''Aragona, trasformandolo da fortezza a residenza adatta a ospitare la corte.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('francesco-di-giorgio-martini', 'Francesco di Giorgio Martini', '{}', NULL, NULL, '{}', 'Architetto e urbanista', 'Coinvolto nei progetti di riorganizzazione della città di Napoli durante il regno aragonese.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('ferdinando-i-daragona-ferrante', 'Ferdinando I d''Aragona (Ferrante)', '{}', NULL, 1494, '{}', 'Sovrano', 'Figlio di Alfonso, regnò dal 1458 al 1494. Protagonista di un''apertura nei confronti del gusto rinascimentale italiano, con preferenza per i modelli toscani. Alleato con Lorenzo il Magnifico, promosse l''arrivo di artisti fiorentini a Napoli.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('benedetto-da-maiano-benedetto-da-firenze', 'Benedetto da Maiano (Benedetto da Firenze)', '{}', 1442, 1497, '{}', 'Scultore e architetto fiorentino', 'Artista fiorentino chiamato a Napoli nel 1490 per realizzare il Monumento funebre di Alfonso d''Aragona nella cappella Piccolomini della chiesa di Sant''Anna dei Lombardi.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('antonio-rossellino', 'Antonio Rossellino', '{}', 1427, 1479, '{}', 'Scultore fiorentino', 'Scultore e architetto fiorentino, fratello di Bernardo Rossellino. Collaborò con Benedetto da Maiano alla realizzazione della cappella Piccolomini e del monumento funebre di Maria d''Aragona.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('benedetto-da-maiano', 'Benedetto da Maiano', '{}', 1442, 1497, '{}', 'architetto e scultore', 'Architetto e scultore fiorentino, attivo principalmente a Napoli nella seconda metà del Quattrocento. Lavorò alla cappella Piccolomini tra il 1475 e il 1490.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('giuliano-da-maiano', 'Giuliano da Maiano', '{}', 1432, 1490, '{}', 'architetto e scultore', 'Architetto e scultore fiorentino, fratello maggiore di Benedetto da Maiano. Progettò la Porta Capuana a Napoli nel 1484, applicando il modello classico degli archi di trionfo romani.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('pietro-di-martino-da-milano', 'Pietro di Martino da Milano', '{}', NULL, NULL, '{}', 'architetto/scultore', 'Architetto e scultore attivo a Napoli nella corte aragonese, collaboratore di Francesco Laurana per l''Arco trionfale di Castel Nuovo', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('francesco-laurana', 'Francesco Laurana', '{}', 1430, 1502, '{}', 'scultore/architetto', 'Scultore dalmata attivo in Italia meridionale e Francia. Arrivò a Napoli verso il 1453, lavorando per Renato d''Angiò come medaglista. Si trasferì in Sicilia nel 1468. Il suo stile si distingue per la cura dei dettagli, la resa nervosa dei panneggi derivata dalla scultura borgognona e l''eccezionale abilità tecnica che gli permette di modificare il linguaggio secondo il contesto. Realizzò una serie di busti-ritratto dedicati a principesse e nobildonne caratterizzati da volumi puri, stilizzazione geometrica, lineamenti idealizzati e superfici levigate, probabilmente ispirati alla pittura di Piero della Francesca e Antonello da Messina.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('colantonio', 'Colantonio', '{}', 1420, 1470, '{}', 'pittore', 'Pittore proprietario di un''influente bottega a Napoli nel XV secolo. La sua formazione avvenne durante il regno di Renato d''Angiò (1435-1442), dimostrando un''interpretazione iniziale delle novità fiamminghe in chiave franco-angioina, influenzata dalla presenza in città di Barthélemy d''Eyck. Sotto gli Aragonesi entrò in contatto con Jean Fouquet e studiò direttamente le opere di Jan van Eyck e Rogier van der Weyden, modificando il proprio stile allineandosi con i modelli della cultura valenciana. Nel periodo aragonese (dopo il 1445) realizzò opere per la chiesa franciscana di San Lorenzo Maggiore, tra cui San Gerolamo nello studio e San Francesco consegna la regola agli ordini francescani.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('antonello-da-messina', 'Antonello da Messina', '{}', 1430, 1479, '{}', 'pittore', 'Antonello di Antonio, detto Antonello da Messina (1430 circa-1479), si forma nella bottega di Colantonio a Napoli, fiorente centro commerciale che lo mette in contatto con le opere fiamminghe. La precisione nordica per il dettaglio si traduce nei numerosi ritratti che l''artista realizza durante la sua carriera, come il Ritratto virile. Alterna soggiorni in Sicilia a viaggi nei principali centri italiani, assimilando le novità artistiche delle varie città e contribuendo allo sviluppo delle scuole locali. Intorno al 1459 compie un viaggio a Roma da cui le sue opere iniziano ad essere organizzate secondo corrette impostazioni geometriche e prospettiche, mentre le figure assumono una saldezza volumetrica e monumentale certamente dipendente dalla lezione di Piero della Francesca. Un''altra esperienza fondamentale è il soggiorno veneziano del 1474-1476, anni in cui Antonello perfeziona lo studio della luce e raggiunge la piena potenza espressiva, evidente in particolare nel San Sebastiano e nel San Gerolamo nello studio. Il nutrito bagaglio di esperienze personali di questi anni porta Antonello a mescolare con sapiente equilibrio gli stimoli fiamminghi, catalani, provenzali e francesi della formazione napoletana e siciliana, con i modelli ormai consolidati della pittura del maturo Rinascimento italiano.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('nicola-da-bari', 'Nicola da Bari', '{}', NULL, NULL, '{}', 'santo', 'Santo le cui figure originali erano inserite in una struttura architettonica classicheggiante, secondo una ricostruzione novecentesca.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('van-eyck', 'Van Eyck', '{}', 1390, 1441, '{}', 'pittore', 'Pittore fiammingo la cui opera fu documentata a Napoli dal 1456 e costituì un importante punto di riferimento per Antonello da Messina.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('pietro-solari', 'Pietro Solari', '{}', 1435, 1515, '{}', 'scultore e architetto', 'Detto Lombardo, attivo a Padova e forse soggiornato in Toscana, si stabilisce a Venezia alla fine degli anni sessanta del Quattrocento. Dà vita a una delle più fiorenti botteghe della città con i figli Tullio e Antonio.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('tullio-lombardo', 'Tullio Lombardo', '{}', 1460, 1532, '{}', 'scultore', 'Figlio di Pietro Solari (Lombardo), attivo nella bottega paterna a Venezia.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('antonio-lombardo', 'Antonio Lombardo', '{}', 1458, 1516, '{}', 'scultore', 'Figlio di Pietro Solari (Lombardo), attivo nella bottega paterna a Venezia.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('mauro-codussi', 'Mauro Codussi', '{}', 1440, 1504, '{}', 'architetto', 'Formatosi a Ravenna, approda a Venezia alla fine degli anni sessanta del Quattrocento. Il suo stile è il risultato di suggestioni derivate dall''architettura bizantina, veneziana e toscana, alle quali si aggiunge la conoscenza dell''arte antica vista a Pola, in Istria e a Verona. Considerato l''architetto più originale del Rinascimento veneziano.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('bartolomeo-vivarini', 'Bartolomeo Vivarini', '{}', NULL, NULL, '{}', 'pittore', 'Fratello minore di Antonio Vivarini, documentato dal 1450 al 1499. Collabora con Antonio e sviluppa uno stile più moderno, influenzato dalla lezione padovana (Mantegna), con solidità volumetrica e linea grafica marcata.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('mantegna', 'Mantegna', '{}', 1431, 1506, '{}', 'pittore', 'Artista padovano la cui influenza è fondamentale per l''evoluzione stilistica di Bartolomeo Vivarini verso forme plastiche e solide.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('johannes-gutenberg', 'Johannes Gutenberg', '{}', 1397, 1468, '{}', 'orafo/inventore', 'Orafo tedesco che elabora a metà Quattrocento la tecnica della stampa a caratteri mobili, rivoluzionando la comunicazione culturale in Europa.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('aldo-manuzio', 'Aldo Manuzio', '{}', 1452, 1515, '{}', 'editore/umanista', 'Uomo di grande ingegno e cultura umanistica, formatosi a Roma, fonda una stamperia a Venezia con l''obiettivo preciso di diffondere la conoscenza della cultura greca e del sapere classico. Introduce il corsivo nella stampa.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('francesco-colonna', 'Francesco Colonna', '{}', NULL, NULL, '{}', 'scrittore/domenicano', 'Domenico autore dell''Hypnerotomachia Poliphili, romanzo allegorico edito da Manuzio nel 1499, considerato un''autentica opera d''arte.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('jacopo-bellini', 'Jacopo Bellini', '{}', 1396, 1470, '{}', 'pittore', 'Direttore della grande bottega veneziana, formatosi a contatto con Gentile da Fabriano, interprete di un gusto gotico raffinato e fiabesco. Soggiornò a Verona (1436) e Ferrara (1440-1441). Padre di Gentile e Giovanni Bellini, educati nella sua bottega paterna. Tentò un rinnovamento verso le forme rinascimentali.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('vittore-carpaccio', 'Vittore Carpaccio', '{}', 1460, 1526, '{}', 'pittore', 'Pittore veneziano formatosi probabilmente con il padre o con Gentile Bellini, attivo tra la fine del Quattrocento e l''inizio del Cinquecento. Celebre per i suoi cicli di teleri narrativi, caratterizzati da atmosfere fiabesche, attenzione ai dettagli architettonici e paesaggistici, e da una narrazione calibrata e leggibile. Collaborò alla realizzazione del ciclo della Scuola Grande di San Giovanni Evangelista (teleri di San Girolamo) e dipingé i celebri teleri per la Scuola di Sant''Orsola.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('giorgione', 'Giorgione', '{}', 1478, 1510, '{}', 'pittore', 'Pittore veneto, allievo di Giovanni Bellini, precursore della pittura tonale e atmosferica.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('leonello-deste', 'Leonello d''Este', '{}', 1407, 1450, '{}', 'Marchese di Ferrara', 'Capo di un piccolo Stato che investì molto nelle lettere e nelle arti, attirando alla sua corte artisti come Leon Battista Alberti, Jacopo Bellini e Pisanello. Promosse commissioni pubbliche e private, favorendo la nascita di una scuola artistica locale.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('borso-deste', 'Borso d''Este', '{}', 1413, 1471, '{}', 'Duca di Ferrara', 'Succeduto a Leonello, garantì a Ferrara un lungo periodo di pace e prosperità. Ampliò la città verso sud con l''Addizione Borsiana e promosse importanti commissioni pubbliche.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('ercole-i-deste', 'Ercole I d''Este', '{}', 1431, 1505, '{}', 'Duca di Ferrara', 'Guidò Ferrara tra il 1482 e il 1484 in una guerra contro Venezia conclusasi disastrosamente. Avviò successivamente una nuova fase di espansione demografica ed economica con l''Addizione Erculea.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('matteo-de-pasti', 'Matteo de'' Pasti', '{}', NULL, NULL, '{}', 'Pittore, medaglista', 'Artista presente alla corte estense di Leonello d''Este.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('cosme-tura', 'Cosmè Tura', '{}', 1430, 1495, '{}', 'Pittore', 'Pittore ferrarese, i primi lavori documentati risalgono al 1450 circa. Si trasferì a Padova e Venezia (1450-1456) dove entrò in contatto con l''opera di Donatello, Mantegna e Squarcione. Tornò a Ferrara iniziando una fortunata carriera come pittore di corte. Mostra padronanza della tecnica a olio acquisita a Venezia senza ipotizzare uno spostamento fino alle Fiandre. I legami con il modello nordico sono riconoscibili nei paesaggi calligrafici, nel nitore dei dettagli e nelle scelte iconografiche.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('biagio-rossetti', 'Biagio Rossetti', '{}', 1447, 1516, '{}', 'architetto', 'Architetto di corte dal 1483, considerato il primo architetto urbanista moderno. Progettò l''Addizione Erculea a Ferrara e il Palazzo dei Diamanti.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('gabriele-frisoni', 'Gabriele Frisoni', '{}', NULL, NULL, '{}', 'artista', 'Scultore e decoratore attivo nel XVII secolo, autore dei particolari ornamentali del Palazzo dei Diamanti (candelabra, angoloni).', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('angelo-maccagnino', 'Angelo Maccagnino', '{}', NULL, NULL, '{}', 'pittore', 'Artista di modi ancora tardo-gotici, ma influenzato anche dall''arte fiamminga e da Cosmè Tura, subentrato dopo la morte del collega allo studio di Belriguardo. Operò principalmente a Ferrara.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('guarino-veronese', 'Guarino Veronese', '{}', 1374, 1460, '{}', 'umanista, precettore', 'Umanista veronese, precettore di Leonello d''Este dal 1436 al 1447, definì il progetto iconografico dedicato alle Muse per lo studiolo di Belriguardo.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('francesco-del-cossa', 'Francesco del Cossa', '{}', 1436, 1478, '{}', 'pittore', 'Personalità che si discosta da Cosmè Tura. Per la condivisione con il caposcuola fantastica inventiva e la propensione per le scene decorative e aneddotiche, egli evita la tensione emotiva variercando da Tura e supera la staticità delle figure introducendo il problema della rappresentazione dei movimenti. La radice della sua autonomia stilistica va ricercata in un viaggio in Toscana compiuto tra il 1462 e il 1467 gli consente di acquisire maggior naturalezza nella definizione delle figure e di sviluppare una preferenza per i colori luminosi e vivaci. Nel 1470 interrompe i rapporti con la corte ferrarese', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('polittico-griffoni', 'Polittico Griffoni', '{}', NULL, NULL, '{}', 'pittore', 'Opera complessa realizzata da Francesco del Cossa ed Ercole de'' Roberti tra il 1470 e il 1473, commissionata per la chiesa di San Petronio a Bologna. L''opera mostra un controllo stilistico unitario nonostante la collaborazione tra i due artisti.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('ercole-de-roberti', 'Ercole de'' Roberti', '{}', 1450, 1496, '{}', 'pittore', 'Pittore ferrarese, allievo di Francesco del Cossa, noto per gli affreschi della cappella Garganelli in San Pietro a Bologna e per la Maddalena di Pinacoteca Nazionale di Bologna. La sua opera è caratterizzata da espressività potente e deformante, anticlassica, con influenze della scultura tarda di Donatello.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('francesco-del-francia-francesco-raibolini', 'Francesco del Francia (Francesco Raibolini)', '{}', NULL, NULL, '{}', 'pittore', 'Pittore bolognese, amico di Ercole de'' Roberti, con cui condivise lo studio a Bologna.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('antonio-del-massaia-antonio-da-messina', 'Antonio del Massaia (Antonio da Messina)', '{}', NULL, NULL, '{}', 'pittore', 'Artista che introdusse in Italia la tecnica della pittura a olio, influenzando lo sviluppo della pittura veneta e ferrarese.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('pietro-di-giovanni-dambrogio', 'Pietro di Giovanni d''Ambrogio', '{}', NULL, 1449, '{}', 'pittore', 'Autore del Polittico Porta Romana (1479-1481), citato come riferimento per la struttura porticata delle opere coeve.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('niccolo-dellarca', 'Niccolò dell''Arca', '{}', 1435, 1494, '{}', 'scultore', 'Scultore nato probabilmente a Bari, attivo a Bologna dal 1460 circa. Noto anche come Niccolò d''Apulia, entrò in contatto con la cultura cosmopolita napoletana e con le influenze nordiche e borgognone. Lavorò nella basilica di San Domenico dove realizzò il Compianto sul Cristo morto, capolavoro di espressionismo naturalistico e pathos intenso.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('nicola-pisano', 'Nicola Pisano', '{}', 1220, 1284, '{}', 'scultore', 'Scultore italiano del XIII secolo, autore del Pulpito del Duomo di Siena e di altri capolavori romanici-gotici. Le sue figure furono studiate e rielaborate da Niccolò dell''Arca nel Compianto sul Cristo morto.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('vita', 'Vita', '{}', NULL, NULL, '{}', 'scultore', 'Scultore che realizzò un''opera gestita dalla confraternita dei Disciplini tra il 1463 e il 1490, data non certa, mostrando conoscenza della scultura borgognona e del naturalismo tardogotico d''Oltalpe.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('pietro-benvogliente', 'Pietro Benvogliente', '{}', NULL, NULL, '{}', 'architetto', 'Architetto che nel 1465 ricevette l''incarico di ristrutturare Palazzo Schifanoia per adeguarlo a residenza ducale', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('maestro-degli-occhi-spalancati', 'Maestro degli Occhi Spalancati', '{}', NULL, NULL, '{}', 'pittore', 'Artista anonimo ferrarese, autore della scena inferiore del trionfo di Borsò d''Este', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('maestro-di-ginevra', 'Maestro di Ginevra', '{}', NULL, NULL, '{}', 'pittore', 'Artista anonimo ferrarese', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('filarete', 'Filarete', '{}', 1400, 1469, '{}', 'architetto e scultore', 'Antonio di Pietro Averlino, noto con lo pseudonimo di Filarete (1400 circa-1469), si forma a Roma nella bottega di Ghiberti. Nel 1450 si reca a Milano su invito di Francesco Sforza per progettare l''Ospedale Maggiore. Autore del Trattato di architettura (1460-1464) e della facciata della Cattedrale di Bergamo. Introdusse in Lombardia i principi dell''architettura rinascimento toscana, adattandoli al contesto locale.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('lorenzo-ghiberti', 'Lorenzo Ghiberti', '{}', 1378, 1455, '{}', 'scultore e orafo', 'Maestro fiorentino nel cui bottega si formò Filarete prima del suo trasferimento a Milano.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('guiniforte-solari', 'Guiniforte Solari', '{}', NULL, 1481, '{}', 'architetto e scultore', 'Architetto lombardo che collaborò con Filarete all''Ospedale Maggiore e ne completò la realizzazione dopo la sua partenza. Lavorò anche alla facciata della Cattedrale di Bergamo e al Castello Sforzesco.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('gian-galeazzo-visconti', 'Gian Galeazzo Visconti', '{}', 1351, 1402, '{}', 'Committente', 'Primo duca di Milano, fondatore della Certosa di Pavia come mausoleo dinastico', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('giovanni-antonio-amadeo', 'Giovanni Antonio Amadeo', '{}', 1447, 1522, '{}', 'Architetto, Scultore', 'Artista bergamasco che operò principalmente in Lombardia, allievo e collaboratore di Bartolomeo Colleoni. Realizzò la Cappella Colleoni a Bergamo (1472-1476) e il Monumento funebre di Bartolomeo Colleoni nella chiesa dei Santi Giovanni e Paolo a Venezia (dal 1488). Morì nel 1522 mentre lavorava al cantiere della Certosa di Pavia.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('bergognone', 'Bergognone', '{}', 1453, 1523, '{}', 'Pittore', 'Pittore lombardo, autore degli affreschi delle volte, del transetto e del coro della Certosa tra il 1488 e il 1495', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('gian-giacomo-dolcebuono', 'Gian Giacomo Dolcebuono', '{}', 1445, 1510, '{}', 'Scultore, Architetto', 'Scultore e architetto milanese, collaborò alla decorazione scultorea della facciata della Certosa', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('giovanni-benedetto-briosco', 'Giovanni Benedetto Briosco', '{}', 1460, 1517, '{}', 'Scultore', 'Scultore lombardo, collaboratore di Amadeo nella realizzazione delle formine incastonate della facciata', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('ambrogio-da-fossano-detto-il-bergognone', 'Ambrogio da Fossano detto il Bergognone', '{}', 1453, 1523, '{}', 'pittore', 'Pittore lombardo attivo tra la fine del Quattrocento e l''inizio del Cinquecento, noto per la decorazione della Certosa di Pavia e per uno stile che unisce influenze foppesche a una sensibilità devozionale intima e delicata.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('vincenzo-foppa', 'Vincenzo Foppa', '{}', 1427, 1515, '{}', 'pittore', 'Pittore originario di Brescia, figura di spicco della cultura figurativa lombarda. Operò principalmente a Milano (1463) e successivamente a Genova, Pavia, Bergamo e Savona. Si formò in un ambiente padovano, con contatti diretti con artisti fiorentini come il Pellegrino Tibaldi e il Portinari, e fu influenzato da Francesco Sforza. La sua opera matura si caratterizza per un naturalismo elementare e una prospettiva geometrica moderna.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('bartolomeo-colleoni', 'Bartolomeo Colleoni', '{}', 1400, 1475, '{}', 'condottiero e committente', 'Famoso condottiero al servizio della Repubblica di Venezia, committente della cappella funebre a Bergamo e del monumento equestre a Venezia. La sua figura ispirò il monumento equestre realizzato dal Verrocchio.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('antonio-del-pollaiuolo', 'Antonio del Pollaiuolo', '{}', NULL, NULL, '{}', 'artista', 'Artista fiorentino citato come riferimento per lo studio anatomico dei corpi nudi.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('gentile-da-fabriano', 'Gentile da Fabriano', '{}', NULL, NULL, '{}', 'pittore', 'Pittore citato come riferimento per la qualità luminosa delle opere di Foppa.', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.artists (id, name, aka, birth, death, period_ids, role, bio, innovations) VALUES ('sismondo-pandolfo-malatesta', 'Sismondo Pandolfo Malatesta', '{}', NULL, NULL, '{}', 'signore', 'Signore di Rimini, committente della cappella dipinta da Foppa (opera perduta).', '{}') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = COALESCE(NULLIF(EXCLUDED.bio, ''), artists.bio), birth = COALESCE(EXCLUDED.birth, artists.birth), death = COALESCE(EXCLUDED.death, artists.death);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('affresco', 'Affresco', 'Tecnica pittorica eseguita su intonaco fresco, utilizzata da Mantegna per la decorazione della cappella Ovetari e della Camera degli Sposi.', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('tratto-inciso-e-sicuro', 'Tratto inciso e sicuro', 'Caratteristica stilistica derivante dall''influenza di Donatello, che conferisce alle figure un''impostazione salda e monumentale.', NULL, NULL, '', 'stile') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('tempera-su-tavola', 'tempera su tavola', 'Tecnica pittorica che utilizza pigmenti legati con uovo o altri leganti applicati su supporto ligneo.', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('prospettiva-illusionistica', 'prospettiva illusionistica', 'Tecnica di rappresentazione spaziale che crea l''illusione di profondità attraverso regole matematiche precise, usata da Mantegna per fondere cornice e spazio dipinto.', NULL, NULL, '', 'composizione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('sacra-conversazione', 'sacra conversazione', 'Schema compositivo rinascimentale che riunisce in uno spazio unitario la Madonna col Bambino e i santi in atto di dialogo.', NULL, NULL, '', 'iconografia') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('cornice-lignea', 'cornice lignea', 'Struttura architettonica in legno che circonda l''opera pittorica, qui integrata con lo spazio dipinto tramite colonne dorate scanalate e fregio a girali.', NULL, NULL, '', 'tecnica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('spazio-architettonico-unitario', 'Spazio architettonico unitario', 'Composizione in cui tutte le figure sono inserite in un unico spazio costruito architettonicamente, con regole prospettiche classiche e impostazione formale rigorosa', NULL, NULL, '', 'composizione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('tempera-a-colla-su-tela', 'tempera a colla su tela', 'Tecnica pittorica che utilizza pigmenti legati con colla animale o vegetale applicati su tela', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('prospettiva-di-sotto-in-su-dal-basso', 'prospettiva di sotto in sù (dal basso)', 'Tecnica prospettica che rappresenta il soggetto visto da un punto di vista inferiore, creando un effetto di monumentalità', NULL, NULL, '', 'composizione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('tempera-grassa', 'Tempera grassa', 'Tecnica pittorica che utilizza pigmenti legati con emulsioni oleose, applicabile anche su muro secco o per ritocchi.', NULL, NULL, '', 'pittorica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('di-sotto-in-su-prospettiva', 'Di sotto in sù (prospettiva)', 'Tecnica prospettica usata per dipingere soffitti creando l''illusione di spazi architettonici aperti verso l''alto.', NULL, NULL, '', 'compositiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('trompe-lil', 'Trompe-l''œil', 'Tecnica illusionistica che crea l''inganno ottico facendo apparire elementi dipinti come reali (balaustrata, oculo).', NULL, NULL, '', 'illusionistica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('di-sotto-in-su', 'Di sotto in su', 'Tecnica pittorica prospettica usata per rappresentare figure o oggetti visti dal basso verso l''alto, tipicamente su soffitti o volte.', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('oculus', 'Oculus', 'Apertura circolare o ellittica, reale o illusionistica, presente in cupole o soffitti; nella Camera degli Sposi è dipinta per creare un effetto di apertura verso il cielo.', NULL, NULL, '', 'architettura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('affresco-a-secco', 'Affresco a secco', 'Tecnica pittorica eseguita su intonaco asciutto, utilizzata da Mantegna per i particolari minuti e i rifiniti della Camera degli Sposi, in combinazione con la tecnica del buon affresco.', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('prospettiva-intuitivaillusionistica', 'Prospettiva intuitiva/illusionistica', 'Uso della prospettiva per creare l''illusione di uno spazio tridimensionale che si prolonga oltre i limiti fisici della parete, tipica della Camera degli Sposi dove l''architettura dipinta sembra continuare quella reale.', NULL, NULL, '', 'composizione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('graffito', 'Graffito', 'Tecnica decorativa che consiste nell''incidere lo strato superficiale dell''intonaco per creare disegni a contrasto cromatico, usata da Mantenga per le decorazioni parietali della Camera.', NULL, NULL, '', 'decorativa') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('finestra-aperta', 'Finestra aperta', 'Concetto teorizzato da Alberti secondo cui la superficie dipinta deve apparire come una finestra attraverso cui si guarda uno spazio reale e virtuale', NULL, NULL, '', 'composizione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('quadratura', 'Quadratura', 'Dipinto illusionistico che simula elementi architettonici per dilatare lo spazio reale dell''ambiente', NULL, NULL, '', 'decorazione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('graffitosgraffito', 'Graffito/Sgraffito', 'Tecnica di incisione o raschiamento dello strato superficiale dell''affresco per creare dettagli o effetti di rilievo', NULL, NULL, '', 'tecnica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('tempera-su-tela', 'Tempera su tela', 'Tecnica pittorica che utilizza pigmenti legati con emulsioni (tuorlo d''uovo o altri leganti) applicati su supporto tessile, tipica del XV secolo prima dell''affermazione dell''olio', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('colorito-corto', 'Colorito corto', 'Modalità cromatica caratterizzata da tonalità vivaci e contrastate, tipica delle opere celebrative mantegnesche', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('ridipintura-cinquecentesca', 'Ridipintura cinquecentesca', 'Intervento di ripristino o modifica effettuato sul dipinto originale nel XVI secolo, che ne altera l''aspetto originario', NULL, NULL, '', 'restauro') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('scorciotaglio-prospettico', 'Scorcio/Taglio prospettico', 'Rappresentazione di un oggetto o una figura da un punto di vista obliquo o estremo, che ne altera la percezione abituale creando effetti spaziali particolari', NULL, NULL, '', 'composizione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('vele', 'Vele', 'Elemento architettonico decorativo a forma di vela o drappo', NULL, NULL, '', 'architettura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('lacunari', 'Lacunari', 'Elementi decorativi a cassettoni presenti nei soffitti, tipici dell''architettura classica', NULL, NULL, '', 'architettura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('oculo', 'Oculo', 'Apertura circolare o finestra rotonda presente nelle strutture architettoniche', NULL, NULL, '', 'architettura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('sfondato-architettonico', 'Sfondato architettonico', 'Ambiente costruito che funge da sfondo alla scena rappresentata, con elementi architettonici realistici o illusionistici', NULL, NULL, '', 'composizione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('medaglistica', 'Medaglistica', 'Arte di creare medaglie commemorative o celebrative, spesso con ritratti del committente', NULL, NULL, '', 'altra') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('arazzeria-su-cartoni', 'Arazzeria su cartoni', 'Tecnica di realizzazione di arazzi basata su disegni preparatori (cartoni) creati da pittori', NULL, NULL, '', 'altra') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('arcosolio', 'Arcosolio', 'Schema architettonico funebre costituito da una nicchia ad arco che ospita il sarcofago e la statua del defunto', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('forma-cubica-con-cupola', 'Forma cubica con cupola', 'Schema planimetrico e volumetrico derivato dai modelli brunelleschiani (Sacrestia Vecchia), caratterizzato da pianta quadrata e copertura a cupola', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('struttura-marmorea-slanciata-in-verticale', 'Struttura marmorea slanciata in verticale', 'Tecnica architettonica che prevede lo sviluppo verticale della struttura in marmo per spezzare la severa linearità della patta del castello', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('colonne-binate-corinzie', 'Colonne binate corinzie', 'Accoppiamento di colonne con capitelli corinzi utilizzate nel piano inferiore dell''arco', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('timpano-curvilineo', 'Timpano curvilineo', 'Elemento architettonico superiore con andamento curvo che contiene le statue delle Virtù nelle nicchie', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('tempera-e-oro-su-tavola', 'tempera e oro su tavola', 'Tecnica pittorica che utilizza pigmenti legati con tempera (generalmente tuorlo d''uovo) applicati su supporto ligneo, con fondo o rifiniture in foglia d''oro', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('fondo-oro-bulinato', 'fondo oro bulinato', 'Tecnica decorativa che prevede l''incisione (bulinatura) sul fondo in oro per creare motivi ornamentali', NULL, NULL, '', 'decorazione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('aureole-traforate', 'aureole traforate', 'Aureole (nimbi) realizzate con lavorazione a traforo, tipiche della tradizione tardogotica e fiamminga', NULL, NULL, '', 'decorazione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('prospettiva-ribaltata', 'prospettiva ribaltata', 'Tecnica prospettica in cui il pavimento sembra inclinarsi verso l''osservatore, tipica di alcune interpretazioni dello spazio fiammingo e aragonese', NULL, NULL, '', 'composizione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('azulejos', 'azulejos', 'Piastrelle ceramiche decorate, tipiche della tradizione spagnola (valenciana), con motivi geometrici e floreali', NULL, NULL, '', 'decorazione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('tecnica-mista-su-tavola', 'Tecnica mista su tavola', 'Tecnica pittorica che combina diversi materiali su supporto ligneo, utilizzata da Antonello da Messina nella Crocifissione del 1475.', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('medium-pittorico-dei-colori-a-olio', 'Medium pittorico dei colori a olio', 'Nuova tecnica pittorica dominata con maestria da Antonello da Messina, che permette di creare sottili passaggi tonali, trasparenze impercettibili e delicati chiaroscuri.', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('sezione-aurea', 'Sezione aurea', 'Proporzione matematica utilizzata nella composizione della Crocifissione per organizzare gli elementi spaziali', NULL, NULL, '', 'compositiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('resa-atmosferica-a-nebbia', 'Resa atmosferica a nebbia', 'Tecnica pittorica che utilizza la nebbia per rendere meno nitido il paesaggio con l''aumentare della distanza, creando profondità spaziale', NULL, NULL, '', 'pittorica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('illuminazione-diagonale', 'Illuminazione diagonale', 'Sistema di luce proveniente da sinistra che colpisce la figura evidenziandone i volumi attraverso un gioco d''ombre radenti', NULL, NULL, '', 'pittorica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('olio-su-tavola', 'Olio su tavola', 'Tecnica pittorica a base oleosa applicata su supporto ligneo, introdotta in Italia tramite l''influenza fiamminga', NULL, NULL, '', 'materica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('trasferimento-su-tela', 'Trasferimento su tela', 'Tecnica di conservazione che prevede il distacco del strato pittorico dal supporto originale e la sua applicazione su tela nuova', NULL, NULL, '', 'restauro') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('prospettiva-centrale', 'Prospettiva centrale', 'Sistema di rappresentazione dello spazio basato su un punto di fuga unico al centro dell''opera', NULL, NULL, '', 'composizione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('prospettiva-lineare', 'Prospettiva lineare', 'Uso sapiente della prospettiva lineare per simulare un ambiente arioso e ampio, conferendo allo spazio un senso monumentale che trascende le ridotte dimensioni della tavola', NULL, NULL, '', 'compositiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('illuminazione-complessa', 'Illuminazione complessa', 'Gioco dei diversi piani di profondità esaltato dalla complessa illuminazione della scena che genera numerose zone d''ombra e di penombra nel vano dello studiolo', NULL, NULL, '', 'tecnica pittorica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('copertura-policroma', 'Copertura policroma', 'Tecnica decorativa che utilizza pietra colorata per creare effetti cromatici sulla superficie architettonica, ripresa della maniera antica e omaggio al gusto veneziano', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('intaglio-della-pietra', 'Intaglio della pietra', 'Tecnica scultorea di raffinata esecuzione sulle superfici lapidee, caratteristica dell''officina lombarda applicata all''architettura', NULL, NULL, '', 'sculptural') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('rivestimento-in-pietra-distria', 'Rivestimento in pietra d''Istria', 'Uso esclusivo della pietra d''Istria bianca candore per rivestire la superficie esterna del prospetto, tecnica tipica dell''architettura veneziana.', NULL, NULL, '', 'materiale') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('pianta-longitudinale-a-tre-navate-su-colonne', 'Pianta longitudinale a tre navate su colonne', 'Struttura interna della chiesa divisa in tre navate sostenute da colonne, secondo una teoria di archi a tutto sesto impostati su colonne.', NULL, NULL, '', 'strutturale') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('sviluppo-orizzontale-con-ritmo-verticale', 'Sviluppo orizzontale con ritmo verticale', 'Composizione palazzina che bilancia l''estensione orizzontale del corpo di fabbrica con una scansione verticale rigorosa tramite marcapiani e ordini architettonici sovrapposti.', NULL, NULL, '', 'compositiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('pittura-a-olio-su-tela', 'pittura a olio su tela', 'Tecnica introdotta in Venezia dai Paesi Bassi che spinge gli artisti locali verso un approccio più diretto alla realtà e alla natura.', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('stampa-a-caratteri-mobili', 'Stampa a caratteri mobili', 'Innovazione tecnica che cambia l''orizzonte culturale di un intero continente, permettendo la riproduzione meccanica di testi attraverso tipi metallici riutilizzabili', NULL, NULL, '', 'altra') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('xilografia', 'Xilografia', 'Tecnica di incisione su legno utilizzata per illustrare libri stampati, come nell''Hypnerotomachia Poliphili che ne contiene circa 170 esempi', NULL, NULL, '', 'altra') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('introduzione-del-corsivo', 'Introduzione del corsivo', 'Perfezionamento tecnico introdotto da Aldo Manuzio nella stampa, uno dei fondamentali miglioramenti della tecnica tipografica', NULL, NULL, '', 'altra') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('architettura-merlata', 'Architettura merlata', 'Elemento decorativo architettonico tardo-gotico presente nel Trittico con la Madonna in trono dei Vivarini, che accoglie la sacra conversazione', NULL, NULL, '', 'altra') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('penna-e-inchiostro-bruno-su-carta', 'penna e inchiostro bruno su carta', 'Tecnica disegnativa che utilizza penna e inchiostro bruno su supporto cartaceo', NULL, NULL, '', 'disegno') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('pittura-a-gettito', 'pittura a gettito', 'Tecnica formale dei teli prospettici con una linea di contorno agile ed essenziale e un colore netto e ben definito', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('telerio', 'Telerio', 'Grande pittura su tela destinata alla decorazione di confraternite (scuole) veneziane, tipico formato del Rinascimento veneziano', NULL, NULL, '', 'altra') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('olio-su-tela', 'Olio su tela', 'Tecnica pittorica che utilizza pigmenti legati ad olio applicati su supporto tessile', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('colore-a-olio', 'colore a olio', 'Tecnica pittorica introdotta a Venezia da Antonello da Messina, che permette tonalità più luminose e sfumature morbide rispetto alla tempera', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('opere-fiamminghe', 'opere fiamminghe', 'Riferimento alla pittura fiamminga presente in laguna, che indusse gli artisti veneziani a scegliere di dipingere con colori a olio', NULL, NULL, '', 'corrente artistica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('ariosa-veduta-collinare', 'Ariosa veduta collinare', 'Tipo di paesaggio ampio e sereno che sostituisce l''asprezza delle rocce mantegnesche con dolci colline e luce diffusa', NULL, NULL, '', 'compositiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('luce-dellalba', 'Luce dell''alba', 'Illuminazione caratterizzata da tonalità rosa/arancio che rischiara il cielo e crea riflessi sulle nuvole, colli e pareti rocciose', NULL, NULL, '', 'luminosa') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('atmosfera-naturale', 'Atmosfera naturale', 'Rendere l''aria come elemento tangibile attraverso sfumature cromatiche e variazioni di luminosità che creano profondità spaziale', NULL, NULL, '', 'pittorica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('punto-di-vista-ravvicinato', 'punto di vista ravvicinato', 'Prospettiva che avvicina le figure allo spettatore, aumentando l''impatto emotivo e il coinvolgimento', NULL, NULL, '', 'compositiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('mezzobusto', 'mezzobusto', 'Raffigurazione delle figure tagliate all''altezza del petto o della vita', NULL, NULL, '', 'compositiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('formato-unitario', 'formato unitario', 'Struttura compositiva tipica della pala rinascimentale toscana, in contrapposizione al politico gotico', NULL, NULL, '', 'compositiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('tavola', 'tavola', 'Supporto ligneo per dipinti, qui in tempera', NULL, NULL, '', 'tecnica artistica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('olio', 'olio', 'Tecnica pittorica ad olio, usata da Bellini nella Pala di Pesaro come sua prima opera in questa tecnica', NULL, NULL, '', 'tecnica artistica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('polittico', 'polittico', 'Opera d''arte composta da più pannelli, qui con tappera fondamentale, legno scolpito e dorato, piastre laterali', NULL, NULL, '', 'tipologia opera') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('prospettiva-aerea', 'Prospettiva aerea', 'Tecnica per rappresentare la profondità attraverso lo sfumatura dei colori in lontananza', NULL, NULL, '', 'composizione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('luce-uniforme', 'Luce uniforme', 'Illuminazione diffusa e omogenea che elimina contrasti drammatici a favore dell''armonia cromatica', NULL, NULL, '', 'illuminazione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('spazio-pittorico-reale', 'Spazio pittorico reale', 'Integrazione dello spazio dipinto con lo spazio architettonico reale in cui l''opera è collocata', NULL, NULL, '', 'compositiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('luce-naturale', 'luce naturale', 'Potenza unificante della luce che lega insieme i colori, le ombre e le forme creando un''atmosfera omogenea e realistica', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('colore-unificante', 'colore unificante', 'Uso del colore non solo come elemento decorativo ma come strumento costruttivo che definisce lo spazio e unifica la composizione', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('colorito-tonale', 'colorito tonale', 'Uso del colore per definire volumi e creare unità atmosferica, tipico della scuola veneta', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('pittura-a-olio', 'pittura a olio', 'Tecnica pittorica che utilizza pigmenti legati con olio di lino o altri oli essiccativi, permettendo sfumature cromatiche e dettagli fini', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('prospettiva-costruita-in-pianta-e-alzato', 'prospettiva costruita in pianta e alzato', 'Tecnica architecttonica dove i pilastri dipinti corrispondono perfettamente a quelli reali dello spazio fisico', NULL, NULL, '', 'architettura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('colore-tonale', 'colore tonale', 'Uso del colore per creare modellato e volume attraverso sfumature progressive anziché contrasti netti', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('addizione-urbanistica', 'Addizione urbanistica', 'Ampliamento pianificato di una città con creazione di nuovi quartieri, strade e piazze secondo criteri razionali.', NULL, NULL, '', 'urbanistica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('bugnato-diamantato', 'bugnato diamantato', 'Rivestimento facciata costituito da blocchi (bugne) a forma di diamante con punte orientate in direzioni diverse, che crea effetti prospettici e luminosi', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('planimetria-articolata', 'planimetria articolata', 'Struttura planimetrica complessa e non regolare, tipica dell''architettura rinascimentale evoluta', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('facciata-a-candelabre', 'facciata a candelabre', 'Decorazione verticale a forma di candelabro, di derivazione classica, utilizzata per elementi strutturali o decorativi', NULL, NULL, '', 'decorativa') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('tarsia-lignea', 'tarsia lignea', 'Tecnica decorativa che consiste nell''intarsio di legni diversi colorati per creare disegni geometrici o figurativi', NULL, NULL, '', 'decorazione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('tecnica-a-olio', 'Tecnica a olio', 'Tecnica pittorica che Tura padroneggia probabilmente acquisita a Venezia', NULL, NULL, '', 'pittorica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('tempera', 'Tempera', 'Tecnica pittorica usata nell''originale delle opere, successivamente modificata con interventi a olio', NULL, NULL, '', 'pittorica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('ante-dorgano', 'Ante d''organo', 'Sportelli decorativi destinati a coprire l''organo della chiesa quando non in uso, spesso dipinti su entrambi i lati (ante aperte/chiuse)', NULL, NULL, '', 'altra') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('prospettiva-invertita', 'Prospettiva invertita', 'Effetto spaziale in cui le figure sembrano proiettarsi verso l''osservatore anziché allontanarsi, creando un effetto di coinvolgimento emotivo e teatrale', NULL, NULL, '', 'compositiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('sfondo-oro', 'Sfondo oro', 'Uso di fondo dorato tipico dell''iconografia medievale e gotica, qui rielaborato in chiave tardogotica', NULL, NULL, '', 'decorativa') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('illuminazione-laterale', 'Illuminazione laterale', 'Tecnica di illuminazione che colpisce le figure lateralmente, accentuando il vigore plastico e il rilievo delle forme', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('articolazione-spaziale', 'Articolazione spaziale', 'Organizzazione dello spazio architettonico dell''opera attraverso strutture architettoniche (nicchie, cornici) che inquadrano le figure', NULL, NULL, '', 'composizione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('schema-piramidale', 'Schema piramidale', 'Composizione figurativa organizzata secondo una struttura triangolare o piramidale, che conferisce equilibrio e stabilità all''insieme.', NULL, NULL, '', 'compositiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('pedana-ottagonale', 'Pedana ottagonale', 'Base ottagonale su cui si innesta la struttura architettonica della pala, soluzione originale adottata da Roberti nella Pala Portonese.', NULL, NULL, '', 'compositiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('volta-a-crociera', 'Volta a crociera', 'Elemento architettonico che copre la struttura porticata della Pala Portonese, derivato dalla decorazione tipica di Tura.', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('affresco-staccato', 'Affresco staccato', 'Tecnica pittorica in cui l''affresco viene staccato dal muro originale e trasferito su un nuovo supporto, spesso tela o tavola, per motivi di conservazione o spostamento.', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('terracotta-policroma', 'Terracotta policroma', 'Scultura in argilla cotta (terracotta) successivamente dipinta con colori per simulare tessuti, carnagioni e altri dettagli realistici; tecnica molto usata nella scultura bolognese del Quattrocento.', NULL, NULL, '', 'scultura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('affresco-e-tempera-a-secco', 'Affresco e tempera a secco', 'Tecnica pittorica utilizzata per il ciclo dei Mesi, combinando affresco (pittura su intonaco fresco) e tempera a secco per finiture', NULL, NULL, '', 'pittura') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('tecnica-mista-a-secco', 'Tecnica mista a secco', 'Tecnica pittorica che prevede l''esecuzione di parti seguate a fresco con interventi a secco per completare o rifinire l''opera', NULL, NULL, '', 'affresco') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('progetto-iconografico-unitario', 'Progetto iconografico unitario', 'Coerenza del linguaggio artistico e scansione regolare delle pareti basata su un progetto comune di apparatenza, pur mantenendo le peculiarità stilistiche dei singoli artisti', NULL, NULL, '', 'compositiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('effetto-illusionistico', 'Effetto illusionistico', 'Tecnica usata nel registro inferiore per creare uno spazio reale attraverso la linea di vista e la prospettiva', NULL, NULL, '', 'prospettiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('fascia-orizzontale', 'Fascia orizzontale', 'Struttura compositiva tipica dei cicli ferraresi di Palazzo Schifanoia, che divide la parete in tre registri sovrapposti: trionfo celeste, zodiaco/mitologia, vita terrena/cortese', NULL, NULL, '', 'composizione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('facciata', 'Facciata', 'In architettura, il fronte principale di un edificio. Filarete ne teorizza una versione semplificata rispetto ai canoni classici, con marcato cornicione in laterizi che raccorda le diverse parti dell''edificio, finestre bifore ad archi ogivali all''ultimo piano e doppio ordine di logge.', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('ordine-architettonico', 'Ordine architettonico', 'Sistema di proporzioni e elementi decorativi (colonne, capitelli, trabeazioni) derivati dall''architettura classica romana e greca. Filarete utilizza principalmente l''ordine corinzio nelle sue opere milanesi.', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('pianta-centrale', 'Pianta centrale', 'Schema planimetrico in cui l''edificio si sviluppa attorno a un centro (cortile o sala), tipico dell''architettura rinascimentale. L''Ospedale Maggiore ne è un esempio con il cortile quadrato porticato.', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('loggiatoporticato', 'Loggiato/Porticato', 'Spazio coperto aperto verso l''esterno attraverso una serie di arcate sostenute da colonne o pilastri. Nell''Ospedale Maggiore è presente su due livelli (doppio ordine).', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('laterizio', 'Laterizio', 'Materiale da costruzione ottenuto dalla cottura dell''argilla, ampiamente utilizzato in Lombardia per la realizzazione delle facciate e dei cornicioni, come nell''Ospedale Maggiore.', NULL, NULL, '', 'materiale') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('pianta-a-stella', 'Pianta a stella', 'Schema urbanistico a forma di stella a otto punte (ottagono inscritto in un cerchio), tipico delle città ideali rinascimentali, con strade convergenti verso il centro', NULL, NULL, '', 'urbanistica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('strade-secondarie-radiali', 'Strade secondarie radiali', 'Sistema viario secondario organizzato a raggiera dal centro verso la periferia, collegato alle vie principali convergenti', NULL, NULL, '', 'urbanistica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('disegno-a-penna-e-inchiostro', 'Disegno a penna e inchiostro', 'Tecnica grafica utilizzata per i disegni architettonici e le illustrazioni dei trattati rinascimentali, eseguita con inchiostro bruno su carta', NULL, NULL, '', 'altra') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('formine-incastonate', 'Formine incastonate', 'Tecnica decorativa che prevede l''inserimento di piccole sculture (formine) all''interno di nicchie o spazi appositamente creati nell''architettura', NULL, NULL, '', 'decorativa') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('colonna-binata', 'Colonna binata', 'Struttura architettonica costituita da due colonne accoppiate, spesso usata per enfatizzare l''importanza di un elemento architettonico come un portale o un''abside', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('loggiato', 'Loggiato', 'Galleria aperta sul lato esterno, sostenuta da colonne o pilastri, tipica dell''architettura rinascimentale italiana', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('facciata-a-paramento-murario', 'facciata a paramento murario', 'Tecnica costruttiva che prevede l''uso di diversi tipi di marmo e pietra per creare effetti cromatici e decorativi sulla superficie esterna dell''edificio', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('cupola-a-spicchi', 'cupola a spicchi', 'Struttura di copertura ottagonale divisa in spicchi (vele), derivata dall''architettura romanica e bizantina, qui ripresa in chiave rinascimentale', NULL, NULL, '', 'architettonica') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('prospettiva-dal-basso-di-sotto-in-su', 'prospettiva dal basso (di sotto in sù)', 'Tecnica prospettica che rappresenta i soggetti visti dal basso verso l''alto, usata per creare effetto di monumentalità', NULL, NULL, '', 'prospettiva') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.techniques (id, name, definition, introduced_by, first_period_id, evolution, category) VALUES ('luce-calda-e-velata', 'luce calda e velata', 'Trattamento della illuminazione che cita il modello dell''Ospedale Maggiore di Filarete, con funzione decorativa e simbolica universale', NULL, NULL, '', 'illuminazione') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), techniques.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('studium-patavinum', 'Studium Patavinum', 'Centro culturale attivo a Padova nel Quattrocento, frequentato dal giovane Andrea Mantegna.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('bottega', 'Bottega', 'Laboratorio artistico dove si formava il giovane Mantegna sotto la guida di Squarcione.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('pittore-di-corte', 'Pittore di corte', 'Ruolo assunto da Mantegna a Mantova al servizio dei Gonzaga, con compiti di grandi cicli decorativi.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('passione-antiquaria', 'Passione antiquaria', 'Interesse per l''antichità classica sviluppato da Mantegna grazie al contatto con l''elite umanistica padovana, caratteristico di tutta la sua attività successiva.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('vicissitudini', 'Vicissitudini', 'Serie di eventi avversi che colpirono gli affreschi della cappella Ovetari: morte di Giovanni d''Alemagna (1450), abbandono di Vivarini, morte di Niccolò Pizzolo (1453), distruzione durante la Seconda guerra mondiale.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('camera-degli-sposi', 'Camera degli Sposi', 'Sala del Palazzo Ducale di Mantova decorata da Mantegna con affreschi tra il 1465 e il 1474.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('predella', 'predella', 'Fascia inferiore di un polittico o di un altare, generalmente decorata con scene narrative di piccole dimensioni.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('polittico', 'polittico', 'Opera d''arte composta da più pannelli (tavole) uniti in una struttura architettonica.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('fregio-a-girali', 'fregio a girali', 'Elemento decorativo orizzontale con motivi vegetali a spirale, tipico dell''architettura classica e rinascimentale.', 'decorazione', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('cimasa', 'cimasa', 'Elemento decorativo superiore della cornice di un polittico, spesso a frontone.', 'architettura', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('coinvoglimento-dello-spettatore', 'coinvoglimento dello spettatore', 'Tecnica compositiva che coinvolge visivamente chi guarda l''opera, qui ottenuta attraverso dettagli realistici come il lembo del mantello di san Pietro che esce dal piano pictorio.', 'composizione', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('punto-di-fuga-ribassato', 'punto di fuga ribassato', 'Tecnica prospettica che colloca il punto di fuga in posizione bassa, conferendo monumentalità alle figure rappresentate.', 'prospettiva', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('punto-di-fuga', 'Punto di fuga', 'Punto dello spazio pittorico verso cui convergono le linee parallele prospettiche, utilizzato da Mantegna per creare monumentalità e coinvolgimento spaziale', 'tecnica artistica', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('gioco-tra-personaggi-e-paesaggio', 'Gioco tra personaggi e paesaggio', 'Relazione dinamica tra le figure umane e lo sfondo naturale, trattato con festosità dalla scuola di Squarcione', 'composizione', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('elementi-classici', 'Elementi classici', 'Motivi derivanti dall''arte antica romana e greca (cornici, colonne, architravi) fusi con elementi religiosi cristiani in una sintesi formale e allegorica', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('sospeso-classico-cristiano', 'Sospeso classico-cristiano', 'Equilibrio tra valori simbolici dell''antichità classica e contenuti religiosi cristiani, tipico del Rinascimento maturo', 'concettuale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('grande-naturalezza', 'grande naturalezza', 'Caratteristica stilistica delle figure di Mantegna, che raffigura gli apostoli con espressioni e atteggiamenti naturalistici e realistici', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('bellezza-quattuoraria', 'bellezza quattuoraria', 'Riferimento allo stile della versione precedente del San Sebastiano di Mantegna, caratterizzata da maggiore eleganza formale', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('forte-caratterizzazione-scultorea', 'forte caratterizzazione scultorea', 'Rendimento delle forme umane con solidità e volume tipici della scultura, anche in pittura', 'stile', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('visione-leggermente-ribassata', 'visione leggermente ribassata', 'Punto di vista leggermente inferiore rispetto al soggetto rappresentato', 'composizione', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('nudo-maschile-di-bellazza-quasi-statuaria', 'nudo maschile di bellazza quasi statuaria', 'Rappresentazione del corpo maschile con perfezione formale ispirata alla scultura classica', 'iconografia', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('accentuata-espressivita-del-volto', 'accentuata espressività del volto', 'Enfasi sulle emozioni trasmesse dall''espressione facciale', 'stile', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('tratti-somatici-degli-archieri', 'tratti somatici degli archieri', 'Caratteristiche fisiche dei personaggi secondari (gli arcieri che torturano San Sebastiano)', 'iconografia', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('paesaggio-nordico', 'paesaggio nordico', 'Tipo di paesaggio con caratteristiche tipiche dell''arte fiamminga o tedesca del Nord Europa', 'iconografia', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('coinvolgimento-emotivo-e-devozionale', 'coinvolgimento emotivo e devozionale', 'Capacità dell''opera di suscitare nello spettatore emozioni religiose e partecipazione spirituale', 'funzione', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('impostazione-dellinquadramento', 'impostazione dell''inquadramento', 'Modo in cui è organizzato lo spazio visivo e il punto di vista scelto dall''artista', 'composizione', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('realismo-dei-dettagli-piu-cruenti-e-drammatici', 'realismo dei dettagli più cruenti e drammatici', 'Rappresentazione realistica degli elementi macabri e sofferenti (ferite, sangue, morte)', 'stile', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('camera-picta-depincta', 'Camera picta / depincta', 'Termine latino indicante una camera dipinta; denominazione originale della Camera degli Sposi.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('stanza-da-letto-di-rappresentanza', 'Stanza da letto di rappresentanza', 'Funzione ufficiale della Camera degli Sposi, destinata agli incontri del marchese con familiari, dignitari e funzionari.', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('vele', 'Vele', 'Superfici curve della volta tra le pareti e il centro, qui dipinte a monocromo con soggetti mitologici.', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('lacunari', 'Lacunari', 'Cassettoni decorativi del soffitto, qui contenenti medaglioni con ritratti di imperatori romani in stucco e mosaico dorato.', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('oculo', 'Oculo', 'Apertura circolare illusionistica al centro della volta che simula uno sguardo verso il cielo con balaustra e figure.', 'artistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('sfondamento-illusionistico-dello-spazio', 'Sfondamento illusionistico dello spazio', 'Effetto visivo creato da Mantegna per trasformare lo spazio reale in un''ariosa loggia marmorea.', 'artistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('camera-picta', 'Camera Picta', 'Nome alternativo della Camera degli Sposi, letteralmente ''camera dipinta'', per sottolineare la totale integrazione tra architettura reale e pittura.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('clipeo', 'Clipeo', 'Forma ovale o tonda, spesso usata come cornice per ritratti o emblemi, qui utilizzata da Mantegna per i busti degli imperatori romani sul soffitto.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('parata-sententiarum', 'Parata sententiarum', 'Disposizione ordinata e solenne dei personaggi secondo un rigido protocollo gerarchico e cerimoniale, tipica della rappresentazione della corte rinascimentale.', 'compositivo', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('oculus', 'Oculus', 'Apertura circolare o finestra, in questo contesto riferita all''effetto illusionistico del soffitto della Camera degli Sopi che simula un''apertura verso il cielo.', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('spazio-allantica', 'Spazio all''antica', 'Spazio architettonico ricostruito secondo i canoni dell''architettura classica romana, con colonne, fregi e proporzioni derivanti dall''antichità, usato da Mantegna per inquadrare le figure contemporanee.', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('programma-iconografico-celebrativo', 'Programma iconografico celebrativo', 'Complesso sistema di immagini ideato per esaltare la potenza, la legittimità e la cultura di una dinastia (in questo caso i Gonzaga), mescolando ritratti reali, allegorie e riferimenti storici.', 'metodologico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('effetto-illusionistico', 'Effetto illusionistico', 'Risultato visivo ottenuto mediante l''uso accurato della prospettiva, della luce e del colore che fa apparire gli elementi dipinti come se fossero reali e tridimensionali.', 'visivo', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('polittico-delle-superificie', 'Polittico delle superificie', 'Concetto riferito alla scomposizione delle pareti in pannelli narrativi autonomi ma collegati, simile alla struttura di un polittico su tavola, qui applicato alla decorazione parietale.', 'compositivo', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('ritmi-e-toni', 'Ritmi e toni', 'Organizzazione temporale e cromatica della composizione pittorica, dove Mantegna dimostra maestria nel dosare le pause e le accentuazioni cromatiche per guidare l''occhio dello spettatore.', 'formale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('programma-iconografico', 'Programma iconografico', 'Sistema organizzato di immagini e simboli volto a comunicare un messaggio specifico o celebrativo', 'metodologia', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('sfondato', 'Sfondato', 'Effetto di profondità spaziale ottenuto mediante l''architettura dipinta che sembra fondersi con lo spazio reale', 'effetto visivo', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('scene-mitologiche', 'Scene mitologiche', 'Rappresentazioni di episodi tratti dalla mitologia classica usati come allegoria di virtù politiche e morali', 'soggetto', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('mascherone', 'Mascherone', 'Elemento decorativo a forma di faccia, spesso grottesca, usato in architettura e decorazione', 'elemento decorativo', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('bassorilievo', 'Bassorilievo', 'Scultura o rappresentazione pittorica che imita il rilievo a basso profilo tipico dell''arte classica romana', 'tecnica artistica', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('pittura-celebrativa', 'Pittura celebrativa', 'Genere pittorico volto a esaltare eventi storici, trionfi militari o figure di potere attraverso rappresentazioni monumentali e solenni', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('trombettieri-e-portatori-dinsegne', 'Trombettieri e portatori d''insegne', 'Figure che accompagnano il corteo trionfale nei Trionfi di Cesare, rappresentati nella prima ottava del ciclo pittorico', 'iconografico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('studiolo', 'Studiolo', 'Ambiente privato destinato allo studio e alla contemplazione, tipico delle residenze principesche rinascimentali, spesso decorato con opere d''arte simboliche', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('grotta', 'Grotta', 'Nello Studiolo di Isabella d''Este, ambiente femminile che si configura come spazio emblematico della cultura cortigiana dell''epoca', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('quadri-a-tema-mitologico', 'Quadri a tema mitologico', 'Opere pittoriche con soggetti tratti dalla mitologia classica, utilizzate per la decorazione dello Studiolo secondo un programma allegorico preciso', 'iconografico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('recupero-dellantico', 'Recupero dell''antico', 'Riferimento all''arte e cultura classica greco-romana come modello ideale', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('gusto-antiquario', 'Gusto antiquario', 'Interesse per le antichità, le rovine e gli oggetti dell''antichità classica', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('realismo-ed-espressivita', 'Realismo ed espressività', 'Rappresentazione fedele della realtà fisica unita alla capacità di trasmettere emozioni e sentimenti intensi', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('ambiente-illusionistico-e-dilatazione-spaziale', 'Ambiente illusionistico e dilatazione spaziale', 'Creazione di uno spazio fittizio che sembra prolungare l''architettura reale, ampliando la percezione dello spazio', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('inedito-rapporto-tra-cornice-e-spazio-dipinto', 'Inedito rapporto tra cornice e spazio dipinto', 'Integrazione tra i limiti fisici dell''opera e lo spazio rappresentato al suo interno', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('tratto-inciso', 'Tratto inciso', 'Linee nette e precise che definiscono i contorni, tipiche dell''incisione e della grafica', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('assoluto-rigore-prospettico', 'Assoluto rigore prospettico', 'Applicazione rigorosa e matematica delle regole della prospettiva lineare', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('gioco-tra-realta-e-finzione', 'Gioco tra realtà e finzione', 'Alternanza o sovrapposizione tra elementi reali e immaginari nell''opera d''arte', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('punti-di-vista-ribassati-e-ravvicinati', 'Punti di vista ribassati e ravvicinati', 'Prospettiva assunta dall''osservatore in posizione bassa e vicina al soggetto', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('san-sebastiano', 'San Sebastiano', 'Martire cristiano raffigurato spesso legato a un albero o colonna e trafitto da frecce', 'iconografia', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('sacra-conversazione', 'Sacra conversazione', 'Composizione pittorica in cui la Madonna col Bambino è circondata da santi in un unico spazio unificato', 'iconografia', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('dormito-virginis', 'Dormito Virginis', 'Dormizione della Vergine, tema iconografico che rappresenta la morte (dormizione) di Maria', 'iconografia', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('compianto-sul-cristo-morto', 'Compianto sul Cristo morto', 'Scena della deposizione o lamentazione sul corpo di Cristo dopo la crocifissione', 'iconografia', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('arte-franco-fiamminga', 'Arte franco-fiamminga', 'Produzione artistica originaria delle Fiandre e della Francia settentrionale, caratterizzata da attenzione al dettaglio naturalistico e uso dell''olio', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('congiuntura-nord-sud', 'Congiuntura Nord-Sud', 'Fusione tra il gusto fiammingo e quello italiano, effettacemente sintetizzata nell''espressione ''congiuntura Nord-Sud'' durante il regno di Ferdinando I d''Aragona', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('proporzioni-anticlassiche', 'Proporzioni anticlassiche', 'Uso di proporzioni che si discostano dai canoni classici dell''antichità e del primo Rinascimento, tipiche di alcune soluzioni architettoniche e plastiche del tardo Quattrocento', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('castel-nuovo-maschio-angioino', 'Castel Nuovo / Maschio Angioino', 'Fortezza angioina trasformata da Alfonso d''Aragona in residenza regale attraverso un intervento di rinnovamento architettonico diretto da Guillem Sagrera', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('cappella-piccolomini', 'Cappella Piccolomini', 'Cappella nella chiesa di Sant''Anna dei Lombardi a Napoli che ospita il Monumento funebre di Alfonso d''Aragona di Benedetto da Maiano', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('effetto-teatrale', 'Effetto teatrale', 'Risultato scenografico ottenuto dalla combinazione di elementi scultorei (statue, paraste) e elementi decorativi (tende aperte) che creano uno spazio scenico intorno al monumento funebre', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('altorilievo-classicheggiante', 'Altorilievo classicheggiante', 'Rilievo scultoreo che richiama i modelli dell''arte classica romana per stile e composizione', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('arco-trionfale', 'Arco trionfale', 'Monumento architettonico celebrativo a forma di arco, derivato dai modelli romani antici, utilizzato per commemorare vittorie militari o ingressi solenni', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('fregio-scoltoreo', 'Fregio scoltoreo', 'Banda decorativa orizzontale contenente rilievi scultorei, nell''arco raffigura Alfonso d''Aragona', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('repertorio-classico', 'Repertorio classico', 'Insieme di modelli formali derivati dall''arte classica greca e romana, ripresi e rielaborati dagli artisti rinascimentali', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('sistema-tardogotico', 'Sistema tardogotico', 'Linguaggio artistico tardo-medievale caratterizzato da motivi decorativi complessi e linee curve, ancora presente in opere formalmente rinascimentali come l''arco di Castel Nuovo', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('busto-ritratto', 'busto-ritratto', 'Ritratto scultoreo che rappresenta solo testa, collo e parte superiore del busto', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('ritratto-virile', 'Ritratto virile', 'Tipo di ritratto maschile realizzato da Antonello da Messina, caratterizzato dalla precisione nordica per il dettaglio derivata dall''influenza fiamminga.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('impostazioni-geometriche-e-prospettiche', 'Impostazioni geometriche e prospettiche', 'Caratteristica delle opere di Antonello dopo il viaggio a Roma del 1459, che conferisce alle figure saldezza volumetrica e monumentale.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('tono-meditativo', 'Tono meditativo', 'Qualità compositiva che non lascia spazio al patetismo o all''espressionismo tipico dell''approccio nordico, orientando invece verso la contemplazione silenziosa', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('prospettiva-aerea', 'Prospettiva aerea', 'Sistema di rappresentazione dello spazio che tiene conto degli effetti atmosferici sulla percezione della profondità', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('ritratto-di-tre-quarti', 'Ritratto di tre quarti', 'Tipologia ritrattistica in cui il soggetto è rappresentato con il volto ruotato di tre quarti rispetto all''osservatore, innovazione introdotta da Antonello rispetto al profilo', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('mezzo-busto', 'Mezzo busto', 'Taglio compositivo del ritratto che include testa e torace, permettendo maggiore naturalezza ed espressione dello stato d''animo', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('patrizio', 'Patrizio', 'Membro dell''aristocrazia nella Repubblica di Venezia. Solo i patrizi potevano sedere nel Maggior Consiglio, principale organo di governo della città.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('soggiorno-veneziano', 'Soggiorno veneziano', 'Periodo trascorso da Antonello da Messina a Venezia (agosto 1475 - marzo 1476), importante occasione di riflessione sulla resa luministica e cromatica', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('componente-fiamminga', 'Componente fiamminga', 'Elemento stilistico derivato dall''arte nordica caratterizzato dall''attenzione ai dettagli realistici, alla resa materica degli oggetti e alla luce diffusa', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('realismo-dei-volti', 'Realismo dei volti', 'Rappresentazione fedele dei lineamenti umani con attenzione alle sensazioni tattili delle epidermidi', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('bellezza-ideale-del-nudo', 'Bellezza ideale del nudo', 'Concetto estetico rinascimentale basato su masse e volumi perfettamente proporzionati secondo i canoni della statuaria classica', 'estetico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('visto-dal-basso-di-sotto-in-su', 'Visto dal basso (di sotto in su)', 'Punto di vista prospettico che rappresenta il soggetto da posizione inferiore, accentuandone la monumentalità', 'compositivo', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('chiaroscuro-modellato', 'Chiaroscuro modellato', 'Uso delicato della luce e dell''ombra per definire i volumi corporei e addolcire le forme geometriche', 'tecnico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('iconografia-umanistica', 'Iconografia umanistica', 'Rappresentazione del santo studioso in un ambiente culturale ricco di libri e strumenti scientifici, tipica della sensibilità rinascimentale', 'iconografico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('prospettiva-lineare', 'Prospettiva lineare', 'Sistema di rappresentazione dello spazio basato su punti di fuga e linee convergenti', 'tecnico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('elementi-fiamminghi', 'Elementi fiamminghi', 'Caratteristiche derivate dalla pittura nordica come l''attenza ai dettagli minuziosi, la resa materica degli oggetti e la luce diffusa', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('spazio-composito-di-sapore-gotico-rinascimentale', 'Spazio composito di sapore gotico-rinascimentale', 'Spazio illusionistico che si spalanca su un ambiente caratterizzato da elementi architettonici di transizione tra il tardo gotico e il primo Rinascimento, con ascendenza aragonese', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('cornice', 'Cornice', 'Arco di pietra dalle forme catalane che incornicia la scena del San Gerolamo, funge da elemento architettonico laico e religioso', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('abito-francescano', 'Abito francescano', 'Vestito cardinalizio indossato da san Gerolamo che richiama l''umiltà francescana, scelta legata alla destinazione originaria dell''opera nella chiesa di San Lorenzo Maggiore a Napoli', 'iconografico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('scrigno', 'Scrigno', 'Mobile su cui è seduto san Gerolamo, collocato su una pedana e impregnato di libri', 'oggetto', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('prototipi-bizantini', 'Prototipi bizantini', 'Modelli architettonici derivanti dall''arte bizantina, particolarmente radicati nella tradizione veneziana per i legami storici con Oriente', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('scansione-spaziale', 'Scansione spaziale', 'Organizzazione ritmica dello spazio architettonico mediante elementi verticali (paraste) e orizzontali (architravi) che articolano la facciata in ordini sovrapposti', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('insista-geometrica-delle-forme', 'Insista geometrica delle forme', 'Caratteristica compositiva che accomuna elementi strutturali e decorativi in una rigorosa geometria, tipica dell''architettura di Santa Maria dei Miracoli', 'compositivo', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('facciata', 'Facciata', 'Prospetto principale di un edificio, che nel caso di Santa Maria dei Miracoli rivela influssi toscani nella scansione spaziale', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('porta-della-carta', 'Porta della Carta', 'Monumentale ingresso laterale del Palazzo Ducale di Venezia che si affaccia sulla Piazzetta San Marco, oggetto di rinnovamento nella prima metà del Quattrocento', 'monumentale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('frontone-semicircolare', 'Frontone semicircolare', 'Elemento decorativo superiore della facciata a forma di arco, derivato dalla tradizione bizantino-veneziana.', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('apparato-plastico-e-decorativo', 'Apparato plastico e decorativo', 'Insieme degli elementi ornamentali (tondi, cornici, modanature) che si sovrappongono alla struttura architettonica senza nasconderla o alterarla, mantenendo l''equilibrio tra struttura e decorazione.', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('marcapiano', 'Marcapiano', 'Elemento orizzontale (cornice o fregio) che separa visivamente i diversi piani di un edificio, scandendo la facciata in altezze distinte.', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('rustico', 'Rustico', 'Trattamento murario a superficie ruvida, usato tipicamente al piano inferiore dei palazzi veneziani per conferire solidità e robustezza alla base.', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('gioco-tra-pieni-e-vuoti', 'Gioco tra pieni e vuoti', 'Effetto compositivo ottenuto alternando masse piene (muri, pilastri) e aperture (finestre, logge) per creare dinamismo e leggerezza nella facciata.', 'compositivo', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('scuole-o-schole', 'Scuole o Schole', 'Associazioni laiche di liberi cittadini che commissionano grandi cicli di storie dipinte, caratterizzate dall''uso della tela come supporto.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('teleri', 'Teleri', 'Termine con cui vengono chiamati i dipinti di grandi dimensioni commissionati dalle Scuole veneziane.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('linguaggio-rinascimentale', 'Linguaggio rinascimentale', 'Nuovo linguaggio artistico con cui si confrontano i pittori veneziani nella seconda metà del Quattrocento.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('primo-mezzo-di-comunicazione-di-massa', 'Primo mezzo di comunicazione di massa', 'La stampa a caratteri mobili, che sancisce la nascita di un sistema di diffusione culturale capace di raggiungere vasti strati della popolazione europea', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('nascente-mercato-editoriale', 'Nascente mercato editoriale', 'L''attività intellettuale e commerciale che si sviluppa in Italia (seconda area dopo la Germania) durante il pieno Rinascimento grazie alla stampa', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('carattere-tipografico', 'Carattere tipografico', 'Elemento fondamentale dell''elaborazione grafica dei libri stampati, curato con particolare attenzione da Manuzio nelle sue edizioni', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('impaginazione', 'Impaginazione', 'Disposizione grafica del testo e delle immagini sulla pagina, elemento curatissimo nelle edizioni manuziane come nell''Hypnerotomachia', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('impostazione-frontale', 'Impostazione frontale', 'Composizione figurativa con soggetti rappresentati frontalmente, tipica della tradizione bizantina', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('repertori-di-immagini', 'Repertori di immagini', 'Album di disegni destinati a essere utilizzati come modelli nella bottega', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
