INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('cura-topografica', 'cura topografica', 'Rappresentazione fedele e spostata lateralmente del campanile per rendere visibile la facciata di San Marco', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('scuola-veneziana', 'Scuola (veneziana)', 'Confraternita laica veneziana, edificio destinato alle riunioni e alla devozione dei membri, spesso decorata con cicli di teleri', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('telerio', 'Telerio', 'Opera pittorica di grandi dimensioni su tela, tipica dell''arte veneziana del XV-XVI secolo', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
