INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('struttura-piramidale', 'Struttura piramidale', 'Composizione figurativa organizzata secondo forme triangolari che conferiscono stabilità e armonia all''insieme', 'compositivo', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('quattrocento', 'Quattrocento', 'Il XV secolo italiano (1401-1500), periodo fondamentale del Rinascimento early', 'storico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('umanesimo', 'Umanesimo', 'Movimento culturale che pone al centro l''uomo e la sua dignità, riscoprendo i classici antichi', 'culturale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('pala-daltare', 'Pala d''altare', 'Dipinto destinato a decorare l''altare di una chiesa, spesso di grandi dimensioni e complessità compositiva', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('impianto-prospettico', 'impianto prospettico', 'Sistema di rappresentazione dello spazio tridimensionale su superficie bidimensionale mediante punti di fuga e linee convergenti', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('aura-di-ieraticita', 'aura di ieraticità', 'Qualità di sacralità e distanza formale conferita al soggetto ritratto, tipica dei ritratti ufficiali di autorità politiche', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('ritratto-ufficiale', 'ritratto ufficiale', 'Ritratto commissionato per scopi istituzionali o pubblici, caratterizzato da formalità e simbolismo del potere', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('delizia', 'Delizia', 'Villa di piacere suburbana tipica della cultura estense, luogo di svago e riposo per la corte.', 'architettura', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('ufficiale-ferrarese', 'Ufficiale ferrarese', 'Definizione riferita allo stile particolaristico della scuola pittorica ferrarese, legato alla committenza ufficiale della corte estense.', 'storia_arte', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('officina-ferrarese', 'Officina ferrarese', 'Termine usato per indicare la produzione artistica collettiva e caratteristica della scuola ferrarese del Quattrocento.', 'storia_arte', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('addizione-erculea', 'Addizione Erculea', 'Nome del grande progetto di ampliamento urbano di Ferrara voluto da Ercole I d''Este e progettato da Biagio Rossetti', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('andamento-rettilineo-e-ortogonale', 'andamento rettilineo e ortogonale', 'Sistema di tracciato viario caratterizzato da strade rette che si incrociano formando angoli retti', 'urbanistica', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('citta-ideale', 'città ideale', 'Modello teorico di città rinascimentale basato su geometria razionale, simmetria e proporzioni matematiche', 'urbanistica', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('muse', 'Muse', 'Nella mitologia greca, nove dee protettrici delle arti; nel Rinascimento oggetto di raffigurazioni allegoriche negli studioli umanistici', 'iconografia', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('calliope', 'Calliope', 'Musa della poesia epica, identificabile nella figura dipinta da Tura', 'mitologico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('erato', 'Erato', 'Musa della poesia amorosa, alternativa identificazione della figura dipinta da Tura', 'mitologico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('studio-dei-belfiore', 'Studio dei Belfiore', 'Luogo per cui fu dipinta l''opera Calliope/Erato', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('paesaggi-calligrafici', 'Paesaggi calligrafici', 'Caratteristica stilistica di Tura riconducibile all''influenza del modello nordico/fiammingo', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('borgogna', 'Borgogna', 'Area culturale di riferimento per lo stile calligrafico e i dettagli nitidi dell''arte di Tura', 'geografico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('fiamminga', 'Fiamminga', 'Arte del Nord Europa che influenza lo stile di Tura nei dettagli e nelle scelte iconografiche', 'geografico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('stile-aspro-e-metallico', 'Stile aspro e metallico', 'Caratteristica stilistica di Tura definita da lineariismi tormentati, aguzzi e netti, con effetti di brillantezza metallica ottenuti attraverso contrasti di luce', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('gotico-cortese', 'Gotico-cortese', 'Componente stilistica presente nell''opera di Tura, derivante dalla tradizione gotica internazionale e dalle corti signorili', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('componente-nordica', 'Componente nordica', 'Influenza artistica proveniente dall''Europa settentrionale (area renana e fiamminga) visibile nell''attenzione ai dettagli, nel realismo e nell''espressività drammatica', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('anatomia-distorta', 'Anatomia distorta', 'Rappresentazione non naturalistica del corpo umano, con proporzioni allungate e pose innaturali, tipica del tardo gotico e del primo Rinascimento ferrarese', 'formale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('sapienza-antiquaria', 'Sapienza antiquaria', 'Conoscenza e rielaborazione dell''arte classica romana e greca, tipica dell''umanesimo rinascimentale', 'culturale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('committenti-privati', 'Committenti privati', 'Meccenate non istituzionali che commissionavano opere d''arte per uso personale o domestico, pratica diffusa nel Rinascimento italiano', 'sociale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('scomparto', 'scomparto', 'Sezione di un polittico o di un''opera divisa in parti', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('naturalistica', 'naturalistica', 'Rappresentazione artistica che imita la natura', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('metallica', 'metallica', 'Effetto cromatico che richiama i metalli', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('fantastico', 'fantastico', 'Elemento immaginario e creativo nell''arte', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('irreale', 'irreale', 'Che non appartiene alla realtà', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('plastrone', 'plastrone', 'Elemento decorativo o strutturale interno di un polittico', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('unificante-della-politica-griffoniana', 'Unificante della politica griffoniana', 'Caratteristica del Polittico Griffoni che riflette l''inserimento dei committenti (famiglia Griffoni) nella zona centrale del potere politico bolognese, con personaggi fantastici in spazi tridimensionali', 'storico-artistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('stile-personale-maturo', 'Stile personale maturo', 'Fase artistica di Ercole de'' Roberti successiva al 1487, caratterizzata da sintesi tra tradizione ferrarese e influssi veneziani.', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('formalismo-arido', 'Formalismo arido', 'Caratteristica dello stile di Ercole de'' Roberti, definito da una rigida aderenza alle forme e a una rappresentazione potente e deformata.', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('compostezza-classica', 'Compostezza classica', 'Qualità delle figure di Roberti nella Pala Portonese, derivate dallo studio dell''arte antica e contemporanea di Giovanni Bellini.', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('pathos-intenso', 'Pathos intenso', 'Capacità dell''opera d''arte di suscitare forti emozioni, partecipazione emotiva e commozione nello spettatore attraverso la rappresentazione drammatica e toccante del soggetto.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('naturalismo-tardogotico-doltalpe', 'Naturalismo tardogotico d''Oltalpe', 'Corrente artistica sviluppatasi oltre le Alpi (area renana e fiamminga) nel tardo Medioevo, caratterizzata da un''attenzione minuziosa ai dettagli naturali, all''espressione drammatica e a una resa realistica delle emozioni umane.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('espressivita-deformante', 'Espressività deformante', 'Tendenza artistica a modificare, alterare o deformare le forme naturali per accentuarne l''espressione emotiva, in contrasto con l''ideale classico di armonia e proporzione.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('anticlassico', 'Anticlassico', 'Che si distacca dai canoni classici di bellezza basati su armonia, proporzione e equilibrio, preferendo invece soluzioni formali originali, talvolta irregolari o emotivamente cariche.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('disciplini-confraternita', 'Disciplini (confraternita)', 'Confraternite religiose dedite alla disciplina (autoflagellazione) e alle pratiche devozionali, spesso committenti di opere d''arte a tema devozionale e penitenziale.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('decani', 'Decani', 'Periodi della durata di dieci giorni ciascuno, secondo le credenze astrologiche sono i periodi che influenzano la personalità e le vicende umane nelle varie decadi', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('trionfo', 'Trionfo', 'Rappresentazione allegorica della vittoria di una figura simbolica sulle altre, tipica dell''iconografia medievale e rinascimentale', 'iconografico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('costellazioni-zodiacali', 'Costellazioni zodiacali', 'Le dodici costellazioni attraverso cui passa il sole durante l''anno, rappresentate nella fascia mediana del ciclo dei Mesi', 'astronomico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('salone-dei-mesi', 'Salone dei Mesi', 'Sala di Palazzo Schifanoia a Ferrara decorata con il celebre ciclo di affreschi raffiguranti i dodici mesi dell''anno', 'luogo', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('buon-governo', 'Buon governo', 'Concetto politico-ideologico rappresentato nel ciclo di affreschi per legittimare il potere di Borso d''Este, associato alle virtù celesti e alla prosperità del territorio', 'politico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('iconografia-decani', 'Iconografia decani', 'Sistema di rappresentazione astrologica basato sui decani (suddivisioni dello zodiaco), utilizzata nel profilo iconografico del ciclo per interpretare i significati allegorici', 'iconografico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('mese-di-ginevra', 'Mese di Ginevra', 'Riferimento al calendario o a figura allegorica presente nel ciclo dei Mesi', 'iconografico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('trionfi', 'Trionfi', 'Forma allegorica letteraria creata da Petrarca, rappresentata da sei carri trionfali (Amore, Castità, Morte, Fama, Tempo, Eternità) che simboleggiano la supremazia progressiva di valori spirituali sui terreni', 'letterario', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('virtusimusi', 'Virtusimusi', 'Termine che indica le virtù proprietarie di Mantegna, richiamate nel testo come modello di riferimento per la rappresentazione delle figure virtuose nella fascia inferiore', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('zodiaco-accidentale', 'Zodiaco accidentale', 'Sistema di corrispondenze astrali che collega i segni zodiacali agli eventi umani e alla ''Scienza'' astrologica, fondamentale per la lettura simbolica del ciclo di Schifanoia', 'astronomico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('palo-di-santagata', 'Palo di Sant''Agata', 'Manifestazione fondamentale della città di Ferrara, evento storico-culturale documentato anche nelle fonti iconografiche come gli affreschi di Palazzo Schifanoia', 'storico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('trattato-di-architettura', 'Trattato di architettura', 'Opera scritta da Filarete tra il 1460 e il 1464, contenente la descrizione teorica dei principi architettonici rinascimentali, il progetto della città ideale di Sforzinda e le regole costruttive. Rappresenta uno dei primi tentativi di sistematizzare l''architettura rinascimentale in Italia settentrionale.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('sforzinda', 'Sforzinda', 'Città ideale descritta da Filarete nel suo Trattato, a pianta stellare ottagonale ispirata agli schemi di Alberti, pensata come modello urbanistico perfetto.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('quattro-chiostri', 'Quattro chiostri', 'Elemento caratteristico dell''Ospedale Maggiore: spazi chiusi su quattro lati da portici, destinati alla deambulazione dei malati e alla contemplazione, organizzati lungo un asse longitudinale.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('bifora', 'Bifora', 'Finestra divisa in due aperture da una colonna o pilastro centrale, spesso con arco. Nella facciata dell''Ospedale Maggiore sono presenti bifore ad archi ogivali, elemento di compromesso tra gotico e rinascimento.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('cornicione', 'Cornicione', 'Elemento orizzontale sporgente che conclude la parte superiore di una facciata o di un edificio. Nell''opera di Filarete assume funzione di raccordo tra le diverse parti dell''edificio.', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('fossato', 'Fossato', 'Canale o scavo difensivo che circonda la città ideale di Sforzinda, situato tra le mura esterne e le torri angolari', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('piazza-porticata', 'Piazza porticata', 'Spazio pubblico centrale di Sforzinda, dotato di portici, destinato al mercato e alla vita civile, con il palazzo del principe e gli edifici pubblici circostanti', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('certosa', 'Certosa', 'Monastero di monaci certosini, ordine religioso fondato da San Bruno nel 1084, caratterizzato dalla vita eremitica e dalla clausura rigorosa', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('mausoleo-dinastico', 'Mausoleo dinastico', 'Edificio funerario monumentale destinato ad accogliere le salme dei membri di una famiglia nobile o regnante', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('presbiterio', 'Presbiterio', 'Parte della chiesa attorno all''altare maggiore, riservata al clero durante le celebrazioni liturgiche', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('transetto', 'Transetto', 'Navata trasversale in una chiesa a croce latina, che interseca la navata maggiore in prossimità del presbiterio', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('cripta', 'Cripta', 'Ambiente sotterraneo di una chiesa, generalmente situato sotto il presbiterio, contenente tombe o reliquie', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('gotico-internazionale', 'Gotico internazionale', 'Stile artistico diffuso in Europa tra il 1375 e il 1425 circa, caratterizzato da eleganza lineare, ricchezza decorativa e aristocraticismo formale', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('rinascimento-lombardo', 'Rinascimento lombardo', 'Manifestazione regionale del Rinascimento italiano sviluppatasi in Lombardia nel XV secolo, caratterizzata dalla fusione di elementi toscani con tradizioni locali tardogotiche', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('certosa-delle-grazie', 'Certosa delle Grazie', 'Complesso monastico certosino di Pavia, sede della decorazione pittorica del Bergognone', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('provanzale-ligure', 'provanzale-ligure', 'Stile artistico riferibile all''area provenzale e ligure, presente nella pittura del Bergognone', 'generale', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('serenissima', 'Serenissima', 'Nome con cui era nota la Repubblica di Venezia, potenza marinara e terrena che dominava parte del territorio italiano settentrionale nel Quattrocento', 'storico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('linguaggio-toscano', 'linguaggio toscano', 'Stile artistico caratterizzato da rigore geometrico, proporzioni classiche e riferimento diretto all''antichità romana, tipico dell''arte fiorentina del primo Rinascimento', 'artistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('elementi-toscani-e-lombardi', 'elementi toscani e lombardi', 'Nell''ambito del monumento funebre veneziano: combinazione tra la solennità classica della tradizione toscana (Verrocchio) e la ricchezza decorativa, il gusto per i dettagli minuziosi e il colore propri della tradizione lombarda (Amadeo)', 'artistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('naturalismo-elementare', 'naturalismo elementare', 'Caratteristica dell''opera matura di Foppa, anticipo di una tendenza che diventerà dominante nella cultura figurativa lombarda successiva', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('sviluppo-piramidale', 'sviluppo piramidale', 'Composizione che si inquadra nella geometria classica di un arco trionfale, elemento ripreso dai modelli sepolc quattrocenteschi di gusto rinascimentale', 'compositivo', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('prospettiva-geometrica-moderna', 'prospettiva geometrica moderna', 'Uso razionale della prospettiva per accentuare le posizioni in scorcio delle croci laterali nell''opera di Foppa', 'prospettico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('parapetto-marmoreo', 'parapetto marmoreo', 'Elemento architettonico usato per separare lo spazio reale dello spettatore dalla rappresentazione fittizia, tipico della pittura rinascimentale', 'architettonico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.terms (id, term, definition, category, period_ids, is_archetype) VALUES ('modello-tardo-gotico', 'modello tardo-gotico', 'Elementi stilistici residui (boschetti lumeggiati d''oro, sentiero che conduce alla scenografia) presenti nell''opera di Foppa accanto alle innovazioni rinascimentali', 'stilistico', '{}', false) ON CONFLICT (id) DO UPDATE SET term = EXCLUDED.term, definition = COALESCE(NULLIF(EXCLUDED.definition, ''), terms.definition);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('affreschi-della-cappella-ovetari', 'Affreschi della cappella Ovetari', '{andrea-mantegna-con-giovanni-dalemagna-antonio-vivarini-niccolo-pizzolo}', NULL, '1449-1455', 1449, 1455, 'affresco', '{}', '{}', 'Padova', 'Chiesa degli Eremitani, transetto destro', NULL, NULL, 1, 0, 0, '', 3, 'Decorazione ad affresco della cappella Ovetari commissionata dalla famiglia Ovetari. Opera collettiva realizzata da due gruppi: primo gruppo con veneziani (Giovanni d''Alemagna, Antonio Vivarini), secondo gruppo con padovani (Andrea Mantegna e Niccolò Pizzolo). Include Storie di san Giacomo Maggiore, Storie di san Cristoforo e l''Assunzione. Distrutta durante la Seconda guerra mondiale, rimangono solo due porzioni riportate su tela nell''Ottocento.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('martirio-e-trasporto-del-corpo-di-san-cristoforo', 'Martirio e trasporto del corpo di san Cristoforo', '{andrea-mantegna}', NULL, '1449-1455', 1449, 1455, 'affresco', '{}', '{}', 'Padova', 'Cappella Ovetari, Chiesa degli Eremitani', NULL, NULL, 1, 0, 0, '', 2, 'Scena sopravvissuta (in parte) degli affreschi della cappella Ovetari. I due episodi sono ambientati in un unico spazio, una città immaginaria in stile veneziano con strutture classicheggianti e pergolato ligneo.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('decorazione-della-camera-degli-sposi', 'Decorazione della Camera degli Sposi', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Palazzo Ducale', NULL, NULL, 1, 0, 0, '', 3, 'Grande ciclo decorativo realizzato da Mantegna come pittore di corte dei Gonzaga.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('pala-di-san-zeno', 'Pala di San Zeno', '{andrea-mantegna}', NULL, '1456-1459', 1456, 1459, 'tavola', '{}', '{}', 'Verona', 'Basilica di San Zeno', NULL, NULL, 1, 0, 0, '', 3, 'Pala d''altare realizzata da Mantegna per la basilica veronese.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('compianto-sul-cristo-morto', 'Compianto sul Cristo morto', '{andrea-mantegna}', NULL, 'dopo il 1475', 1475, NULL, 'tela', '{}', '{}', 'Milano', 'Pinacoteca di Brera', NULL, NULL, 1, 0, 0, '', 3, 'Opera di matura compiutezza realizzata dopo il 1475.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('trionfi-di-cesare-in-gallia', 'Trionfi di Cesare in Gallia', '{andrea-mantegna}', NULL, '1485-1505', 1485, 1505, 'tela', '{}', '{}', 'Londra', 'Hampton Court Palace', NULL, NULL, 1, 0, 0, '', 3, 'Ciclo di tele celebranti i trionfi di Giulio Cesare, realizzato nel periodo mantovano.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('altare-del-santo-di-donatello', 'Altare del Santo di Donatello', '{donatello}', NULL, '', NULL, NULL, 'scultura', '{}', '{}', 'Padova', 'Basilica del Santo', NULL, NULL, 1, 0, 0, '', 1, 'Opera scultorea citata come probabile riferimento strutturale per la Pala di San Zeno, in particolare per la disposizione dei santi e l''uso dello spazio architettonico unitario.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('pala-di-brera', 'Pala di Brera', '{piero-della-francesca}', NULL, '', NULL, NULL, 'tavola', '{}', '{}', 'Milano', 'Pinacoteca di Brera', NULL, NULL, 1, 0, 0, '', 1, 'Opera citata come esempio del nuovo equilibrio tra valori simbolici classici e cristiani, paragonata alla Pala di San Zeno.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('pala-di-san-zeno-polittico-di-san-zeno', 'Pala di San Zeno (Polittico di San Zeno)', '{andrea-mantegna}', NULL, '1456-1459', 1456, 1459, 'polittico', '{}', '{}', 'Verona', 'Basilica di San Zeno', NULL, NULL, 1, 0, 0, '', 3, 'Grande pala d''altare con struttura architettonica che incornicia le figure sacre in uno spazio unico. Al centro Madonna col Bambino in trono, affiancata da santi in nicchie architettoniche. Predella con tre scene della Passione. Composizione ispirata all''Altare del Santo di Donatello.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('altare-del-santo-altare-di-santantonio-da-padova', 'Altare del Santo (Altare di Sant''Antonio da Padova)', '{donatello}', NULL, '1444-1450', 1444, 1450, 'scultura', '{}', '{}', 'Padova', 'Basilica del Santo', NULL, NULL, 1, 0, 0, '', 2, 'Complesso scultoreo con struttura architettonica che ospita le figure dei santi in un unico spazio unitario, modello compositivo per la Pala di San Zeno di Mantegna.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('pala-di-brera-montefeltro-altarpiece', 'Pala di Brera (Montefeltro Altarpiece)', '{piero-della-francesca}', NULL, '1472-1474', 1472, 1474, 'tavola', '{}', '{}', 'Milano', 'Pinacoteca di Brera', NULL, NULL, 1, 0, 0, '', 2, 'Opera citata come esempio di composizione simmetrica e classica con valori simbolici al centro, paragonata alla concezione della Pala di San Zeno.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('morte-della-vergine', 'Morte della Vergine', '{andrea-mantegna}', NULL, '1462 circa', 1462, 1462, 'tavola', '{}', '{}', 'Madrid', 'Museo del Prado', NULL, NULL, 1, 0, 0, '', 3, 'Primo incarico affidato da Ludovico Gonzaga a Mantegna, decorazione della cappella del castello di San Giorgio, appena rinnovata. La scena si svolge in un ambiente architettonico con pavimento a scacchiera; la Vergine giace sul catafalco centrale, gli apostoli sono raffigurati con espressioni e atteggiamenti di grande naturalezza. San Giovanni incensa il corpo, san Pietro è collocato sull''asse di simmetria verticale. Lo sguardo dello spettatore è richiamato in profondità dal paesaggio visibile oltre la porta-finestra sullo sfondo.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('san-sebastiano', 'San Sebastiano', '{andrea-mantegna}', NULL, '1482-1485 circa', 1482, 1485, 'tela', '{}', '{}', 'Parigi', 'Musée du Louvre', NULL, NULL, 1, 0, 0, '', 3, 'Dipinto ascrivibile con certezza alla committenza gonzaghesca, donato come regalo per il nozze Gilbert de Bourbon. Il santo è in primo piano, la rovina è circodata da fregi. Rispetto alla versione precedente della bellezza quattuoraria, appare nuovamente rigido, all''espressività germinale ribassata. La postura meno contratta e serpentina suggerisce uno schema classico, la maggiore carica del santo pronta a resistere. L''accenno espressiva del volto, i smi dei tratti somatici degli arceri, in la minuta descrizione degli elementi in paesaggio sullo sfondo riceve una influenza nordici assimilati dall''artista.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('camera-degli-sposi', 'Camera degli Sposi', '{andrea-mantegna}', NULL, 'dal 1465', 1465, NULL, 'affresco', '{}', '{}', 'Mantova', 'Castello di San Giorgio, torzione di nord-est', NULL, NULL, 1, 0, 0, '', 2, 'Decorazione di una piccola stanza nel torzione di nord-est del castello di San Giorgio, affidata a Mantegna nel 1465.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('compianto-sul-cristo-morto-cristo-morto', 'Compianto sul Cristo morto (Cristo morto)', '{andrea-mantegna}', NULL, 'post 1475, tempera a colla su tela', 1475, NULL, 'tela', '{}', '{}', 'Milano', 'Pinacoteca di Brera', NULL, NULL, 1, 0, 0, '', 3, 'Rappresentazione del Cristo morto disteso su un sarcofago di porfido rosso, visto in prospettiva dal basso (di sotto in sù), con i piedi in primo piano e il capo reclinato indietro. L''opera presenta una forte caratterizzazione scultorea, con un realismo drammatico che enfatizza i dettagli anatomici e le ferite della passione.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('decorazione-della-camera-degli-sposi-camera-picta', 'Decorazione della Camera degli Sposi (Camera Picta)', '{andrea-mantegna}', NULL, '1465', 1465, NULL, 'affresco', '{}', '{}', 'Mantova', 'Castello di San Giorgio, torrione nord-est', NULL, NULL, 1, 0, 0, '', 2, 'Decorazione di una piccola stanza nel torrione del castello dei Gonzaga, eseguita nel 1465 su commissione di Ludovico Gonzaga.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('incontro-tra-ludovico-gonzaga-e-il-cardinale-francesco-gonzaga', 'Incontro tra Ludovico Gonzaga e il cardinale Francesco Gonzaga', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Camera degli Sposi, parete nord', NULL, NULL, 1, 0, 0, '', 2, 'Scena di corte che ritrae il marchese Ludovico Gonzaga con la famiglia e il figlio cardinale, in un ambiente domestico e politico.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('corteggio-della-duchessa-barbara-di-brandeburgo', 'Corteggio della duchessa Barbara di Brandeburgo', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Camera degli Sposi, parete est', NULL, NULL, 1, 0, 0, '', 2, 'Scena che raffigura la duchessa Barbara di Brandeburgo seguita dal suo corteggio, con un servo nero in primo piano.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('volta-della-camera-degli-sposi', 'Volta della Camera degli Sposi', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Camera degli Sosti, soffitto', NULL, NULL, 1, 0, 0, '', 3, 'Affreschi del soffitto con oculus centrale illusionistico (*di sotto in su*), putti e clipei con busti dei primi imperatori romani.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('camera-degli-sposi-camera-picta', 'Camera degli Sposi (Camera Picta)', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Palazzo Ducale, Torre della Gabbia', NULL, NULL, 1, 0, 0, '', 3, 'Ciclo di affreschi che decorano una sala del Palazzo Ducale di Mantova, commissionato da Ludovico III Gonzaga. Comprende scene di corte, celebrazioni dinastiche, ritratti della famiglia Gonzaga e elementi architettonici illusionistici che dilatano lo spazio reale.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('scena-di-corte-e-celebrazione-di-gonzaga', 'Scena di corte e celebrazione di Gonzaga', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Camera degli Sposi, parete nord', NULL, NULL, 1, 0, 0, '', 3, 'La parete principale (nord) mostra il marchese Ludovico Gonzaga in conversazione con la moglie Barbara di Brandeburgo e la corte, circondati da figli, cani e segretari. Scena di vita quotidiana elevata a cerimoniale attraverso la composizione rigorosa e l''uso della prospettiva.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('parete-occidentale---incontro-col-figlio-francesco', 'Parete occidentale - Incontro col figlio Francesco', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Camera degli Sposi, parete ovest', NULL, NULL, 1, 0, 0, '', 2, 'Rappresenta l''incontro tra il marchese Ludovico e il figlio secondogenito Francesco, nominato cardinale grazie all''interesse dello stesso Francesco Sforza, duca di Milano. Simboleggia l''alleanza tra le casate Gonzaga e Sforza e l''ideale umanistico di Roma.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('ritratto-di-leon-battista-alberti', 'Ritratto di Leon Battista Alberti', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Camera degli Sposi, parete ovest', NULL, NULL, 1, 0, 0, '', 2, 'Ritratto dell''architetto e umanista Leon Battista Alberti inserito nella scena dell''incontro, riconoscibile dai monumenti all''epoca Mantegnesco (Colosseo, Arco di Adriano, mausoleo). Testimonia la presenza e l''influenza degli intellettuali alla corte mantovana.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('ritratto-di-vittore-da-feltre', 'Ritratto di Vittore da Feltre', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Camera degli Sposi, parete ovest', NULL, NULL, 1, 0, 0, '', 2, 'Ritratto dell''umanista Vittore da Feltre, precursore dei principi pedagogici presenti nell''opera. Presente nella scena dell''incontro tra Ludovico e il figlio cardinale.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('scena-dellincontro-parete-nord', 'Scena dell''Incontro (parete nord)', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Camera degli Sposi, parete nord', NULL, NULL, 1, 0, 0, '', 2, 'Scena dell''incontro tra il marchese Federico Gonzaga (figlio di Ludovico) e il cardinale Francesco Gonzaga, con il segretario Cristoforo da Dianquè. Momento di dialogo politico e familiare reso con rigore compositivo.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('particolare-decorativo-ornato', 'Particolare decorativo (ornato)', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Camera degli Sposi, dettaglio ornamentale', NULL, NULL, 1, 0, 0, '', 1, 'Particolare del ricco apparato decorativo che incornicia le scene narrative, con motivi vegetali, antropomorfi e elementi classici che richiamano l''architettura romana antica.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('parete-ovest---scena-dellincontro', 'Parete ovest - Scena dell''Incontro', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Palazzo Ducale, Camera degli Sposi, parete ovest', NULL, NULL, 1, 0, 0, '', 2, 'Scena raffigurante l''incontro tra Ludovico Gonzaga, l''imperatore Federico III d''Asburgo, il figlio cardinale Federico Gonzaga e Cristiano di Danimarca. La scena presenta una solennità ufficiale con personaggi maschili in posa formale.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('parete-nord---scene-mitologiche-e-autoritratto', 'Parete nord - Scene mitologiche e autoritratto', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Palazzo Ducale, Camera degli Sposi, parete nord', NULL, NULL, 1, 0, 0, '', 2, 'Sezione della parete contenente scene mitologiche dipinte imitando bassorilievi, che alludono alle virtù politiche e militari di Ludovico Gonzaga. Include un autoritratto di Mantegna mimetizzato come mascherone sul pilastro.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('autoritratto-mascherone', 'Autoritratto (mascherone)', '{andrea-mantegna}', NULL, '1465-1474', 1465, 1474, 'affresco', '{}', '{}', 'Mantova', 'Palazzo Ducale, Camera degli Sposi, pilastro', NULL, NULL, 1, 0, 0, '', 2, 'Autoritratto dell''artista rappresentato come mascherone ornamentale su un pilastro, che divide la scena dell''Incontro dalla parte centrale della parete.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('parnaso', 'Parnaso', '{andrea-mantegna}', NULL, '1497 circa', 1497, NULL, 'tela', '{}', '{}', 'Parigi', 'Musée du Louvre', NULL, NULL, 1, 0, 0, '', 2, 'Opera realizzata per lo Studiolo di Isabella d''Este, raffigurante il mito del Parnaso. Dipinto che segna una svolta qualitativa nell''opera di Mantegna verso un''interpretazione più libera e cinquecentesca, distaccandosi dalla rigidità prospettica precedente.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('studiolo-di-isabella-deste', 'Studiolo di Isabella d''Este', '{varii-mantegna-perugino-costa-lorenzo-costa-il-vecchio}', NULL, '1490-1502', 1490, 1502, 'architettura', '{}', '{}', 'Mantova', 'Palazzo Ducale', NULL, NULL, 1, 0, 0, '', 3, 'Spazio privato creato da Isabella d''Este all''interno del Palazzo Ducale di Mantova, comprendente una biblioteca e una collezione di antichità. Decorato con quadri a tema mitologico-allegorico dai principali artisti dell''epoca, configurandosi come proposta emblematica della cultura cortigiana del tempo.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('minerva-caccia-i-vizi-dal-giardino-delle-virtu', 'Minerva caccia i Vizi dal giardino delle Virtù', '{andrea-mantegna}', NULL, '1499-1502 circa', 1499, 1502, 'tela', '{}', '{}', 'Parigi', 'Musée du Louvre', NULL, NULL, 1, 0, 0, '', 3, 'Allegoria morale in cui Isabella d''Este è identificata con Minerva, dea della sapienza, che scaccia i Vizi (figure nude, spesso animali o deforme) dal giardino delle Virtù. Opera che riflette la cultura e la saggezza della committente.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('cappella-ovetari', 'Cappella Ovetari', '{andrea-mantegna}', NULL, '', 1448, 1457, 'affresco', '{}', '{}', 'Padova', 'Chiesa degli Eremitani, Cappella Ovetari', NULL, NULL, 1, 0, 0, '', 2, 'Ciclo di affreschi giovanili che mostrano l''influenza di Donatello e l''interesse per le rovine antiche.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('cristo-morto', 'Cristo morto', '{andrea-mantegna}', NULL, '', 1480, 1480, 'tela', '{}', '{}', 'Milano', 'Pinacoteca di Brera', NULL, NULL, 1, 0, 0, '', 3, 'Opera famosa per lo scorcio prospettico estremo del corpo di Cristo.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('studio-per-una-medaglia-di-alfonso-daragona', 'Studio per una medaglia di Alfonso d''Aragona', '{pisanello}', NULL, '1449', 1449, 1449, 'tavola', '{}', '{}', 'Parigi', 'Musée du Louvre', NULL, NULL, 1, 0, 0, '', 2, 'Studio preparatorio per la medaglia di Alfonso d''Aragona, realizzato quando Pisanello era alla corte aragonese come medaglista.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('medaglia-di-alfonso-daragona', 'Medaglia di Alfonso d''Aragona', '{pisanello}', NULL, '1449', 1449, 1449, 'oreficeria', '{}', '{}', 'Parigi', 'Musée du Louvre', NULL, NULL, 1, 0, 0, '', 3, 'Medaglia bronzea di Alfonso d''Aragona realizzata da Pisanello, diametro 10,6 cm.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('trasformazione-del-castel-nuovo-maschio-angioino', 'Trasformazione del Castel Nuovo (Maschio Angioino)', '{guillem-sagrera}', NULL, 'dal 1443', 1443, NULL, 'architettura', '{}', '{}', 'Napoli', 'Castel Nuovo', NULL, NULL, 1, 0, 0, '', 3, 'Rinnovamento architettonico della fortezza angioina trasformata in residenza regale adatta a ospitare la corte aragonese, uno dei primi obiettivi del piano di rinnovamento di Alfonso d''Aragona.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('passione-di-cristo-arazzi', 'Passione di Cristo (arazzi)', '{rogier-van-der-weyden-su-cartoni-di-jean-fouquet}', NULL, '1452-1458', 1452, 1458, 'altro', '{}', '{}', NULL, NULL, NULL, NULL, 1, 0, 0, '', 2, 'Serie di arazzi raffiguranti la Passione di Cristo, realizzata su cartoni di Jean Fouquet durante il suo soggiorno napoletano.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('monumento-funebre-di-alfonso-daragona', 'Monumento funebre di Alfonso d''Aragona', '{benedetto-da-maiano}', NULL, 'dal 1490', 1490, NULL, 'scultura', '{}', '{}', 'Napoli', 'Chiesa di Sant''Anna dei Lombardi, Cappella Piccolomini', NULL, NULL, 1, 0, 0, '', 3, 'Monumento funebre sormontato da cupola, riproducente la Sacrestia Vecchia di San Lorenzo di Firenze con equilibri plastici costruiti su proporzioni anticlassiche. L''effetto è una nicchia ad arco a tutto sesto con elementi scultorei e tende aperte.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('cappella-del-cardinale-del-portogallo', 'Cappella del Cardinale del Portogallo', '{antonio-rossellino}', NULL, '1461-1466', 1461, 1466, 'architettura', '{}', '{}', 'Firenze', 'San Miniato al Monte', NULL, NULL, 1, 0, 0, '', 2, 'Opera di riferimento per il Monumento funebre di Alfonso d''Aragona di Benedetto da Maiano, con cui presenta notevoli affinità stilistiche.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('cappella-piccolomini', 'Cappella Piccolomini', '{benedetto-da-maiano-antonio-rossellino}', NULL, '1475-1490', 1475, 1490, 'architettura', '{}', '{}', 'Napoli', 'chiesa di Sant''Anna dei Lombardi', NULL, NULL, 1, 0, 0, '', 3, 'Principale esempio di architettura sacra partenopea impostata su modelli fiorentini. Presenta forma cubica sormontata da cupola che riprende la Sacrestia Vecchia di San Lorenzo di Brunelleschi. Contiene il monumento funebre di Maria d''Aragona con schema ad arcosolio e effetto teatrale.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('monumento-funebre-di-maria-daragona', 'Monumento funebre di Maria d''Aragona', '{antonio-rossellino-benedetto-da-maiano}', NULL, '1475-1490', 1475, 1490, 'scultura', '{}', '{}', 'Napoli', 'Cappella Piccolomini, chiesa di Sant''Anna dei Lombardi', NULL, NULL, 1, 0, 0, '', 2, 'Monumento funebre con schema ad arcosolio, sarcofago sormontato dalla statua della defunta inserita in nicchia ad arco a tutto sesto. Effetto teatrale degli elementi scultorei e delle tende aperte.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('porta-capuana', 'Porta Capuana', '{giuliano-da-maiano}', NULL, '1484', 1484, NULL, 'architettura', '{}', '{}', 'Napoli', NULL, NULL, NULL, 1, 0, 0, '', 3, 'Arco di trionfo di tipo marmoreo tra due possenti torri cilindriche merlate, decorato con altorilievi classicheggianti e sculture dei santi protettori della città (Gennaro e Aniello). In origine sormontato da edicola a timpano triangolare con nicchia contenente affresco.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('arco-trionfale-di-castel-nuovo', 'Arco trionfale di Castel Nuovo', '{pietro-di-martino-da-milano-e-francesco-laurana}', NULL, '1452-1471', 1452, 1471, 'architettura', '{}', '{}', 'Napoli', 'Castel Nuovo (Maschio Angioino)', NULL, NULL, 1, 0, 0, '', 3, 'Arco trionfale in marmo bianco inserito tra le torri medievali del castello, costruito per celebrare l''ingresso trionfale di Alfonso d''Aragona a Napoli. Struttura a due piani con archi sovrapposti, colonne binate corinzie, fregio scoltoreo raffigurante Alfonso d''Aragona e nicchie con statue delle Virtù. Ispirazione dagli archi di trionfo romani ma con elementi tardogotici e rinascimentali.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('busto-di-eleonora-o-isabella-daragona', 'Busto di Eleonora (o Isabella) d''Aragona', '{francesco-laurana}', NULL, '1487-1488', 1487, 1488, 'scultura', '{}', '{}', 'Palermo', 'Galleria Regionale della Sicilia, Palazzo Abatellis', NULL, NULL, 1, 0, 0, '', 3, 'Busto-ritratto postumo appartenente a una serie dedicata a principesse e nobildonne, caratterizzato da volumi puri, stilizzazione geometrica, lineamenti idealizzati e superfici levigate.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('san-gerolamo-nello-studio', 'San Gerolamo nello studio', '{colantonio}', NULL, '', NULL, NULL, 'tavola', '{}', '{}', NULL, NULL, NULL, NULL, 1, 0, 0, '', 2, 'Opera realizzata nel periodo aragonese (attorno al 1445) per la chiesa di San Lorenzo Maggiore a Napoli, tra le scene principali dell''intervento decorativo.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('san-francesco-consegna-la-regola-agli-ordini-francescani', 'San Francesco consegna la regola agli ordini francescani', '{colantonio}', NULL, '1445 circa', 1445, NULL, 'tavola', '{}', '{}', 'Napoli', 'Museo e Gallerie Nazionali di Capodimonte', NULL, NULL, 1, 0, 0, '', 3, 'Tavola che raffigura san Francesco attorniato da due gruppi di monaci e clarisse. L''opera è stilisticamente vicina alla pittura aragonese, meno attenta alla resa realistica degli spazi e più rigida nelle figure, ma risente delle novità fiamminghe nei tratti fisionomici delle clarisse, nel fondo oro bulinato, nelle aureole traforate e nella prospettiva ribaltata del pavimento. Le piastrelle riprendono i tipici azulejos spagnoli con motivi geometrici e floreali alternati agli stemmi di Alfonso d''Aragona.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('crocifissione', 'Crocifissione', '{antonello-da-messina}', NULL, '1475', NULL, 1475, 'tavola', '{}', '{}', 'Londra', 'National Gallery', NULL, NULL, 1, 0, 0, '', 3, 'Opera della fase matura dell''artista, dove Antonello reinterpreta gli insegnamenti del maestro Colantonio sviluppando uno stile personale e indipendente in cui la regola fiamminga della rappresentazione oggettiva del dato naturale trova corrispondenza nella perfezione tecnica.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('ritratto-virile', 'Ritratto virile', '{antonello-da-messina}', NULL, '', NULL, NULL, 'altro', '{}', '{}', NULL, NULL, NULL, NULL, 1, 0, 0, '', 2, 'Esempio dei numerosi ritratti realizzati dall''artista durante la sua carriera, caratterizzati dalla precisione nordica per il dettaglio derivata dal contatto con le opere fiamminghe.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('la-crocifissione', 'La Crocifissione', '{antonello-da-messina}', NULL, '1475', NULL, 1475, 'tavola', '{}', '{}', NULL, NULL, NULL, NULL, 1, 0, 0, '', 3, 'Opera firmata e datata 1475 che presenta una Crocifissione focalizzata sul Cristo isolato nella parte superiore, con Vergine e san Giovanni ai piedi della croce in secondo piano. L''iconografia richiama i modelli nordeuropei, con prospettiva aerea, sezione aurea, resa atmosferica a nebbia e tono meditativo tipici dell''approccio nordico ma con elementi decisamente italiani', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('ritratto-virile-ritratto-dignoto-marinaio', 'Ritratto virile (Ritratto d''ignoto marinaio)', '{antonello-da-messina}', NULL, '1465 circa', 1465, 1465, 'tavola', '{}', '{}', 'Cefalù (Palermo)', 'Museo della Fondazione Mandralisca', NULL, NULL, 1, 0, 0, '', 2, 'Ritratto virile conservato a Cefalù, il più antico tra quelli giunti fino a noi, probabilmente raffigurante Francesco Vitale da Noja, personaggio legato alla corte aragonese e poi vescovo di Cefalù. Opera che testimonia l''approccio antonelliano alla ritrattistica', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('vergine-annunziata', 'Vergine Annunziata', '{antonello-da-messina}', NULL, 'circa 1475-1476', 1475, 1476, 'tavola', '{}', '{}', 'Palermo', 'Galleria Regionale della Sicilia, Palazzo Abatellis', NULL, NULL, 1, 0, 0, '', 3, 'Piccola tavola che riproduce la Vergine Annunziata al momento in cui riceve l''annuncio della sua gravidanza dall''arcangelo Gabriele. Presenta una posa di tre quarti, sfondo scuro, illuminazione da sinistra e umanizzazione del personaggio. Lo sguardo sereno e sicuro della Vergine rivela l''accettazione del proprio destino. Il movimento della mano destra è inteso come gesto benedicente e di umiltà.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('pala-di-san-cassiano-madonna-in-trono-con-il-bambino-tra-i-santi-nicola-da-bari-', 'Pala di San Cassiano (Madonna in trono con il Bambino tra i santi Nicola da Bari, Maria Maddalena, Orsola e Domenico)', '{antonello-da-messina}', NULL, '1475-1476', 1475, 1476, 'polittico', '{}', '{}', 'Vienna', 'Kunsthistorisches Museum', NULL, NULL, 1, 0, 0, '', 3, 'Pala d''altare commissionata dal patrizio Pietro Bon per la chiesa di San Cassiano a Venezia. Ne restano solo tre frammenti relativi alla zona centrale della tavola: la Madonna in trono con il Bambino e i santi. Rappresentò un''innovazione nella pala d''altare veneziana con la sacra conversazione.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('pala-per-la-basilica-dei-santi-giovanni-e-paolo', 'Pala per la basilica dei Santi Giovanni e Paolo', '{giovanni-bellini}', NULL, '', NULL, NULL, 'tavola', '{}', '{}', 'Venezia', 'Basilica dei Santi Giovanni e Paolo', NULL, NULL, 1, 0, 0, '', 2, 'Opera con trono in posizione sopraelevata, elemento di novità rispetto alle composizioni precedenti.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('chiesa-di-santa-maria-dei-miracoli', 'Chiesa di Santa Maria dei Miracoli', '{pietro-solari-lombardo}', NULL, '1481-1489', 1481, 1489, 'architettura', '{}', '{}', 'Venezia', 'Cannaregio', NULL, NULL, 1, 0, 0, '', 3, 'Combina elementi tipicamente lagunari con un gusto plastico e pittorico rinascimentale di matrice lombarda giocato sui colori dei materiali e la raffinatezza dell''intaglio delle pietre. La struttura rimanda a prototipi bizantini, mentre la facciata rivela influssi toscani nella scansione spaziale. Le paraste e l''architrave sono richieggiati da motivi decorativi a croce; gli archi ciechi coronano il secondo ordine ripetendo la curva del timpano e le forme circolari degli oculi. La copertura policroma costituisce una ripresa della maniera antica.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('chiesa-di-san-michele-in-isola', 'Chiesa di San Michele in Isola', '{mauro-codussi}', NULL, '1468-1479 circa', 1468, 1479, 'architettura', '{}', '{}', 'Venezia', 'Isola di San Michele', NULL, NULL, 1, 0, 0, '', 3, 'Prima opera nota di Mauro Codussi, mostra l''influsso di Leon Battista Alberti e in particolare del progetto del Tempio Malatestiano. Esempio dell''originale stile rinascimento veneziano di Codussi.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('palazzo-ducale-porta-della-carta', 'Palazzo Ducale (Porta della Carta)', '{vari-artisti-gruppo}', NULL, 'prima metà Quattrocento', NULL, NULL, 'architettura', '{}', '{}', 'Venezia', 'Piazza San Marco', NULL, NULL, 1, 0, 0, '', 2, 'Il cantiere storicamente più rilevante nella Venezia della prima metà del Quattrocento, che vede impegnati gruppi di architetti, scultori e decoratori chiamati a ridisegnare l''affaccio sulla piazzetta di San Marco.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('ca-vendramin-calergi', 'Ca'' Vendramin Calergi', '{mauro-codussi}', NULL, 'dal 1481', 1481, NULL, 'architettura', '{}', '{}', 'Venezia', 'Cannaregio', NULL, NULL, 1, 0, 0, '', 2, 'Palazzo costruito su commissione privata a partire dal 1481, costituisce un modello per lo sviluppo del palazzo veneziano rinascimentale. Lo sviluppo orizzontale è scandito da pilastri corinzi con funzione lesene al piano terra e finestre scanalate al piano nobile.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('palazzo-rucellai', 'Palazzo Rucellai', '{leon-battista-alberti}', NULL, 'circa 1451', 1446, 1451, 'architettura', '{}', '{}', 'Firenze', NULL, NULL, NULL, 1, 0, 0, '', 2, 'Palazzo fiorentino che funge da modello diretto per il Ca'' Vendramin-Calergi di Codussi, caratterizzato dal ritmo verticale dei pilastri e dalla scansione dei piani.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('medaglia-di-matteo-de-pasti', 'Medaglia di Matteo de'' Pasti', '{matteo-de-pasti}', NULL, '', NULL, NULL, 'altro', '{}', '{}', NULL, NULL, NULL, NULL, 1, 0, 0, '', 1, 'Medaglia che presenta un frontone semicicolare simile a quello della facciata di San Michele in Isola.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('trittico-con-la-madonna-in-trono-con-il-bambino-tra-i-santi-gregorio-gerolamo-am', 'Trittico con la Madonna in trono con il Bambino tra i santi Gregorio, Gerolamo, Ambrogio e Agostino', '{antonio-vivarini-e-giovanni-dalemagna}', NULL, '1446', 1446, 1446, 'polittico', '{}', '{}', 'Venezia', 'Gallerie dell''Accademia', NULL, NULL, 1, 0, 0, '', 3, 'Opera di stile tardo-gotico per l''abbondanza di ori nell''ornato della pedana e dell''architettura merlata che incornicia la scena, ma presenta anche elementi tecnici moderni come la precoce esecuzione su sostante le dimensioni notevoli e la ricerca efficace e unitaria dello spazio pittorico che superare la suddivisione in tre pannelli.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('polittico-con-santambrogio-benedicente-e-i-santi-offerenti-luigi-pietro-paolo-e-', 'Polittico con sant''Ambrogio benedicente e i santi offerenti Luigi, Pietro, Paolo e Sebastiano', '{bartolomeo-vivarini}', NULL, '1477', 1477, 1477, 'polittico', '{}', '{}', 'Venezia', 'Gallerie dell''Accademia', NULL, NULL, 1, 0, 0, '', 2, 'Opera destinata alla Scuola dei Tintori in cui la struttura, i fondi oro e le pose aggraziate dei santi mantengono i segni distintivi della bottega, ma Bartolomeo mostra un carattere individuale con solidità volumetrica e linea grafica.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('trittico-con-la-madonna-in-trono', 'Trittico con la Madonna in trono', '{antonio-vivarini-giovanni-dalemagna}', NULL, '1446', NULL, 1446, 'polittico', '{}', '{}', NULL, NULL, NULL, NULL, 1, 0, 0, '', 3, 'Opera di gusto tardo-gotico caratterizzata dall''abbondanza di ori nell''ornamentazione della pedana e dell''architettura merlata che accoglie la scena. Presenta elementi moderni come la precoce esecuzione su tela nonostante le dimensioni notevoli e la ricerca di unitarietà dello spazio pittorico superando la suddivisione in tre pannelli.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('politico-con-santambrogio-benedicente', 'Politico con sant''Ambrogio benedicente', '{bartolomeo-vivarini-con-collaborazione-di-antonio-vivarini}', NULL, '1477 circa', 1477, NULL, 'tavola', '{}', '{}', NULL, 'Scuola dei Tagliapietre', NULL, NULL, 1, 0, 0, '', 3, 'Opera destinata alla Scuola dei Tagliapietre dove si notano i segni distintivi della bottega ma anche l''energia e il carattere individuale di Bartolomeo, con attenzione ai confronti del linguaggio rinascimentale e influenza della lezione padovana (Mantenga) nelle forme plastiche, solidità volumetrica e linea grafica.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('bibbia-di-gutenberg', 'Bibbia di Gutenberg', '{johannes-gutenberg}', NULL, '1454-1455', 1454, 1455, 'altro', '{}', '{}', 'Magonza', NULL, NULL, NULL, 1, 0, 0, '', 3, 'Principale opera di Gutenberg, pubblicazione della Bibbia risalente al 1455, testo stampato con caratteri mobili, iniziali e marginalia dipinti a mano. Rappresenta la nascita del primo mezzo di comunicazione di massa in Europa.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('grammatica-greca', 'Grammatica greca', '{aldo-manuzio}', NULL, '1495', 1495, NULL, 'altro', '{}', '{}', 'Venezia', 'Stamperia di Aldo Manuzio', NULL, NULL, 1, 0, 0, '', 2, 'Prima opera pubblicata da Aldo Manuzio, una grammatica greca che segna l''inizio della sua attività editoriale volta alla diffusione della cultura classica.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('hypnerotomachia-poliphili', 'Hypnerotomachia Poliphili', '{francesco-colonna-autore-aldo-manuzio-editore}', NULL, '1499', 1499, NULL, 'altro', '{}', '{}', 'Venezia', 'Stamperia di Aldo Manuzio', NULL, NULL, 1, 0, 0, '', 3, 'Romanzo allegorico (''Combattimento amoroso di Polifilo in sogno'') edito da Manuzio nel 1499, considerato un''autentica opera d''arte con veste grafica curatissima nell''elaborazione del carattere tipografico e nell''impaginazione, arricchito da circa 170 splendide xilografie.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('madonna-con-il-bambino-benedicente', 'Madonna con il Bambino benedicente', '{jacopo-bellini}', NULL, '1450 circa', 1450, 1450, 'tavola', '{}', '{}', 'Venezia', 'Gallerie dell''Accademia', NULL, NULL, 1, 0, 0, '', 3, 'Dipinto che testimonia lo sforzo di adeguamento ai nuovi modelli di pittura che iniziano a circolare in laguna. Spezza la rigida impostazione frontale di derivazione bizantina: la collocazione del bambino di tre quarti è funzionale al più ampio tentativo di creare una profondità spaziale e umanizzare i personaggi. Rimanenze tardogotiche si intuiscono nel probabile influsso della pittura fiamminga, sia nello sfondo scuro sia nell''espediente della balaustra marmorea.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('deposizione-dalla-croce-e-compianto-sul-corpo-di-cristo', 'Deposizione dalla croce e Compianto sul corpo di Cristo', '{jacopo-bellini}', NULL, '1460-1470', 1460, 1470, 'altro', '{}', '{}', 'Parigi', 'Musée du Louvre', NULL, NULL, 1, 0, 0, '', 2, 'Disegno facente parte di album di disegni conservati al British Museum di Londra e al Musée du Louvre di Parigi. Repertori di immagini destinati a essere utilizzati come modelli nella bottega di famiglia. L''impostazione spaziale attesta una buona conoscenza della prospettiva lineare, adottata per creare unità spaziale, ma applicata a soggetti ancora di sapore tardogotico.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('la-processione-in-piazza-san-marco', 'La Processione in piazza San Marco', '{gentile-bellini}', NULL, '1496', 1496, NULL, 'tela', '{}', '{}', 'Venezia', 'Gallerie dell''Accademia', NULL, NULL, 1, 0, 0, '', 3, 'Uno dei tre teleri dipinti da Gentile per l''Oraorio della Scuola Grande di San Giovanni Evangelista. Raffigura la festa religiosa del 1444 durante la quale avvenne la guarigione miracolosa di un devoto bresciano. L''opera è dipinta con una linea di contorno agile ed essenziale e un colore netto e ben definito.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('ciclo-di-dieci-teleri-dedicato-ai-miracoli-della-vera-croce', 'Ciclo di dieci teleri dedicato ai Miracoli della vera Croce', '{gentile-bellini}', NULL, 'dal 1493', 1493, NULL, 'tela', '{}', '{}', 'Venezia', 'Scuola Grande di San Giovanni Evangelista', NULL, NULL, 1, 0, 0, '', 2, 'Ciclo di dieci teleri (tre dei quali dipinti da Gentile) realizzati per l''Oraorio della Scuola Grande di San Giovanni Evangelista, che coinvolse anche altri artisti nella realizzazione.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('miracolo-della-reliquia-della-croce-a-rialto', 'Miracolo della reliquia della Croce a Rialto', '{vittore-carpaccio}', NULL, '1494-1496', 1494, 1496, 'tela', '{}', '{}', 'Venezia', 'Gallerie dell''Accademia', NULL, NULL, 1, 0, 0, '', 3, 'Telerio che raffigura un miracoloso evento legato alla reliquia della Vera Croce avvenuto a Rialto. L''opera presenta una veduta urbana di grande vivacità, con l''Inghilterra medievale descritta mediante torri, rocche e cinte murarie immaginarie a sinistra, e la Bretagna rinascimentale caratterizzata da edifici non dissimili dalle architetture veneziane a destra. Il protagonista è la città con le sue architetture.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('incontro-di-orsola-ed-ereo-e-partenza-dei-pellegrini', 'Incontro di Orsola ed Ereo e partenza dei pellegrini', '{vittore-carpaccio}', NULL, '1490-1497', 1490, 1497, 'tela', '{}', '{}', 'Venezia', 'Gallerie dell''Accademia', NULL, NULL, 1, 0, 0, '', 2, 'Telerio facente parte del ciclo delle Storie di sant''Orsola dipinto per la Scuola di Sant''Orsola. Raffigura quattro diversi episodi: da sinistra a destra, il principe Ereo si congeda dal padre; Orsola ed Ereo si incontrano; i due giovani salutano i sovrani di Bretagna; sul fondo si srotola il corteo del pellegrinaggio per Roma. Il pennone in primo piano divide la tela in due zone di dimensioni differenti che ospitano due paesaggi: quello a sinistra identificabile con l''Inghilterra medievale, quello sulla destra con la Bretagna rinascimentale. I gesti solenni dei personaggi ricordano le cerimonie civili della repubblica aristocratica veneziana.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('ciclo-delle-storie-di-santorsola', 'Ciclo delle Storie di sant''Orsola', '{vittore-carpaccio}', NULL, '1490-1497', 1490, 1497, 'altro', '{}', '{}', 'Venezia', 'Scuola di Sant''Orsola', NULL, NULL, 1, 0, 0, '', 3, 'Ciclo di nove teleri dedicati alle Storie di sant''Orsola, principessa vergine e martire vissuta nel IV secolo. L''artista inserisce più episodi in modo calibrato e leggibile in ciascun telerio, arricchendo le scene con numerosi dettagli che impressioniscono il racconto. La narrazione ha un carattere fiabesco asseente nel ciclo dei Mincoli della vera Croce.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('teleri-di-san-girolamo', 'Teleri di San Girolamo', '{vittore-carpaccio}', NULL, '', NULL, NULL, 'tela', '{}', '{}', 'Venezia', 'Scuola Grande di San Giovanni Evangelista', NULL, NULL, 1, 0, 0, '', 2, 'Teleri dipinti da Carpaccio nella Scuola Grande di San Giovanni Evangelista in un contesto che reca l''impronta di Gentile Bellini. Opera di committenza profana, rapida e fastosa, poco adatta allo scopo devozionale.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('presentazione-al-tempio', 'Presentazione al Tempio', '{giovanni-bellini}', NULL, '1460 circa', 1460, 1460, 'tavola', '{}', '{}', 'Venezia', 'Fondazione Querini Stampalia', NULL, NULL, 1, 0, 0, '', 2, 'Opera giovanile che riproduce quasi esattamente l''analogo dipinto del cognato Mantegna (1455), ma utilizzando tonalità luminose più morbide. La mancanza delle aureole e la balaustra rendono i personaggi più umani e colloquiali. Ritrae probabilmente membri della famiglia Bellini come figure secondarie.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('orazione-di-gesu-nellorto-degli-ulivi', 'Orazione di Gesù nell''orto degli ulivi', '{giovanni-bellini}', NULL, '1465-1470', 1465, 1470, 'tavola', '{}', '{}', NULL, NULL, NULL, NULL, 1, 0, 0, '', 2, 'Opera in cui emerge chiaramente l''influenza di Mantegna sullo stile di Bellini, riprendendone la composizione da una tavola di analogo soggetto.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('pala-di-pesaro', 'Pala di Pesaro', '{antonello-da-messina}', NULL, '', NULL, NULL, 'tavola', '{}', '{}', 'Venezia', NULL, NULL, NULL, 1, 0, 0, '', 1, 'Opera che dimostra l''arrivo a Venezia di Antonello da Messina e l''introduzione della tecnica del colore a olio.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('trittico-dei-frari', 'Trittico dei Frari', '{giovanni-bellini}', NULL, '1488', 1488, 1488, 'polittico', '{}', '{}', 'Venezia', 'Santa Maria Gloriosa dei Frari', NULL, NULL, 1, 0, 0, '', 2, 'Punto di contatto tra due artisti che rielaborano la concezione pittorica di Bellini in modo nuovo e spaziale.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('pala-di-san-zaccaria', 'Pala di San Zaccaria', '{giovanni-bellini}', NULL, '1505', 1505, 1505, 'tavola', '{}', '{}', 'Venezia', 'Chiesa di San Zaccaria', NULL, NULL, 1, 0, 0, '', 3, 'Opera matura di Bellini che rappresenta l''evoluzione verso forme piene e geometriche con particolare attenzione alla luce e al colore.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('lorazione-nellorto-o-cristo-nellorto', 'L''Orazione nell''orto (o Cristo nell''orto)', '{giovanni-bellini}', NULL, 'circa 1465-1470', 1465, 1470, 'tavola', '{}', '{}', 'Londra', 'National Gallery', NULL, NULL, 1, 0, 0, '', 3, 'Raffigura Cristo in preghiera sul Monte degli Ulivi mentre gli apostoli dormono in primo piano. Il paesaggio si apre su un''ampia veduta con campanili, architetture venete e un cielo drammatico con nuvole rosate all''alba. L''opera mostra il passaggio dall''influenza mantegnesca verso uno stile più luminoso e naturalistico.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('cristo-nellorto-versione-mantegnesca', 'Cristo nell''orto (versione mantegnesca)', '{andrea-mantegna}', NULL, 'circa 1458-1460', 1458, 1460, 'tavola', '{}', '{}', 'Londra', 'National Gallery', NULL, NULL, 1, 0, 0, '', 2, 'Versione precedente dello stesso soggetto, caratterizzata da linee di contorno incisive, forme plastiche e minuziose, paesaggio aspro e roccioso con monumenti simbolici sullo sfondo.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('pieta', 'Pietà', '{giovanni-bellini}', NULL, '1475 circa', 1470, 1480, 'tavola', '{}', '{}', 'Milano', 'Pinacoteca di Brera', NULL, NULL, 1, 0, 0, '', 3, 'Cristo morto sorretto da Maria e da san Giovanni Evangelista, con punto di vista ravvicinato e raffigurazione a mezzobusto. Presenta accenti drammatici, coinvolgimento emotivo dello spettatore, contrasto tra cielo metallico e colori caldi/freddi. La scena è separata dal mondo reale da una paratetto in marna.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('pala-di-pesaro-pala-della-coronazione-della-vergine-tra-san-francesco-paolo-piet', 'Pala di Pesaro (Pala della Coronazione della Vergine tra San Francesco, Paolo, Pietro, Girolamo)', '{giovanni-bellini}', NULL, '1470-1475', 1470, 1475, 'polittico', '{}', '{}', 'Pesaro', 'Musei Civici', NULL, NULL, 1, 0, 0, '', 3, 'Pala d''altare composta da un pannello centrale con la Coronazione della Vergine tra i santi Francesco, Paolo, Pietro e Girolama, una cimasa con il Cristo morto sorretto dalla Vergine e santi, predella con storie della vita di Cristo, e cornice architettonica intagliata. Opera che segna l''evoluzione verso uno spazio unitario e luminoso.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('cimasa-del-pala-di-pesaro-cristo-morto-sorretto-dalla-vergine', 'Cimasa del Pala di Pesaro (Cristo morto sorretto dalla Vergine)', '{giovanni-bellini}', NULL, '1470-1475', 1470, 1475, 'tavola', '{}', '{}', 'Pesaro', 'Musei Civici', NULL, NULL, 1, 0, 0, '', 2, 'Parte superiore della Pala di Pesaro raffigurante il Cristo morto sorretto dalla Vergine, opera di forte intensità emotiva e solidità volumetrica', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('predella-della-pala-di-pesaro', 'Predella della Pala di Pesaro', '{giovanni-bellini}', NULL, '1470-1475', 1470, 1475, 'tavola', '{}', '{}', 'Pesaro', 'Musei Civici', NULL, NULL, 1, 0, 0, '', 1, 'Parte inferiore della Pala di Pesaro con scene narrative della vita di Cristo', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('cornice-della-pala-di-pesaro', 'Cornice della Pala di Pesaro', '{giovanni-bellini}', NULL, '1470-1475', 1470, 1475, 'altro', '{}', '{}', 'Pesaro', 'Musei Civici', NULL, NULL, 1, 0, 0, '', 1, 'Cornice architettonica rinascimentale ricostruita nella prima metà del Novecento, con colonne e fregio decorativo', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('allegoria-sacra', 'Allegoria sacra', '{giovanni-bellini}', NULL, '1490-1500 circa', 1490, 1500, 'tavola', '{}', '{}', 'Firenze', 'Gallerie degli Uffizi', NULL, NULL, 1, 0, 0, '', 3, 'Opera misteriosa e enigmatica ambientata su una terrazza pavimentata a scacchi che si affaccia su una città fortificata e una campagna veneta. Presenta figure sacre (Madonna col Bambino, santi) e simboliche (nudi, putti) in una composizione complessa e ambigua, con elementi allegorici di difficile interpretazione.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('madonna-del-prato', 'Madonna del Prato', '{giovanni-bellini}', NULL, '1500-1505 circa', 1500, 1505, 'tela', '{}', '{}', 'Londra', 'National Gallery', NULL, NULL, 1, 0, 0, '', 3, 'Tela devozionale di formato ridotto raffigurante la Madonna in piedi che adora il Bambino disteso sul terreno, secondo lo schema medievale della Madonna dell''Umiltà. L''iconografia nordica della Madonna adorante è arricchita da una struttura compositiva piramidale e da uno sfondo paesaggistico veneto nettamente distaccato dalla figura.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('madonna-col-bambino-in-trono-con-angeli-musicanti-e-santi-pietro-e-caterina', 'Madonna col Bambino in trono con angeli musicanti e santi Pietro e Caterina', '{giovanni-bellini}', NULL, '1505', 1505, NULL, 'tavola', '{}', '{}', 'Venezia', 'Chiesa di San Zaccaria', NULL, NULL, 1, 0, 0, '', 3, 'Pala d''altare con composizione piramidale ispirata al Trittico di Piero della Francesca. Presenta nicchia con catino absidale in mosaico dorato, trono architettonico, angeli musicanti al centro, santi Pietro e Caterina ai lati. Caratterizzata da prospettiva costruita in pianta e alzato, pilastri dipinti corrispondenti a quelli reali, uso del colore sfumato e barbe raffinate.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('ritratto-del-doge-leonardo-loredan', 'Ritratto del doge Leonardo Loredan', '{giovanni-bellini}', NULL, '1501-1502', 1501, 1502, 'tavola', '{}', '{}', 'Londra', 'National Gallery', NULL, NULL, 1, 0, 0, '', 2, 'Ritratto ufficiale del doge Leonardo Loredan all''età di circa 65 anni. Opera innovativa che rielabora il ritratto tradizionale del profilo in posa frontale a mezza figura, con attenzione al realismo somatico (segni del tempo), simbolismo politico (guarnitura cerimoniale) e solidità scultorea del busto. Esempio di ''aura di ieraticità'' espressa con mezzi modernissimi.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('palazzo-schifanoia', 'Palazzo Schifanoia', '{varii-scuola-ferrarese}', NULL, 'XV secolo', NULL, NULL, 'architettura', '{}', '{}', 'Ferrara', 'Ferrara', NULL, NULL, 1, 0, 0, '', 3, 'Palazzo della delizia voluto dalla famiglia d''Este, esempio emblematico dell''architettura eccentrica ferrarese.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('addizione-borsiana', 'Addizione Borsiana', '{borso-deste-committente}', NULL, '1450-1471', 1450, 1471, 'urbanistica', '{}', '{}', 'Ferrara', 'Ferrara', NULL, NULL, 1, 0, 0, '', 3, 'Ampliamento della città verso sud voluto da Borso d''Este, con costruzione di palazzi, ville da campagna e ''delizie''.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('addizione-erculea', 'Addizione Erculea', '{ercole-i-deste-committente}', NULL, 'dal 1492', 1492, NULL, 'urbanistica', '{}', '{}', 'Ferrara', 'Ferrara', NULL, NULL, 1, 0, 0, '', 3, 'Impostante campagna di ampliamento e riorganizzazione urbanistica di Ferrara voluta da Ercole I d''Este dopo la guerra con Venezia.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('pianta-della-citta-di-ferrara', 'Pianta della città di Ferrara', '{anonimo}', NULL, 'XV-XVI secolo', NULL, NULL, 'altro', '{}', '{}', 'Ferrara', NULL, NULL, NULL, 1, 0, 0, '', 2, 'Mappa che mostra le Addizioni di Borso I (1451) e di Ercole I (1492), con indicazione dei principali monumenti: Castello estense, Palazzo Schifanoia, Palazzo dei Diamanti, vie degli Angeli e dei Priori, Piazza Nuova.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('palazzo-dei-diamanti', 'Palazzo dei Diamanti', '{biagio-rossetti}', NULL, 'dal 1493', 1493, NULL, 'architettura', '{}', '{}', 'Ferrara', 'Corso Ercole I d''Este', NULL, NULL, 1, 0, 0, '', 2, 'Edificio residenziale dell''Addizione Erculea, costruito per Sigismondo d''Este. Facciata caratterizzata da bugne diamantate (blocchi a forma di diamante) in marmo rosa, balcone a candelabre classicheggianti di Gabriele Frisoni, soluzioni planimetriche articolate.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('candelabra-e-angoloni-del-palazzo-dei-diamanti', 'Candelabra e angoloni del Palazzo dei Diamanti', '{gabriele-frisoni}', NULL, '1692', 1692, NULL, 'scultura', '{}', '{}', 'Ferrara', 'Palazzo dei Diamanti', NULL, NULL, 1, 0, 0, '', 1, 'Particolari ornamentali in stile classico (candelabra e angoloni) realizzati per il Palazzo dei Diamanti nel XVII secolo.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('urania', 'Urania', '{angelo-maccagnino}', NULL, '1455-1460', 1455, 1460, 'tavola', '{}', '{}', 'Ferrara', 'Palazzo dei Diamanti', NULL, NULL, 1, 0, 0, '', 2, 'Figura delle Muse realizzata da Angelo Maccagnino per lo studiolo di Belriguardo. Raffigura probabilmente Urania (o Apollo), musa/guida delle Muse, seduta in trono con attributi musicali o astronomici.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('decorazione-dello-studiolo-di-belriguardo', 'Decorazione dello Studiolo di Belriguardo', '{angelo-maccagnino-cosme-tura}', NULL, '1447-1463', 1447, 1463, 'altro', '{}', '{}', 'Ferrara', 'Villa di Belriguardo (distrutta)', NULL, NULL, 1, 0, 0, '', 3, 'Complesso decorativo commissionato da Leonello d''Este per il suo studiolo nella villa di Belriguardo. Comprendeva figure delle Muse in tavola (faccia superiore) e tarsie lignee (faccia inferiore), con un progetto iconografico umanistico definito da Guarino Veronese.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('calliope-o-erato', 'Calliope (o Erato)', '{cosme-tura}', NULL, '1455-1460 circa', 1455, 1460, 'tavola', '{}', '{}', 'Londra', 'National Gallery', NULL, NULL, 1, 0, 0, '', 2, 'Raffigura la musa Calliope (della poesia epica) o Erato (della poesia amorosa), dipinta per lo studio dei Belfiore. L''opera mostra figure trasformate in forme scultoree, modellate nel bronzo, sbalzate a cellole e incastonate con pietre preziose, con un realismo crudo che richiama la fontaniera ma controllato da classici modelli toscani.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('opera-non-specificata-seconda-stesura', 'Opera non specificata (seconda stesura)', '{cosme-tura}', NULL, '', NULL, NULL, 'tavola', '{}', '{}', NULL, NULL, NULL, NULL, 1, 0, 0, '', 2, 'Opera probabilmente modificata in una seconda stesura intervenendo con colori a olio sull''originale tempera.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('san-giorgio-e-la-principessa-ante-chiusure', 'San Giorgio e la principessa (ante chiusure)', '{cosme-tura}', NULL, '1469 circa', NULL, 1469, 'tela', '{}', '{}', 'Ferrara', 'Museo della Cattedrale', NULL, NULL, 1, 0, 0, '', 3, 'Ante d''organo per il duomo di Ferrara raffiguranti San Giorgio a cavallo che uccide il drago accanto alla principessa. L''opera presenta uno stile gotico-cortese con componenti nordiche: figure sottili, pose contorte, materiali metallici (oro su sfondo), prospettiva invertita e anatomia distorta. Il cavallo è scolpito in modo da saltare verso l''osservatore.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('lannunciazione', 'L''Annunciazione', '{cosme-tura}', NULL, '', NULL, NULL, 'tela', '{}', '{}', NULL, NULL, NULL, NULL, 1, 0, 0, '', 2, 'Parte delle ante dell''organo del duomo di Ferrara, raffigurante l''Annunciazione con la Vergine in un ambiente architettonico. Opera caratterizzata dalla sapienza antiquaria e prospezione verso lo spazio reale tipiche dell''influenza mantegnesca.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('politico-roverella', 'Politico Roverella', '{cosme-tura}', NULL, '1475-1479', 1475, 1479, 'affresco', '{}', '{}', 'Ferrara', 'monastero di San Giorgio fuori le mura', NULL, NULL, 1, 0, 0, '', 3, 'Tavola d''altare destinata alla chiesa del monastero di San Giorgio fuori le mura, completata pala d''altare, danneggiata da un colpo di cannone e smembrata nel Settecento; oggi le parti sono disseminate in musei europei e americani', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
