INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('politico-griffoni', 'Politico Griffoni', '{francesco-del-cossa}', NULL, '1473', 1473, NULL, 'polittico', '{}', '{}', 'Bologna', 'basilica di San Petronio', NULL, NULL, 1, 0, 0, '', 3, 'Polittico commissionato da Floriano Griffoni, membro di una delle caste bolognesi più colte e potenti, per la cappella di famiglia nella basilica di San Petronio. Secondo ricostruzioni, la zona centrale del politico Griffoni era occupata dalla figura di San Ludovico di Tolosa, affiancato dalle tavole con San Pietro e San Giacomo Battista. Nella parte superiore si trovava tondo con la Crocifissione, mentre i plastroni interni ospitavano scomparti con santi di dimensioni ridotte. Nella parte alta del politico l''artista prova a superare il limite imposto dall''arco a tutto sesto o rotondo raffigurando parapetti in pietra che conferiscono un senso di profondità prospettica', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('polittico-griffoni-ricostruzione', 'Polittico Griffoni (ricostruzione)', '{francesco-del-cossa-ercole-de-roberti}', NULL, '1470-1473', 1470, 1473, 'polittico', '{}', '{}', 'Bologna', 'Chiesa di San Petronio (originale); varie sedi museali (attuale)', NULL, NULL, 1, 0, 0, '', 3, 'Polittico composto da 109 pannelli (ipotesi ricostruttiva) con figure di santi in nicchie architettoniche, Crocifissione centrale e predella con storie di santi. Opera caratterizzata da unificante della politica griffoniana, figure di vigore plastico e illuminazione laterale.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
