INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('pala-portonese-madonna-col-bambino-e-santi', 'Pala Portonese (Madonna col Bambino e santi)', '{ercole-de-roberti}', NULL, 'circa 1475-1480', 1470, 1480, 'tavola', '{}', '{}', 'Venezia', 'Gallerie dell''Accademia', NULL, NULL, 1, 0, 0, '', 3, 'Capolavoro giovanile di Roberti, eseguito dopo un viaggio a Venezia e conservato nella chiesa di Santa Maria in Porto a Ravenna. Rielabora il modello della Pala di San Cassiano di Antonio da Messina secondo uno schema piramidale e simmetrico su un originale pedana ottagonale. Presenta una struttura porticata coperta da una volta a crociera, con figure di classica compostezza derivate dall''opera di Giovanni Bellini.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('affreschi-della-cappella-garganelli', 'Affreschi della cappella Garganelli', '{ercole-de-roberti}', NULL, '1487-1490', 1487, 1490, 'affresco', '{}', '{}', 'Bologna', 'Cattedrale di San Pietro', NULL, NULL, 1, 0, 0, '', 2, 'Decorazione della cappella Garganelli nella cattedrale bolognese, commissionata dopo la morte di Francesco del Cossa (1478). Il ciclo di affreschi rappresenta la conclusione dei lavori decorativi della cappella.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('polittico-porta-romana', 'Polittico Porta Romana', '{pietro-di-giovanni-dambrogio}', NULL, '1479-1481', 1479, 1481, 'polittico', '{}', '{}', 'Siena', NULL, NULL, NULL, 1, 0, 0, '', 1, 'Opera citata come riferimento per la struttura porticata adottata da Ercole de'' Roberti nella Pala Portonese.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('pala-di-san-cassiano', 'Pala di San Cassiano', '{antonio-da-messina}', NULL, '', NULL, NULL, 'tavola', '{}', '{}', 'Venezia', NULL, NULL, NULL, 1, 0, 0, '', 2, 'Opera monumentale che servì da modello per la Pala Portonese di Ercole de'' Roberti, specialmente per la sacra conversazione e lo schema piramidale.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('maddalena', 'Maddalena', '{ercole-de-roberti}', NULL, '1478-1486', 1478, 1486, 'affresco', '{}', '{}', 'Bologna', 'Pinacoteca Nazionale', NULL, NULL, 1, 0, 0, '', 3, 'Frammento raffigurante il volto ulteriore e piangente della Maddalena, che rimanda ancora a una volta specifica della scultura ferraresca; orientata verso un''espressività potente e deformante, anticlassica.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('maddalena-penitente', 'Maddalena penitente', '{donatello}', NULL, '1453-1455', 1453, 1455, 'scultura', '{}', '{}', 'Firenze', 'Museo dell''Opera del Duomo', NULL, NULL, 1, 0, 0, '', 2, 'Scultura tarda di Donatello che esercitò forte influenza sull''espressività deformante e anticlassica dei pittori ferraresi come Ercole de'' Roberti e sugli scultori bolognesi come Niccolò dell''Arca.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('ciclo-dei-mesi-salone-dei-mesi', 'Ciclo dei Mesi (Salone dei Mesi)', '{francesco-del-cossa-ercole-de-roberti}', NULL, '1467-1470', 1467, 1470, 'affresco', '{}', '{}', 'Ferrara', 'Palazzo Schifanoia, Salone d''onore', NULL, NULL, 1, 0, 0, '', 3, 'Ciclo decorativo monumentale dedicato ai mesi dell''anno, strutturato in tre fasce: la fascia inferiore con scene di vita urbana o cortigiana, quella mediana con trionfi zodiacali, e quella superiore con il trionfo della divinità pagana protettiva. Il programma iconografico è ispirato alla cultura astrologica medievale e alle teorie di Pellegrino Prisciani.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('palazzo-schifanoia-ristrutturazione', 'Palazzo Schifanoia (ristrutturazione)', '{pietro-benvogliente}', NULL, 'dal 1465', 1465, NULL, 'architettura', '{}', '{}', 'Ferrara', 'Palazzo Schifanoia', NULL, NULL, 1, 0, 0, '', 2, 'Intervento architettonico di ristrutturazione e ampliamento del palazzo per trasformarlo in residenza di rappresentanza deglì Ordini, con creazione di un nuovo appartamento ducale e salone d''onore rettangolare.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('ciclo-degli-affreschi-del-salone-dei-mesi-palazzo-schifanoia', 'Ciclo degli affreschi del Salone dei Mesi (Palazzo Schifanoia)', '{officina-ferrarese-cosme-tura-ercole-de-roberti-francesco-del-cossa}', NULL, '1469-1470 circa', 1469, 1470, 'affresco', '{}', '{}', 'Ferrara', 'Palazzo Schifanoia, Salone dei Mesi', NULL, NULL, 1, 0, 0, '', 3, 'Complesso ciclo decorativo che rappresenta i singoli mesi dell''anno su tre pareti (Est, Sud, Nord), con scene allegoriche relative ai segni zodiacali e alle attività umane. Ogni mese è attribuito a un diverso pittore dell''officina ferrarese.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('mese-di-febbraio-trionfo-di-minerva', 'Mese di Febbraio (Trionfo di Minerva)', '{cosme-tura}', NULL, '1469-1470', 1469, 1470, 'affresco', '{}', '{}', 'Ferrara', 'Palazzo Schifanoia, Salone dei Mesi, Parete Est', NULL, NULL, 1, 0, 0, '', 2, 'Affresco rappresentante il mese di febbraio con il trionfo della dea Minerva e scene legate al segno zodiacale dei Pesci', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('mese-di-marzo', 'Mese di Marzo', '{francesco-del-cossa}', NULL, '1469-1470', 1469, 1470, 'affresco', '{}', '{}', 'Ferrara', 'Palazzo Schifanoia, Salone dei Mesi, Parete Est', NULL, NULL, 1, 0, 0, '', 2, 'Affresco rappresentante il mese di marzo con scene allegoriche', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('mese-di-settembre', 'Mese di Settembre', '{ercole-de-roberti}', NULL, '1469-1470', 1469, 1470, 'affresco', '{}', '{}', 'Ferrara', 'Palazzo Schifanoia, Salone dei Mesi, Parete Nord', NULL, NULL, 1, 0, 0, '', 2, 'Affresco rappresentante il mese di settembre con scene allegoriche', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('trionfo-di-marzo-apile-e-maggio', 'Trionfo di Marzo (Apile e Maggio)', '{officina-ferrarese-cosme-tura}', NULL, 'circa 1460-1470', NULL, NULL, 'affresco', '{}', '{}', 'Ferrara', 'Palazzo Schifanoia (Sala dei Mesi)', NULL, NULL, 1, 0, 0, '', 3, 'Scena superiore del ciclo dei Mesi: trionfo di Borsò d''Este su carro trionfale trainato da cavalli bianchi, con figure allegoriche e corteo celebrativo. Rappresenta il buon governo del duca con riferimenti astrologici (Zodiaco) e divinità pagane.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('trionfo-di-marzo---scena-inferiore', 'Trionfo di Marzo - Scena inferiore', '{maestro-degli-occhi-spalancati}', NULL, '', NULL, NULL, 'affresco', '{}', '{}', 'Ferrara', 'Palazzo Schifanoia (Sala dei Mesi)', NULL, NULL, 1, 0, 0, '', 2, 'Registro inferiore del trionfo di marzo: creazione di uno spazio reale con effetto illusionistico tra spaziale e prospettico, raffigurante pacchetti aperti con figure in primo piano', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('ciclo-di-affreschi-dei-mesi-sala-dei-mesi', 'Ciclo di affreschi dei Mesi (Sala dei Mesi)', '{officina-ferrarese-cosme-tura-francesco-del-cossa-ercole-de-roberti}', NULL, '1469-1470', 1469, 1470, 'affresco', '{}', '{}', 'Ferrara', 'Palazzo Schifanoia', NULL, NULL, 1, 0, 0, '', 3, 'Ciclo decorativo completo della Sala dei Mesi, realizzato per celebrare la casata d''Este e il governo di Borso d''Este. Comprende registri superiori (trionfi e temi astrologici), medi (scene della vita cortese) e inferiori (generici). Iconografia complessa che unisce temi neoplatonici, astrologici e politici.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('ritratto-di-uomo-probabile-autoritratto-o-ritratto-di-corte', 'Ritratto di uomo (probabile autoritratto o ritratto di corte)', '{pietro-perugino}', NULL, '', NULL, NULL, 'tavola', '{}', '{}', NULL, NULL, NULL, NULL, 1, 0, 0, '', 2, 'Ritratto maschile con sfondo paesaggistico tipico del linguaggio peruginesco', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('mesi-di-aprile-salone-dei-mesi-di-palazzo-schifanoia', 'Mesi di Aprile (Salone dei Mesi di Palazzo Schifanoia)', '{francesco-del-cossa}', NULL, 'circa 1470', 1469, 1470, 'affresco', '{}', '{}', 'Ferrara', 'Palazzo Schifanoia, Salone dei Mesi', NULL, NULL, 1, 0, 0, '', 3, 'Ciclo di affreschi che rappresenta il mese di aprile attraverso tre fasce orizzontali: la fascia superiore con il trionfo di Venere (divinità protettrice del mese), la fascia centrale con lo zodiaco (segno del Toro con Ariete e Gemelli) e figure mitologiche, e la fascia inferiore con scene della vita cortese e Virtù. L''opera è ispirata ai Trionfi di Petrarca e alle teorie astrologiche dell''epoca.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('trionfi-di-francesco-petrarca', 'Trionfi di Francesco Petrarca', '{francesco-petrarca}', NULL, 'completati entro il 1351', NULL, 1351, 'altro', '{}', '{}', NULL, NULL, NULL, NULL, 1, 0, 0, '', 3, 'Opera letteraria in versi composta da sei parti: Amore, Castità, Morte, Fama, Tempo e Eternità/Dio. Ogni trionfo rappresenta l''ascesa di un concetto allegorico sul precedente. I Trionfi esercitarono un''enorme influenza sull''arte figurativa rinascimentale, fornendo un repertorio iconografico fondamentale.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('palo-di-santagata', 'Palo di Sant''Agata', '{anonimo}', NULL, '', NULL, NULL, 'tavola', '{}', '{}', 'Ferrara', NULL, NULL, NULL, 1, 0, 0, '', 1, 'Nella fascia bassa del mese di Aprile è raffigurato il Palo di sant''Agata a Ferrara, documento di un evento storico-culturale locale.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('ospedale-maggiore', 'Ospedale Maggiore', '{filarete}', NULL, '1456-1481', 1456, 1481, 'architettura', '{}', '{}', 'Milano', 'Ospedale Maggiore', NULL, NULL, 1, 0, 0, '', 3, 'Grande complesso ospedaliero a pianta quadrata con cortile centrale, porticato su quattro lati e due ordini di logge sovrapposte. La facciata principale presenta un marcato cornicione in laterizi che raccorda le fronti interne ed esterne, con finestre bifore ad archi ogivali all''ultimo piano. Il progetto prevedeva un sistema di approvvigionamento idrico avanzato.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('castello-sforzesco', 'Castello Sforzesco', '{filarete-guiniforte-solari}', NULL, '1450-1466', 1450, 1466, 'architettura', '{}', '{}', 'Milano', 'Castello Sforzesco', NULL, NULL, 1, 0, 0, '', 2, 'Torre d''ingresso costruita su rovina della rocca viscontea, isolata dal contesto urbano con scala monumentale che contrappone tessuto urbano medievale e nuova architettura rinascimentale.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('facciata-della-cattedrale-di-bergamo', 'Facciata della Cattedrale di Bergamo', '{filarete-guiniforte-solari}', NULL, '1456-1459 (progetto Filarete); completamento fino al 1481', 1456, 1481, 'architettura', '{}', '{}', 'Bergamo', 'Cattedrale (Duomo)', NULL, NULL, 1, 0, 0, '', 2, 'Facciata incompiuta progettata da Filarete e realizzata sotto la direzione di Guiniforte Solari, esempio di contaminazione tra stile toscano e tradizione lombarda.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('trattato-di-architettura', 'Trattato di architettura', '{filarete}', NULL, '1460-1464', 1460, 1464, 'altro', '{}', '{}', NULL, NULL, NULL, NULL, 1, 0, 0, '', 3, 'Opera teorica in cui Filarete espone i principi dell''architettura rinascimentale, descrive la città ideale di Sforzinda e definisce le regole della facciata e dell''ordinamento architettonico classico adattato al contesto lombardo.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('sforzinda', 'Sforzinda', '{filarete}', NULL, '1460-1465', 1460, 1465, 'urbanistica', '{}', '{}', NULL, 'Firenze, Biblioteca Nazionale', NULL, NULL, 1, 0, 0, '', 3, 'Città ideale a pianta ottagonale inscritta in una cerchio (stella a otto punte), con centro geometrico definito dalla stella. Prevede un fossato, torri agli angoli, strade convergenti verso una piazza centrale con palazzo del principe e architettura pubblica. La città è divisa in settori funzionali: mercati, residenze, edifici pubblici, con strade secondarie radiali.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('certosa-di-pavia---facciata', 'Certosa di Pavia - Facciata', '{guiniforte-solari-giovanni-antonio-amadeo}', NULL, '1473-1499', 1473, 1499, 'architettura', '{}', '{}', 'Pavia', 'Certosa di Pavia', NULL, NULL, 1, 0, 0, '', 3, 'Facciata monumentale a due ordini con loggiato superiore, arricchita da formine incastonate, colonne binate e ricca decorazione scultorea che fonde elementi gotici e rinascimentali', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('certosa-di-pavia---interno-chiesa', 'Certosa di Pavia - Interno chiesa', '{guiniforte-solari}', NULL, 'dal 1396', 1396, NULL, 'architettura', '{}', '{}', 'Pavia', 'Certosa di Pavia', NULL, NULL, 1, 0, 0, '', 2, 'Interno a tre navate con pilastri compositi, volte a crociera e presbiterio rialzato su cripta, con monumentale ingresso classico e colonna binata in marmo rosso di Verona', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('affreschi-della-facciata-della-certosa', 'Affreschi della facciata della Certosa', '{andrea-mantegna}', NULL, '1473', 1473, 1473, 'affresco', '{}', '{}', 'Pavia', 'Facciata Certosa di Pavia', NULL, NULL, 1, 0, 0, '', 2, 'Primi affreschi eseguiti sulla facciata, andati perduti, che costituirono un modello per la decorazione pittorica successiva', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('decorazione-pittorica-del-coro-e-transetto', 'Decorazione pittorica del coro e transetto', '{bergognone}', NULL, '1488-1495', 1488, 1495, 'affresco', '{}', '{}', 'Pavia', 'Certosa di Pavia - Coro e transetto', NULL, NULL, 1, 0, 0, '', 3, 'Ciclo di affreschi raffiguranti la vita e i miracoli di San Bruno e altri soggetti religiosi, caratterizzati da composizioni equilibrate e figure umane di grande dignità', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('formine-decorative-della-facciata', 'Formine decorative della facciata', '{gian-giacomo-dolcebuono-giovanni-benedetto-briosco}', NULL, 'fine XV secolo', 1490, 1500, 'scultura', '{}', '{}', 'Pavia', 'Facciata Certosa di Pavia', NULL, NULL, 1, 0, 0, '', 2, 'Piccole formine incastonate negli spazi della facciata, rappresentanti santi e personaggi biblici, eseguite con tecnica miniaturistica di alta qualità', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('portale-dingresso', 'Portale d''ingresso', '{amadeo-e-collaboratori}', NULL, 'fine XV secolo', 1490, NULL, 'architettura', '{}', '{}', 'Pavia', 'Certosa di Pavia', NULL, NULL, 1, 0, 0, '', 2, 'Monumentale ingresso di gusto classico con colonne binate e timpano triangolare, esempio dell''evoluzione verso forme rinascimentali', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('presentazione-della-certosa-alla-vergine-da-parte-di-gian-galeazzo', 'Presentazione della Certosa alla Vergine da parte di Gian Galeazzo', '{ambrogio-da-fossano-detto-il-bergognone}', NULL, '1488-1494', 1488, 1494, 'affresco', '{}', '{}', 'Pavia', 'Certosa delle Grazie, chiesa conventuale', NULL, NULL, 1, 0, 0, '', 3, 'Affresco della volta del transetto della Certosa di Pavia che raffigura la presentazione del monastero alla Vergine da parte di Gian Galeazzo Visconti. Opera caratterizzata da rigide composizioni simmetriche e aspetto monumentale celebrativo.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('madonna-del-ceroso', 'Madonna del Ceroso', '{ambrogio-da-fossano-detto-il-bergognone}', NULL, '1488-1494, tempera su tavola', 1488, 1494, 'tavola', '{}', '{}', 'Milano', 'Pinacoteca di Brera', NULL, NULL, 1, 0, 0, '', 2, 'Tavola devozionale privata di piccolo formato (46 x 40,5 cm) che rappresenta la Madonna col Bambino con santi (probabilmente Santa Caterina d''Alessandria e San Francesco). Opera caratterizzata da cromie spente, sfumato trasportato devozionale e maggiore valenza narrativa rispetto agli affreschi.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('cappella-colleoni', 'Cappella Colleoni', '{giovanni-antonio-amadeo}', NULL, '1472-1476', 1472, 1476, 'architettura', '{}', '{}', 'Bergamo', 'Piazza Duomo, accanto alla Basilica di Santa Maria Maggiore', NULL, NULL, 1, 0, 0, '', 3, 'Cappella funebre a pianta ottagonale con cupola a spicchi, facciata riccamente decorata con elementi classici (colonne corinzie, timpani, frontoni), marmi policromi e sculture. Opera che segna il passaggio dal gotico internazionale al linguaggio rinascimentale in ambito lombardo.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('monumento-funebre-di-bartolomeo-colleoni', 'Monumento funebre di Bartolomeo Colleoni', '{giovanni-antonio-amadeo-con-andrea-del-verrocchio-per-la-statua-equestre}', NULL, 'dal 1488', 1488, NULL, 'scultura', '{}', '{}', 'Venezia', 'chiesa dei Santi Giovanni e Paolo', NULL, NULL, 1, 0, 0, '', 2, 'Monumento funebre con statua equestre bronzea del condottiero su alto basamento in marmo, circondato da figure allegoriche e decorazioni architettoniche. L''opera unisce la tradizione toscana (statua del Verrocchio) con elementi decorativi lombardi (basamento dell''Amadeo).', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.works (id, title, artist_ids, period_id, date_text, year_start, year_end, type, technique_ids, materials, location_city, location_place, lat, lon, book, chapter, page, source_file, importance, summary, analysis, innovations, term_ids, image_url, image_thumb, image_source) VALUES ('tre-crocifissi', 'Tre Crocifissi', '{vincenzo-foppa}', NULL, '1456', 1456, 1456, 'tavola', '{}', '{}', 'Bergamo', 'Accademia Carrara', NULL, NULL, 1, 0, 0, '', 2, 'Prima opera firmata e datata di Foppa, raffigurante tre crocifissi entro un arco classico con ritratti di imperatori romani ai lati. Presenta tridimensionalità dei corpi, luce calda e velata, uso della prospettiva dal basso (di sotto in sù), modelli tardo-gotici uniti a studio anatomico e prospettica geometrica moderna.', NULL, '{}', '{}', '', '', '') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, summary = COALESCE(NULLIF(EXCLUDED.summary, ''), works.summary), year_start = COALESCE(EXCLUDED.year_start, works.year_start), year_end = COALESCE(EXCLUDED.year_end, works.year_end);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('nascita-di-andrea-mantegna', 1431, NULL, 'Nascita di Andrea Mantegna', 'Andrea Mantegna nasce a Isola di Carturo, presso Padova.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('inizio-lavori-cappella-ovetari', 1449, NULL, 'Inizio lavori Cappella Ovetari', 'Mantegna viene coinvolto nella decorazione ad affresco della cappella Ovetari nella chiesa degli Eremitani a Padova.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('matrimonio-con-nicolosia-bellini', 1453, NULL, 'Matrimonio con Nicolosia Bellini', 'Mantegna sposa Nicolosia Bellini, sorella dei pittori veneziani Gentile e Giovanni Bellini.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('morte-di-niccolo-pizzolo', 1453, NULL, 'Morte di Niccolò Pizzolo', 'Morte del collaboratore Niccolò Pizzolo; Mantegna diventa responsabile di tutta la decorazione pittorica della cappella Ovetari.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('trasferimento-a-mantova', 1460, NULL, 'Trasferimento a Mantova', 'Mantegna si trasferisce definitivamente a Mantova su invito di Ludovico Gonzaga, assumendo il ruolo di pittore di corte.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('viaggio-in-toscana', 1466, NULL, 'Viaggio in Toscana', 'Primo dei due viaggi importanti compiuti da Mantegna durante il periodo mantovano, in Toscana.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('soggiorno-romano', 1488, NULL, 'Soggiorno romano', 'Mantegna soggiorna a Roma chiamato da papa Innocenzo VIII.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('ritorno-da-roma', 1490, NULL, 'Ritorno da Roma', 'Mantegna rientra a Mantova dopo il soggiorno romano.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('morte-di-andrea-mantegna', 1506, NULL, 'Morte di Andrea Mantegna', 'Mantegna muore a Mantova, città dove aveva vissuto e lavorato come pittore di corte dal 1460.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('distruzione-affreschi-cappella-ovetari', 1944, NULL, 'Distruzione affreschi Cappella Ovetari', 'Gli affreschi della cappella Ovetari vengono distrutti durante la Seconda guerra mondiale; ne rimangono solo due porzioni riportate su tela nell''Ottocento.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('nomina-di-gregorio-correr-ad-abate-di-san-zeno', 1443, NULL, 'Nomina di Gregorio Correr ad abate di San Zeno', 'Gregorio Correr viene nominato abate di San Zeno a Verona, evento che precede la commissione della Pala di Mantegna.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('esecuzione-della-pala-di-san-zeno', 1456, NULL, 'Esecuzione della Pala di San Zeno', 'Inizio dei lavori per la Pala di San Zeno commissionata dall''abate Gregorio Correr.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('completamento-della-pala-di-san-zeno', 1459, NULL, 'Completamento della Pala di San Zeno', 'Conclusione dell''opera di Andrea Mantegna per la basilica veronese.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('restauri-della-pala-di-san-zeno', 2007, NULL, 'Restauri della Pala di San Zeno', 'Durante i restauri condotti nel 2007 è stata rilevata la corrispondenza del tappeto con la data 1443, confermando la datazione della committenza.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('commissione-della-pala-di-san-zeno', 1443, NULL, 'Commissione della Pala di San Zeno', 'L''abate Gregorio Correr commissiona ad Andrea Mantegna la realizzazione della pala d''altare per la Basilica di San Zeno a Verona', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('restauro-della-pala-di-san-zeno', 2007, NULL, 'Restauro della Pala di San Zeno', 'Durante i restauri condotti nel 2007, viene rilevata sul tappeto della data 1443, confermando l''anno della commissione dell''opera', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('inizio-collaborazione-mantegna-gonzaga', 1460, NULL, 'Inizio collaborazione Mantegna-Gonzaga', 'Mantegna inizia a lavorare per la famiglia Gonzaga a Mantova, dove resterà per oltre quarant''anni', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('affidamento-morte-della-vergine', 1462, NULL, 'Affidamento Morte della Vergine', 'Ludovico Gonzaga affida a Mantegna la decorazione della cappella del castello di San Giorgio con la Morte della Vergine', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('affidamento-camera-degli-sposi', 1465, NULL, 'Affidamento Camera degli Sposi', 'Ludovico affida a Andrea Mantegna anche la decorazione di una piccola stanza nel torzione di nord-est del castello di San Giorgio (Camera degli Sposi)', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('commissione-della-camera-degli-sposi', 1465, NULL, 'Commissione della Camera degli Sposi', 'Ludovico Gonzaga affida ad Andrea Mantegna la decorazione di una piccola stanza nel torrione nord-est del castello di San Giorgio a Mantova', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-del-compianto-sul-cristo-morto', 1475, NULL, 'Realizzazione del Compianto sul Cristo morto', 'Mantegna realizza il Compianto sul Cristo morto, opera privata destinata alla devozione personale, dopo il 1475', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('inizio-lavori-decorazione-camera-degli-sposi', 1465, NULL, 'Inizio lavori decorazione Camera degli Sposi', 'Andrea Mantegna inizia a decorare la piccola stanza cubica nel castello di San Giorgio su commissione di Ludovico III Gonzaga.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('conclusione-decorazione-camera-degli-sposi', 1474, NULL, 'Conclusione decorazione Camera degli Sposi', 'Mantegna conclude la straordinaria decorazione pittorica, testimoniata dalla targa dorata sulla porta occidentale.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('incontro-ludovico-gonzaga---cardinale-francesco-gonzaga', NULL, NULL, 'Incontro Ludovico Gonzaga - Cardinale Francesco Gonzaga', 'Scene raffigurate negli affreschi: l''incontro del marchese Ludovico col figlio cardinale Francesco (affresco 2) e la scena di caccia (affresco 3).', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('inizio-lavori-camera-degli-sposi', 1465, NULL, 'Inizio lavori Camera degli Sposi', 'Inizio dei lavori di Andrea Mantegna per la decorazione affrescata della Camera degli Sposi nel Palazzo Ducale di Mantova.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('completamento-camera-degli-sposi', 1474, NULL, 'Completamento Camera degli Sposi', 'Completamento del ciclo di affreschi della Camera degli Sposi dopo circa nove anni di lavoro.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('stipula-del-contratto-per-la-camera-degli-sposi', 1465, NULL, 'Stipula del contratto per la Camera degli Sposi', 'Ludovico III Gonzaga affida ad Andrea Mantegna l''incarico di decorare una sala della Torre della Gabbia nel Palazzo Ducale di Mantova, dando inizio al capolavoro della Camera Picta.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('nomina-a-cardinale-di-francesco-gonzaga', 1463, NULL, 'Nomina a cardinale di Francesco Gonzaga', 'Francesco, secondogenito di Ludovico III Gonzaga, viene nominato cardinale grazie all''appoggio di Francesco Sforza, evento celebrato nell''affresco della parete occidentale della Camera.', 'politico', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('incontro-tra-ludovico-iii-e-il-figlio-cardinale-francesco', 1474, NULL, 'Incontro tra Ludovico III e il figlio cardinale Francesco', 'Episodio reale raffigurato da Mantegna nella Camera degli Sposi, momento di incontro tra il marchese e il figlio tornato da Roma, con presenza di dignitari e segretari.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('completamento-della-camera-degli-sposi', 1474, NULL, 'Completamento della Camera degli Sposi', 'Terminazione dei lavori di decorazione della Camera Picta, dopo circa nove anni di lavoro, con l''esecuzione delle ultime scene e dei dettagli ornamentali.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('decorazione-della-camera-degli-sposi', 1465, NULL, 'Decorazione della Camera degli Sposi', 'Inizio dei lavori di Andrea Mantegna alla decorazione affrescata della camera da letto dei Gonzaga nel Palazzo Ducale di Mantova', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('incontro-tra-ludovico-gonzaga-e-federico-iii-dasburgo', 1472, NULL, 'Incontro tra Ludovico Gonzaga e Federico III d''Asburgo', 'Evento storico commemorato nella scena dell''Incontro sulla parete ovest della Camera degli Sposi', 'politico', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-della-pala-di-san-zeno', 1457, NULL, 'Realizzazione della Pala di San Zeno', 'Opera precedente di Mantegna che sperimenta l''imposizione architettonica poi sviluppata nella Camera degli Sposi', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('chiamata-di-mantegna-a-roma-da-papa-innocenzo-viii', 1488, NULL, 'Chiamata di Mantegna a Roma da Papa Innocenzo VIII', 'Il papa chiama Mantegna a Roma per realizzare affreschi in una cappella palatina (distrutta nel 1780), occasione che consente al maestro lo studio diretto dei modelli antichi', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('inizio-lavori-studiolo-di-isabella-deste', 1490, NULL, 'Inizio lavori Studiolo di Isabella d''Este', 'Il marchese Francesco II Gonzaga sposa Isabella d''Este e inizia la creazione dello spazio privato con biblioteca e collezione di antichità', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-del-parnaso', 1497, NULL, 'Realizzazione del Parnaso', 'Mantegna realizza il Parnaso per lo Studiolo di Isabella d''Este, prima opera che mostra una svolta qualitativa verso stilemi più liberi e anticipatori del Cinquecento', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('unificazione-del-regno-di-napoli-e-sicilia', 1443, NULL, 'Unificazione del regno di Napoli e Sicilia', 'Alfonso d''Aragona prende il potere e unifica il regno di Napoli con quello di Sicilia, dando inizio al periodo aragonese', 'politico', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('arrivo-di-jean-fouquet-a-roma', 1444, NULL, 'Arrivo di Jean Fouquet a Roma', 'Il pittore francese Jean Fouquet giunge a Roma e successivamente si spinge fino a Napoli', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('soggiorno-di-jean-fouquet-a-napoli', NULL, NULL, 'Soggiorno di Jean Fouquet a Napoli', 'Jean Fouquet risiede a Napoli dove realizza i cartoni della Passione di Cristo', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('morte-di-alfonso-daragona', 1458, NULL, 'Morte di Alfonso d''Aragona', 'Fine del regno di Alfonso d''Aragona e ascesa al trono del figlio Ferdinando I (Ferrante)', 'politico', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('alleanza-con-lorenzo-il-magnifico', NULL, NULL, 'Alleanza con Lorenzo il Magnifico', 'Ferdinando I d''Aragona stringe alleanza con Lorenzo de'' Medici, favorendo l''arrivo di artisti fiorentini a Napoli', 'politico', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('commissione-del-monumento-funebre-di-alfonso-daragona', 1490, NULL, 'Commissione del Monumento funebre di Alfonso d''Aragona', 'Ferdinando I commissiona a Benedetto da Maiano il monumento funebre del padre Alfonso nella cappella Piccolomini', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('invasione-di-carlo-viii-di-valois', 1495, NULL, 'Invasione di Carlo VIII di Valois', 'L''invasione del re di Francia provoca la fuga degli Aragonesi da Napoli e interrompe il periodo aragonese', 'politico', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('costruzione-cappella-piccolomini', 1475, NULL, 'Costruzione Cappella Piccolomini', 'Inizio dei lavori della Cappella Piccolomini nella chiesa di Sant''Anna dei Lombardi a Napoli su progetto di Benedetto da Maiano e Antonio Rossellino', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('progettazione-porta-capuana', 1484, NULL, 'Progettazione Porta Capuana', 'Progettazione della Porta Capuana da parte di Giuliano da Maiano nell''ambito del programma di rafforzamento delle fortificazioni cittadine voluto da Ferdinando I', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('ingresso-trionfale-di-alfonso-daragona-a-napoli', 1443, NULL, 'Ingresso trionfale di Alfonso d''Aragona a Napoli', 'Alfonso V d''Aragona entra trionfalmente a Napoli dopo la conquista del regno, evento commemorato dalla costruzione dell''Arco trionfale di Castel Nuovo', 'politico', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('inizio-costruzione-arco-trionfale-di-castel-nuovo', 1452, NULL, 'Inizio costruzione Arco trionfale di Castel Nuovo', 'Avvio dei lavori di costruzione dell''arco trionfale rivolto verso il centro antico della città', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('interruzione-lavori-arco-trionfale', 1458, NULL, 'Interruzione lavori Arco trionfale', 'Sospensione dei lavori di costruzione dell''arco trionfale', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('completamento-arco-trionfale-di-castel-nuovo', 1471, NULL, 'Completamento Arco trionfale di Castel Nuovo', 'Terminazione dei lavori dell''arco trionfale sotto il regno di Ferdinando I', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('arrivo-di-francesco-laurana-a-napoli', 1453, NULL, 'Arrivo di Francesco Laurana a Napoli', 'Lo scultore dalmata arriva a Napoli verosimilmente insieme all''architetto Luciano, iniziando la sua carriera italiana al servizio di Renato d''Angiò', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('trasferimento-di-laurana-in-sicilia', 1468, NULL, 'Trasferimento di Laurana in Sicilia', 'Laurana si trasferisce in Sicilia dove continua la sua attività di scultore e ritrattista', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-delle-opere-di-colantonio-per-san-lorenzo-maggiore', 1445, NULL, 'Realizzazione delle opere di Colantonio per San Lorenzo Maggiore', 'Nel periodo aragonese, attorno al 1445, Colantonio realizza il capolavoro comprendente San Gerolamo nello studio e San Francesco consegna la regola agli ordini francescani per la chiesa franciscana di San Lorenzo Maggiore a Napoli', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('formazione-nella-bottega-di-colantonio', 1450, NULL, 'Formazione nella bottega di Colantonio', 'Intorno al 1450 Antonello si forma nella bottega di Colantonio a Napoli, centro commerciale fiorente che lo espone alle influenze fiamminghe.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('viaggio-a-roma', 1459, NULL, 'Viaggio a Roma', 'Viaggio fondamentale in cui Antonello entra in contatto con le impostazioni geometriche e prospettiche e con la lezione di Piero della Francesca.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('soggiorno-a-venezia', NULL, NULL, 'Soggiorno a Venezia', 'Esperienza fondamentale in cui Antonello perfeziona lo studio della luce e raggiunge la piena potenza espressiva, realizzando opere come San Sebastiano e San Gerolamo nello studio.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('ritorno-e-morte-a-messina', 1479, NULL, 'Ritorno e morte a Messina', 'Dopo aver lasciato la città lagunare, l''artista prosegue la sua attività a Messina fino alla morte avvenuta nel 1479.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('arrivo-di-antonello-da-messina-a-venezia', 1474, NULL, 'Arrivo di Antonello da Messina a Venezia', 'Antonello da Messina giunge a Venezia probabilmente nel 1474, iniziando un soggiorno che si protrarrà fino al marzo 1476', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-della-vergine-annunziata', 1475, NULL, 'Realizzazione della Vergine Annunziata', 'Tra il 1475 e il 1476 Antonello dipinge la piccola tavola della Vergine Annunziata durante il soggiorno veneziano', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('commissione-della-pala-di-san-cassiano', 1475, NULL, 'Commissione della Pala di San Cassiano', 'Il patrizio Pietro Bon commissiona ad Antonello da Messina la pala d''altare per la chiesa di San Cassiano a Venezia', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('ricostruzione-novecentesca-della-composizione-originaria', 1900, NULL, 'Ricostruzione novecentesca della composizione originaria', 'Proposta all''inizio del Novecento di ricostruzione della composizione originaria con figure inserite in struttura architettonica classicheggiante', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-del-san-sebastiano-per-la-scuola-dei-santi-rocco-e-nicolo', 1478, NULL, 'Realizzazione del San Sebastiano per la Scuola dei Santi Rocco e Nicolò', 'Commissione dell''opera alla parrocchia di San Zulian a Venezia come parte di un trittico comprendente anche San Rocco e San Cristoforo', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('traduzione-della-bibbia-in-latino-da-parte-di-san-gerolamo', NULL, NULL, 'Traduzione della Bibbia in latino da parte di san Gerolamo', 'San Gerolamo, Padre e Dottore della Chiesa vissuto tra IV e V secolo, tradusse la Bibbia in latino (Vulgata). Secondo la tradizione radicata fu anche di origine cardinale.', 'religioso', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('soggiorno-di-antonello-da-messina-a-venezia', 1475, NULL, 'Soggiorno di Antonello da Messina a Venezia', 'Periodo durante il quale Antonello potrebbe aver realizzato il suo San Gerolamo nello studio, portando con sé la tecnica dell''olio su tavola appresa dai modelli fiamminghi.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('documentazione-dellopera-di-van-eyck-a-napoli', 1456, NULL, 'Documentazione dell''opera di Van Eyck a Napoli', 'Documentazione a Napoli di un dipinto di analogo soggetto di Van Eyck che influenzò Antonello da Messina', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('collocazione-originale-del-san-gerolamo', NULL, NULL, 'Collocazione originale del San Gerolamo', 'L''opera era originariamente collocata nella chiesa di San Lorenzo Maggiore a Napoli di ordine francescano', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('arrivo-di-mauro-codussi-a-venezia', 1468, NULL, 'Arrivo di Mauro Codussi a Venezia', 'Mauro Codussi, formatosi a Ravenna, approda a Venezia alla fine degli anni sessanta del Quattrocento portando nuove influenze architettoniche', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('inizio-lavori-chiesa-di-santa-maria-dei-miracoli', 1481, NULL, 'Inizio lavori Chiesa di Santa Maria dei Miracoli', 'Inizio della costruzione della chiesa di Santa Maria dei Miracoli su progetto di Pietro Solari (Lombardo)', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('costruzione-ca-vendramin-calergi', 1481, NULL, 'Costruzione Ca'' Vendramin Calergi', 'Inizio della costruzione del palazzo privato Ca'' Vendramin Calergi su progetto di Mauro Codussi, modello per lo sviluppo del palazzo veneziano', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('trasferimento-di-mantegna-a-padova', 1448, NULL, 'Trasferimento di Mantegna a Padova', 'Mantegna si trasferisce a Padova per affrescare la cappella Ovetari, entrando in contatto con l''opera di Donatello e con i pittori toscani come Andrea del Castagno e Paolo Uccello', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('pubblicazione-della-bibbia-di-gutenberg', 1455, NULL, 'Pubblicazione della Bibbia di Gutenberg', 'Vent''anni dopo quasi tutte le principali città del continente possiedono un''officina di stampa; a fine secolo in Europa si contano oltre 200 stamperie', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('fuga-degli-eruditi-da-costantinopoli', 1453, NULL, 'Fuga degli eruditi da Costantinopoli', 'Caduta di Costantinopoli e rifugio degli eruditi bizantini a Venezia (nelle mani dei Turchi), portando con sé la tradizione della cultura greca classica che alimenta l''attività di Aldo Manuzio', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('fondazione-della-stamperia-di-aldo-manuzio-a-venezia', NULL, NULL, 'Fondazione della stamperia di Aldo Manuzio a Venezia', 'Aldo Manuzio fonda una stamperia a Venezia, città ideale legata alla tradizione bizantina e rifugio degli eruditi, iniziando la pubblicazione di testi greci e classici', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('soggiorno-a-verona', 1436, NULL, 'Soggiorno a Verona', 'Jacopo Bellini soggiorna a Verona', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('soggiorno-a-ferrara', 1440, NULL, 'Soggiorno a Ferrara', 'Jacopo Bellini soggiorna a Ferrara fino al 1441', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('guarigione-miracolosa-di-un-devoto-bresciano', 1444, NULL, 'Guarigione miracolosa di un devoto bresciano', 'Evento miracoloso avvenuto durante una festa religiosa in piazza San Marco, raffigurato da Gentile Bellini nel telerio Processione in piazza San Marco', 'religioso', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('invito-di-maometto-ii-a-gentile-bellini', 1479, NULL, 'Invito di Maometto II a Gentile Bellini', 'Gentile viene invitato dalle autorità veneziane a Costantinopoli per ritrarre il sultano conquistatore Maometto II', 'politico', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('donazione-della-vera-croce-alla-confraternita', 1369, NULL, 'Donazione della Vera Croce alla confraternita', 'La Vera Croce donata alla confraternita nel 1369 da Philippe de Mézières, cancelliere del regno di Gerusalemme', 'religioso', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-del-ciclo-di-santorsola', 1490, NULL, 'Realizzazione del ciclo di Sant''Orsola', 'Inizio della realizzazione del ciclo di nove teleri delle Storie di sant''Orsola per la Scuola di Sant''Orsola, completato nel 1497', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-del-miracolo-della-croce-a-rialto', 1494, NULL, 'Realizzazione del Miracolo della Croce a Rialto', 'Esecuzione del telerio del Miracolo della reliquia della Croce a Rialto (1494-1496), parte del ciclo della Scuola Grande di San Giovanni Evangelista', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('matrimonio-tra-nicolosia-bellini-e-andrea-mantegna', 1453, NULL, 'Matrimonio tra Nicolosia Bellini e Andrea Mantegna', 'Nicolosia, sorella di Giovanni Bellini, sposa Andrea Mantegna, creando un legame familiare e artistico tra i due pittori', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('nomina-a-pittore-ufficiale-della-serenissima', 1483, NULL, 'Nomina a pittore ufficiale della Serenissima', 'Giovanni Bellini viene nominato pittore ufficiale della Repubblica di Venezia, riconoscimento ufficiale del suo ruolo di primo piano', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('morte-di-giovanni-bellini', 1516, NULL, 'Morte di Giovanni Bellini', 'Morte dell''artista a Venezia dopo una lunga carriera', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('matrimonio-di-andrea-mantegna-con-nicolosia-bellini', 1453, NULL, 'Matrimonio di Andrea Mantegna con Nicolosia Bellini', 'Unione familiare che rafforzò i legami tra le botteghe dei due artisti e facilitò lo scambio culturale tra Padova e Venezia', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-dellorazione-nellorto', 1467, NULL, 'Realizzazione dell''Orazione nell''orto', 'Opera chiave nel percorso di autonomizzazione stilistica di Giovanni Bellini rispetto al modello mantegnesco', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-della-pala-di-pesaro', 1470, NULL, 'Realizzazione della Pala di Pesaro', 'Inizio della realizzazione della Pala di Pesaro commissionata probabilmente dalla famiglia Sforza di Pesaro', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('completamento-della-pala-di-pesaro', 1475, NULL, 'Completamento della Pala di Pesaro', 'Completamento e consegna della Pala di Pesaro alla chiesa di destinazione', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('ricostruzione-della-cornice-della-pala-di-pesaro', 1925, NULL, 'Ricostruzione della cornice della Pala di Pesaro', 'Ricostruzione della cornice architettonica della pala nella prima metà del XX secolo', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-della-pala-di-san-zaccaria', 1505, NULL, 'Realizzazione della Pala di San Zaccaria', 'Completamento di una delle ultime grandi pale d''altare di Giovanni Bellini, considerata tra i suoi capolavori maturi', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('elezione-di-leonardo-loredan-come-doge', 1501, NULL, 'Elezione di Leonardo Loredan come doge', 'Leonardo Loredan viene eletto doge di Venezia, evento commemorato dal celebre ritratto di Giovanni Bellini', 'politico', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('guerra-contro-venezia', 1482, NULL, 'Guerra contro Venezia', 'Conflitto combattuto da Ercole I d''Este contro la Serenissima, conclusosi in modo disastroso per Ferrara con la cessione del Polesine e Rovigo.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('ascesa-di-leonello-deste', 1441, NULL, 'Ascesa di Leonello d''Este', 'Leonello diventa marchese di Ferrara, iniziando una politica di mecenatismo che trasforma la città in centro culturale.', 'politico', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('morte-di-leonello-deste', 1450, NULL, 'Morte di Leonello d''Este', 'Fine del periodo di governo di Leonello; succede il fratello Borso I.', 'politico', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('costruzione-mura-e-addizione-erculea', 1492, NULL, 'Costruzione mura e Addizione Erculea', 'Inizio dei lavori di costruzione delle mura e dell''ampliamento urbano settentrionale di Ferrara su progetto di Biagio Rossetti', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('nomina-di-biagio-rossetti-architetto-di-corte', 1483, NULL, 'Nomina di Biagio Rossetti architetto di corte', 'Biagio Rossetti viene nominato architetto di corte degli Este', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('costruzione-dello-studiolo-di-belriguardo', 1447, NULL, 'Costruzione dello Studiolo di Belriguardo', 'Il marchese Leonello d''Este avvia la costruzione e decorazione del suo studiolo privato nella villa di Belriguardo, affidando a Guarino Veronese la definizione del progetto iconografico dedicato alle Muse.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('completamento-decorazione-studiolo', 1463, NULL, 'Completamento decorazione Studiolo', 'Termine della decorazione dello studiolo di Belriguardo, suddivisa in due facciate: superiore con figure delle Muse in tavola, inferiore con tarsie lignee.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('distruzione-dello-studiolo-di-belriguardo', 1482, NULL, 'Distruzione dello Studiolo di Belriguardo', 'Lo studiolo andato distrutto a causa del terremoto o eventi bellici; le opere d''arte vengono disperse e oggi conservate in vari musei.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('soggiorno-a-padova-e-venezia-di-cosme-tura', 1450, NULL, 'Soggiorno a Padova e Venezia di Cosmè Tura', 'Dopo un viaggio poetico a Padova e Venezia (circa 1450-1456), Tura entra in contatto con Donatello, Mantegna e Squarcione', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('ritorno-a-ferrara-di-cosme-tura', 1456, NULL, 'Ritorno a Ferrara di Cosmè Tura', 'Tura torna a Ferrara e inizia una fortunata carriera come pittore di corte', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-delle-ante-dellorgano-del-duomo-di-ferrara', 1469, NULL, 'Realizzazione delle ante dell''organo del Duomo di Ferrara', 'Commissione a Cosmè Tura delle ante decorate per l''organo del duomo di Ferrara, comprendenti San Giorgio e la principessa e l''Annunciazione', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('danneggiamento-del-politico-roverella', NULL, NULL, 'Danneggiamento del Politico Roverella', 'Il Politico Roverella viene danneggiato da un colpo di cannone', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('smembramento-del-politico-roverella', NULL, NULL, 'Smembramento del Politico Roverella', 'Nel Settecento l''opera viene smembrata e le parti disperse in musei europei e americani', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('viaggio-in-toscana-di-francesco-del-cossa', NULL, NULL, 'Viaggio in Toscana di Francesco del Cossa', 'Viaggio formativo di Francesco del Cossa in Toscana che influenza il suo stile', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('rottura-con-borso-deste', 1470, NULL, 'Rottura con Borso d''Este', 'Francesco del Cossa interrompe i rapporti con la corte ferrarese inviando una lettera di protesta per il trattamento economico', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('trasferimento-a-bologna', 1470, NULL, 'Trasferimento a Bologna', 'Dopo la rottura con la corte ferrarese, Francesco del Cossa si trasferisce a Bologna dove lavora al Politico Griffoni', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-del-polittico-griffoni', 1470, NULL, 'Realizzazione del Polittico Griffoni', 'Inizio dei lavori per il polittico commissionato dalla famiglia Griffoni per la cappella di San Petronio a Bologna', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('completamento-del-polittico-griffoni', 1473, NULL, 'Completamento del Polittico Griffoni', 'Conclusione del Polittico Griffoni ad opera di Francesco del Cossa ed Ercole de'' Roberti', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
