INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('arrivo-di-ercole-de-roberti-a-ferrara-come-pittore-di-corte', 1487, NULL, 'Arrivo di Ercole de'' Roberti a Ferrara come pittore di corte', 'Roberti raggiunge Cosmè Tura assumendo il ruolo di pittore di corte ferrarese, segnando l''inizio della sua fase matura.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('morte-di-francesco-del-cossa', 1478, NULL, 'Morte di Francesco del Cossa', 'La morte del maestro apre la strada a Ercole de'' Roberti per la commissione degli affreschi della cappella Garganelli a Bologna.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('conclusione-affreschi-cappella-garganelli', 1490, NULL, 'Conclusione affreschi cappella Garganelli', 'Termine dei lavori decorativi della cappella Garganelli nella cattedrale di San Pietro a Bologna.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('inizio-lavori-ciclo-dei-mesi', 1467, NULL, 'Inizio lavori ciclo dei Mesi', 'Inizio della realizzazione del complesso ciclo decorativo del Salone d''onore di Palazzo Schifanoia', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('commissione-ristrutturazione-palazzo-schifanoia', 1465, NULL, 'Commissione ristrutturazione Palazzo Schifanoia', 'Borso d''Este affida all''architetto Pietro Benvogliente l''incarico di ristrutturare il palazzo come residenza di rappresentanza', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('esecuzione-della-decorazione-del-salone-dei-mesi', 1469, NULL, 'Esecuzione della decorazione del Salone dei Mesi', 'Inizio dei lavori di decorazione del Salone dei Mesi di Palazzo Schifanoia a Ferrara, affidati a un congruo numero di pittori dell''officina ferrarese tra cui Cosmè Tura, Francesco del Cossa ed Ercole de'' Roberti', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('ufficializzazione-della-nomina-a-duca-di-ferrara-di-borso-deste', 1471, NULL, 'Ufficializzazione della nomina a Duca di Ferrara di Borso d''Este', 'Borso d''Este viene nominato ufficialmente duca di Ferrara dal Papa; l''opera doveva essere ultimata entro questa data per celebrare l''avvenimento', 'politico', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-del-ciclo-di-affreschi-della-sala-dei-mesi', 1469, NULL, 'Realizzazione del ciclo di affreschi della Sala dei Mesi', 'Inizio dei lavori di decorazione della Sala dei Mesi di Palazzo Schifanoi con la partecipazione di Francesco del Cossa, Ercole de'' Roberti e altri artisti dell''officina ferrarese', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-degli-affreschi-del-mese-di-aprile', 1470, NULL, 'Realizzazione degli affreschi del Mese di Aprile', 'Francesco del Cossa completa gli affreschi del Mese di Aprile nel Salone dei Mesi di Palazzo Schifanoia, Ferrara, inviando successivamente una lettera di reclamo al duca Borso d''Este per la retribuzione ritenuta non proporzionata alla qualità del lavoro', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('composizione-dei-trionfi-di-petrarca', 1351, NULL, 'Composizione dei Trionfi di Petrarca', 'Completamento dell''opera poetica dei Trionfi di Francesco Petrarca, che diventerà fonte iconografica essenziale per l''arte rinascimentale italiana', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('palo-di-santagata-a-ferrara', NULL, NULL, 'Palo di Sant''Agata a Ferrara', 'Evento culturale e religioso cittadino documentato nella fascia inferiore degli affreschi del Mese di Aprile, esempio di come l''arte registrasse manifestazioni sociali contemporanee', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('arrivo-di-filarete-a-milano', 1450, NULL, 'Arrivo di Filarete a Milano', 'Filarete viene chiamato a Milano dal Duca Francesco Sforza per lavorare alla ricostruzione e modernizzazione architecttonica del ducato, segnando l''incontro tra cultura fiorentina e tradizione lombarda.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('inizio-lavori-ospedale-maggiore', 1456, NULL, 'Inizio lavori Ospedale Maggiore', 'Avvio della costruzione dell''Ospedale Maggiore di Milano su progetto di Filarete, opera destinata a diventare il simbolo del nuovo umanesimo sforzesco.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('partenza-di-filarete-da-milano', 1465, NULL, 'Partenza di Filarete da Milano', 'Filarete lascia Milano dopo quindici anni di attività; i suoi lavori vengono continuati da Guiniforte Solari secondo le direttive originali ma con adattamenti locali.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('morte-di-francesco-sforza', 1466, NULL, 'Morte di Francesco Sforza', 'Morte del Duca committente, evento che segna una svolta nella politica artistica milanese e nella prosecuzione dei grandi cantieri avviati.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('composizione-del-trattato-di-architettura', 1460, NULL, 'Composizione del Trattato di architettura', 'Periodo di stesura del trattato teorico di Filarete, fondamentale documento sulla diffusione dell''architettura rinascimentale in Lombardia.', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('redazione-del-trattato-di-architettura-di-filarete', 1460, NULL, 'Redazione del Trattato di architettura di Filarete', 'Inizio della stesura del trattato che contiene il progetto della città ideale di Sforzinda, durante il soggiorno di Filarete a Milano alla corte degli Sforza', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('inizio-lavori-ospedale-maggiore-di-milano', 1456, NULL, 'Inizio lavori Ospedale Maggiore di Milano', 'Avvio della costruzione del grande complesso ospedaliero milanese su progetto di Filarete, commesso da Francesco Sforza', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('fondazione-della-certosa-di-pavia', 1396, NULL, 'Fondazione della Certosa di Pavia', 'Gian Galeazzo Visconti fonda la Certosa come mausoleo dinastico per la famiglia Visconti, iniziando i lavori di costruzione', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('inizio-affreschi-di-mantegna', 1473, NULL, 'Inizio affreschi di Mantegna', 'Andrea Mantegna esegue i primi affreschi sulla facciata della Certosa, inaugurando la fase decorativa del monumento', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('nomina-di-amadeo', 1481, NULL, 'Nomina di Amadeo', 'Dopo la morte di Guiniforte Solari, Giovanni Antonio Amadeo assume la direzione dei lavori della Certosa, modificando il progetto originario', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('affreschi-di-bergognone', 1488, NULL, 'Affreschi di Bergognone', 'Inizio dei lavori di Bergognone per la decorazione pittorica del coro e del transetto della Certosa, che si protrarranno fino al 1495', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('attivita-del-bergognone-a-milano', 1481, NULL, 'Attività del Bergognone a Milano', 'L''artista si trasferisce a Milano dove lavorerà fino al 1495', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('decorazione-della-certosa-di-pavia', NULL, NULL, 'Decorazione della Certosa di Pavia', 'Periodo di attività del Bergognone alla decorazione ad affresco della volta, del transetto e delle pareti della chiesa della Certosa di Pavia', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('costruzione-della-cappella-colleoni', 1472, NULL, 'Costruzione della Cappella Colleoni', 'Inizio dei lavori della cappella funebre voluta da Bartolomeo Colleoni a Bergamo, affidata a Giovanni Antonio Amadeo', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('completamento-della-cappella-colleoni', 1476, NULL, 'Completamento della Cappella Colleoni', 'Termine della costruzione della cappella, uno dei capolavori del Rinascimento lombardo', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('inizio-del-monumento-funebre-di-colleoni-a-venezia', 1488, NULL, 'Inizio del Monumento funebre di Colleoni a Venezia', 'Inizio dei lavori per il monumento funebre equestre nella chiesa dei Santi Giovanni e Paolo a Venezia, con la statua bronzea del Verrocchio e il basamento dell''Amadeo', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('arrivo-di-vincenzo-foppa-a-milano', 1463, NULL, 'Arrivo di Vincenzo Foppa a Milano', 'Foppa si trasferisce a Milano dove lavora come pittore di corte sotto gli Sforza, entrando in contatto con artisti e intellettuali fiorentini residenti in città', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.events (id, year, year_end, title, description, kind, period_id) VALUES ('realizzazione-del-tre-crocifissi', 1456, NULL, 'Realizzazione del Tre Crocifissi', 'Esecuzione della prima opera firmata e datata di Vincenzo Foppa, conservata oggi all''Accademia Carrara di Bergamo', 'culturale', NULL) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, year = COALESCE(EXCLUDED.year, events.year);
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('squarcione-andrea-mantegna-maestro-allievo', 'artist', 'squarcione', 'artist', 'andrea-mantegna', 'maestro-allievo', 'Mantegna si forma nella bottega di Squarcione a Padova per circa dieci anni, poi sviluppa uno stile personale distaccato dal maestro.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('donatello-andrea-mantegna-influenza', 'artist', 'donatello', 'artist', 'andrea-mantegna', 'influenza', 'Influenza sul tratto inciso e sicuro e sull''impostazione salda e monumentale delle figure del giovane Mantenga.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('filippo-lippi-andrea-mantegna-influenza', 'artist', 'filippo-lippi', 'artist', 'andrea-mantegna', 'influenza', 'Influenza toscana presente a Padova negli anni giovanili di Mantegna.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('andrea-del-castagno-andrea-mantegna-influenza', 'artist', 'andrea-del-castagno', 'artist', 'andrea-mantegna', 'influenza', 'Influenza toscana presente a Padova negli anni giovanili di Mantegna.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('paolo-uccello-andrea-mantegna-influenza', 'artist', 'paolo-uccello', 'artist', 'andrea-mantegna', 'influenza', 'Influenza toscana presente a Padova negli anni giovanili di Mantegna, in particolare sul rigore nella costruzione prospettica.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('ludovico-gonzaga-andrea-mantegna-committenza', 'artist', 'ludovico-gonzaga', 'artist', 'andrea-mantegna', 'committenza', 'Invito a trasferirsi a Mantova nel 1460 come pittore di corte, ruolo mantenuto fino alla morte.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('filippo-lippi-niccolo-pizzolo-maestro-allievo', 'artist', 'filippo-lippi', 'artist', 'niccolo-pizzolo', 'maestro-allievo', 'Niccolò Pizzolo fu collaboratore di Filippo Lippi prima di lavorare alla cappella Ovetari.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('donatello-niccolo-pizzolo-maestro-allievo', 'artist', 'donatello', 'artist', 'niccolo-pizzolo', 'maestro-allievo', 'Niccolò Pizzolo fu collaboratore di Donatello prima di lavorare alla cappella Ovetari.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('elite-umanistica-padovana-andrea-mantegna-contaminazione', 'artist', 'elite-umanistica-padovana', 'artist', 'andrea-mantegna', 'contaminazione', 'Contatto con l''elite umanistica padovana che sviluppa in Mantegna una particolare passione antiquaria.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('francesco-squarcione-andrea-mantegna-maestro-allievo', 'artist', 'francesco-squarcione', 'artist', 'andrea-mantegna', 'maestro-allievo', 'Mantegna si forma nella scuola di Squarcione, da cui eredita certi elementi decorativi (festoni di frutti e foglie) ma poi evolve verso uno stile più naturalistico e monumentale.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('gregorio-correr-andrea-mantegna-committenza', 'artist', 'gregorio-correr', 'artist', 'andrea-mantegna', 'committenza', 'L''abate Gregorio Correr commissiona la Pala di San Zeno a Mantegna nel 1443 (nomina ad abate), con esecuzione tra il 1456 e il 1459.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('piero-della-francesca-andrea-mantegna-rielaborazione', 'artist', 'piero-della-francesca', 'artist', 'andrea-mantegna', 'rielaborazione', 'La Pala di Brera è citata come emblema di perfezione rinascimentale nella composizione simmetrica, confrontata con il sospeso classico-cristiano della Pala di San Zeno') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('ludovico-iii-gonzaga-andrea-mantegna-committenza', 'artist', 'ludovico-iii-gonzaga', 'artist', 'andrea-mantegna', 'committenza', 'Dal 1460 Ludovico III Gonzaga affida a Mantenga incarichi per la decorazione della cappella del castello di San Giorgio e altre opere mantovane') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('federico-gonzaga-andrea-mantegna-committenza', 'artist', 'federico-gonzaga', 'artist', 'andrea-mantegna', 'committenza', 'Successore di Ludovico III, continua la committenza con Mantegna dal 1478 al 1484') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('francesco-ii-gonzaga-andrea-mantegna-committenza', 'artist', 'francesco-ii-gonzaga', 'artist', 'andrea-mantegna', 'committenza', 'Nipote di Ludovico III, prosegue la committenza con Mantegna dal 1484 al 1519') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('san-sebastiano-versione-precedente-san-sebastiano-louvre-evoluzione', 'artist', 'san-sebastiano-versione-precedente', 'artist', 'san-sebastiano-louvre', 'evoluzione', 'Rispetto alla versione precedente della bellezza quattuoraria, questa versione appare più rigida e all''espressività germinale ribassata, con schema classico e influenza nordica') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('antichita-classica-andrea-mantegna-influenza', 'artist', 'antichita-classica', 'artist', 'andrea-mantegna', 'influenza', 'Riferimenti all''arte classica e al mondo antico nella rappresentazione anatomica e architettonica') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('jacopo-bellini-andrea-mantegna-influenza', 'artist', 'jacopo-bellini', 'artist', 'andrea-mantegna', 'influenza', 'Mantegna fu allievo di Jacopo Bellini e ne sposò la figlia Nicolosia.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('leon-battista-alberti-andrea-mantegna-influenza', 'artist', 'leon-battista-alberti', 'artist', 'andrea-mantegna', 'influenza', 'Influenza teorica e pratica sull''uso della prospettiva e sull''integrazione tra pittura e architettura, visibile nella struttura spaziale della Camera degli Sposi.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('jacopo-bellini-andrea-mantegna-maestro-allievo', 'artist', 'jacopo-bellini', 'artist', 'andrea-mantegna', 'maestro-allievo', 'Mantegna sposò Nicolosia, figlia di Jacopo Bellini, entrando così nella famiglia di pittori veneziani e assorbendo influenze venete unite allo stile padovano.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('vittore-da-feltre-cultura-della-corte-gonzaghesca-contaminazione', 'artist', 'vittore-da-feltre', 'artist', 'cultura-della-corte-gonzaghesca', 'contaminazione', 'I principi pedagogici umanisti di Vittore da Feltre influenzarono il programma culturale e celebrativo della Camera degli Sposi.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('francesco-sforza-ludovico-iii-gonzaga-influenza', 'artist', 'francesco-sforza', 'artist', 'ludovico-iii-gonzaga', 'influenza', 'Alleanza tra Milano e Mantova sancita dalla nomina a cardinale di Francesco Gonzaga, figlio di Ludovico, e celebrata nell''affresco della parete occidentale.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('donatello-andrea-mantegna-maestro-allievo', 'artist', 'donatello', 'artist', 'andrea-mantegna', 'maestro-allievo', 'Influenza stilistica e tecnica durante il soggiorno di Donatello a Padova') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('arte-classica-romana-andrea-mantegna-contaminazione', 'artist', 'arte-classica-romana', 'artist', 'andrea-mantegna', 'contaminazione', 'Imitazione dei bassorilievi romani nelle scene mitologiche e uso del mascherone classico') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('pala-di-san-zeno-camera-degli-sposi-evoluzione', 'work', 'pala-di-san-zeno', 'work', 'camera-degli-sposi', 'evoluzione', 'Evoluzione dell''impostazione architettonica dalla pala d''altare alla decorazione parietale complessa') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('isabella-deste-andrea-mantegna-committenza', 'artist', 'isabella-deste', 'artist', 'andrea-mantegna', 'committenza', 'Isabella d''Este commissiona a Mantegna opere per lo Studiolo, inclusa la decorazione con quadri a tema mitologico come il Parnaso (1497)') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('belliore-ferrara-e-federico-da-montefeltro-urbino-studiolo-di-isabella-deste-influenza', 'artist', 'belliore-ferrara-e-federico-da-montefeltro-urbino', 'work', 'studiolo-di-isabella-deste', 'influenza', 'Lo Studiolo di Isabella d''Este trae ispirazione dagli studioli preesistenti di Belliore a Ferrara e di Federico da Montefeltro a Urbino') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('papa-innocenzo-viii-andrea-mantegna-maestro-allievo', 'artist', 'papa-innocenzo-viii', 'artist', 'andrea-mantegna', 'maestro-allievo', 'Nel 1488 Papa Innocenzo VIII chiama Mantegna a Roma per realizzare affreschi nella Cappella Sistina (poi distrutti), permettendogli lo studio diretto dei modelli antichi') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('alfonso-daragona-pisanello-committenza', 'artist', 'alfonso-daragona', 'artist', 'pisanello', 'committenza', 'Alfonso d''Aragona chiamò Pisanello alla sua corte tra il 1448 e il 1449 come medagalista ufficiale') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('jan-van-eyck-artisti-napoletani-influenza', 'artist', 'jan-van-eyck', 'artist', 'artisti-napoletani', 'influenza', 'Le opere di Jan van Eyck presenti nelle collezioni di Alfonso d''Aragona furono studiate direttamente dagli artisti napoletani') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('jean-fouquet-rogier-van-der-weyden-maestro-allievo', 'artist', 'jean-fouquet', 'artist', 'rogier-van-der-weyden', 'maestro-allievo', 'I cartoni della Passione di Cristo realizzati da Jean Fouquet a Napoli furono utilizzati da Rogier van der Weyden per la serie di arazzi') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('antonio-rossellino-benedetto-da-maiano-influenza', 'artist', 'antonio-rossellino', 'artist', 'benedetto-da-maiano', 'influenza', 'Il Monumento funebre di Alfonso d''Aragona di Benedetto da Maiano è assai simile alla cappella del cardinale del Portogallo di Antonio Rossellino') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('filippo-brunelleschi-benedetto-da-maiano-influenza', 'artist', 'filippo-brunelleschi', 'artist', 'benedetto-da-maiano', 'influenza', 'La Sacrestia Vecchia di San Lorenzo di Brunelleschi è richiamata nel monumento funebre di Alfonso d''Aragona per gli equilibri plastici e le proporzioni anticlassiche') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
