INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('garganelli-ercole-de-roberti-committenza', 'artist', 'garganelli', 'artist', 'ercole-de-roberti', 'committenza', 'Commissione degli affreschi della cappella Garganelli nella cattedrale di San Pietro a Bologna dopo la morte di Francesco del Cossa.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('arte-veneta-ercole-de-roberti-contaminazione', 'artist', 'arte-veneta', 'artist', 'ercole-de-roberti', 'contaminazione', 'Il viaggio a Venezia e lo studio dell''arte locale (Bellini, Antonello da Messina) contaminarono lo stile ferrarese di Roberti, introducendo la luce naturale e la compostezza classica.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('donatello-ercole-de-roberti-influenza', 'artist', 'donatello', 'artist', 'ercole-de-roberti', 'influenza', 'L''opera di Ercole de'' Roberti è fortemente influenzata dalla potenza espressiva delle sculture tarde di Donatello, in particolare la Maddalena penitente, verso un''espressività deformante e anticlassica.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('donatello-niccolo-dellarca-influenza', 'artist', 'donatello', 'artist', 'niccolo-dellarca', 'influenza', 'Il naturalismo tardogotico d''Oltalpe e l''espressionismo delle sculture tarde di Donatello influenzarono profondamente il Compianto sul Cristo morto di Niccolò dell''Arca.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('nicola-pisano-niccolo-dellarca-rielaborazione', 'artist', 'nicola-pisano', 'artist', 'niccolo-dellarca', 'rielaborazione', 'Nel Compianto sul Cristo morto, Niccolò dell''Arca rielaborò i modelli di Nicola Pisano, in particolare quelli del Pulpito del Duomo di Siena, adattandoli a un linguaggio più moderno ed espressivo.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('cultura-napoletana-e-nordica-niccolo-dellarca-contaminazione', 'artist', 'cultura-napoletana-e-nordica', 'artist', 'niccolo-dellarca', 'contaminazione', 'Nato probabilmente a Bari, Niccolò dell''Arca entrò in contatto con la cultura cosmopolita della corte di Napoli e con le influenze nordiche e borgognone, che confluiscono nella sua opera bolognese.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('ercole-de-roberti-niccolo-dellarca-influenza', 'artist', 'ercole-de-roberti', 'artist', 'niccolo-dellarca', 'influenza', 'Le figure di Maria Maddalena e Maria di Cleofa negli affreschi di Ercole de'' Roberti (cappella Garganelli) trovano perfetta rispondenza nelle figure del Compianto sul Cristo morto di Niccolò dell''Arca, dimostrando una comune ricerca espressiva.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('borso-deste-francesco-del-cossa-ercole-de-roberti-committenza', 'artist', 'borso-deste', 'artist', 'francesco-del-cossa-ercole-de-roberti', 'committenza', 'Borso d''Este commissiona il ciclo dei Mesi per celebrare il proprio potere e la protezione astrale sulla città e sul suo governo') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('pellegrino-prisciani-ciclo-dei-mesi-influenza', 'artist', 'pellegrino-prisciani', 'work', 'ciclo-dei-mesi', 'influenza', 'Il programma iconografico del ciclo è ispirato alle teorie astrologiche di Pellegrino Prisciani, professore di astronomia all''università di Ferrara e bibliotecario degli Este') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('cosme-tura-ercole-de-roberti-maestro-allievo', 'artist', 'cosme-tura', 'artist', 'ercole-de-roberti', 'maestro-allievo', 'Ercole de'' Roberti fu allievo di Cosmè Tura nell''ambito dell''officina ferrarese') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('cosme-tura-maestro-degli-occhi-spalancati-maestro-allievo', 'artist', 'cosme-tura', 'artist', 'maestro-degli-occhi-spalancati', 'maestro-allievo', 'L''officina ferrarese diretta da Cosmè Tura comprendeva artisti come il Maestro degli Occhi Spalancanti, che lavoravano sotto la sua direzione al progetto iconografico unitario') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('borso-deste-officina-ferrarese-committenza', 'artist', 'borso-deste', 'period', 'officina-ferrarese', 'committenza', 'Commissione del ciclo di affreschi della Sala dei Mesi per magnificare la casata estense e celebrare il proprio governo') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('filosofia-neoplatonica-ciclo-di-affreschi-sala-dei-mesi-influenza', 'artist', 'filosofia-neoplatonica', 'work', 'ciclo-di-affreschi-sala-dei-mesi', 'influenza', 'L''iconografia del ciclo riflette i principi filosofici neoplatonici, con significati allegorici di natura morale e spirituale') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('astrologiazodiaco-trionfo-di-marzo-contaminazione', 'artist', 'astrologiazodiaco', 'artist', 'trionfo-di-marzo', 'contaminazione', 'Integrazione del tema del tracciare del tempo zodiacale con la celebrazione politica del duca') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('francesco-petrarca-francesco-del-cossa-influenza', 'artist', 'francesco-petrarca', 'artist', 'francesco-del-cossa', 'influenza', 'I Trionfi di Petrarca (in particolare il Trionfo di Venere) costituiscono la fonte letteraria diretta per l''iconografia della fascia superiore degli affreschi del Mese di Aprile') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('letteratura-arte-figurativa-contaminazione', 'artist', 'letteratura', 'artist', 'arte-figurativa', 'contaminazione', 'Il ciclo pittorico di Palazzo Schifanoia realizza visivamente i concetti poetici petrarcheschi, unendo arte e letteratura in una sintesi rinascimentale') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('lorenzo-ghiberti-filarete-maestro-allievo', 'artist', 'lorenzo-ghiberti', 'artist', 'filarete', 'maestro-allievo', 'Filarete si forma nella bottega di Ghiberti a Roma, acquisendo i principi dell''arte rinascimentale fiorentina') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('francesco-sforza-filarete-committenza', 'artist', 'francesco-sforza', 'artist', 'filarete', 'committenza', 'Francesco Sforza chiama Filarete a Milano nel 1450 per rinnovare l''architettura ducale secondo i modelli toscani') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('filarete-guiniforte-solari-influenza', 'artist', 'filarete', 'artist', 'guiniforte-solari', 'influenza', 'Collaborazione alla realizzazione dell''Ospedale Maggiore e della facciata del Duomo di Bergamo; Solari completa le opere di Filarete dopo la sua partenza') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('architettura-fiorentina-filarete-influenza', 'artist', 'architettura-fiorentina', 'artist', 'filarete', 'influenza', 'Introduzione dei moduli classici (ordine corinzio, proporzioni, simmetria) nell''architettura lombarda') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('tradizione-lombarda-filarete-contaminazione', 'artist', 'tradizione-lombarda', 'artist', 'filarete', 'contaminazione', 'Adattamento dei modelli toscani alle esigenze locali: uso del laterizio, mantenimento delle bifore ogivali, integrazione con il tessuto medievale esistente') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('leon-battista-alberti-filarete-contrasto', 'artist', 'leon-battista-alberti', 'artist', 'filarete', 'contrasto', 'Il trattato di Filarete differisce da quello di Alberti (scritto circa dieci anni prima) perché non considera caratteri topografici del luogo prescelto, ma impone lo sviluppo della città su dati di natura astronomica e simbolica, mentre Alberti si basa su rapporti armonici ed estetici naturali.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('leon-battista-alberti-filarete-evoluzione', 'artist', 'leon-battista-alberti', 'artist', 'filarete', 'evoluzione', 'Il trattato filaretiano rappresenta un''evoluzione/alternativa rispetto alla trattatistica albertiana, introducendo elementi di urbanistica simbolica e astronomica nella progettazione delle città ideali.') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
INSERT INTO public.connections (id, source_type, source_id, target_type, target_id, kind, description) VALUES ('guiniforte-solari-giovanni-antonio-amadeo-maestro-allievo', 'artist', 'guiniforte-solari', 'artist', 'giovanni-antonio-amadeo', 'maestro-allievo', 'Amadeo succede a Solari nella direzione dei lavori della Certosa dopo la sua morte, continuando e modificando il progetto originale') ON CONFLICT (id) DO UPDATE SET description = EXCLUDED.description;
